reset_state()

logger = function(ctx)
    if type(ctx) == "table" and type(ctx.log) == "table" then
        return ctx.log
    end
    return log
end

local function task_api()
    if type(task) == "table" then
        return task
    end
    return nil
end

local function share_api(ctx)
    local sys_api = type(ctx) == "table" and ctx.sys or sys
    if type(sys_api) == "table"
        and type(sys_api.set_share) == "function"
        and type(sys_api.get_share) == "function"
    then
        return sys_api
    end
    return nil
end

local function nav_worker_key(suffix)
    if type(state.nav_worker_share_prefix) ~= "string" or state.nav_worker_share_prefix == "" then
        return nil
    end
    return state.nav_worker_share_prefix .. ":" .. tostring(suffix or "")
end

local function nav_worker_set(ctx, suffix, value)
    local sys_api = share_api(ctx)
    local key = nav_worker_key(suffix)
    if not sys_api or not key then
        return false
    end
    sys_api.set_share(key, value)
    return true
end

local function nav_worker_get(ctx, suffix)
    local sys_api = share_api(ctx)
    local key = nav_worker_key(suffix)
    if not sys_api or not key then
        return nil
    end
    return sys_api.get_share(key)
end

local function nav_worker_clear_shares(ctx)
    local sys_api = share_api(ctx)
    if not sys_api or type(state.nav_worker_share_prefix) ~= "string" or state.nav_worker_share_prefix == "" then
        return
    end

    local suffixes = {
        "stop",
        "paused",
        "target_version",
        "target_x",
        "target_y",
        "target_source",
        "target_path_index",
        "move_interval_ms",
        "mode",
        "route_version",
        "route_count",
        "route_arrive_distance",
        "route_switch_ms",
        "route_direction",
        "route_stuck_skip_ms",
        "route_progress_reset_distance",
        "worker_status",
        "last_error",
        "last_issue_at",
        "last_target_x",
        "last_target_y",
        "last_target_version",
        "heartbeat_at"
    }

    for _, suffix in ipairs(suffixes) do
        sys_api.set_share(state.nav_worker_share_prefix .. ":" .. suffix, nil)
    end
    for index = 1, M.NAV_WORKER_ROUTE_POINT_SHARE_LIMIT do
        sys_api.set_share(state.nav_worker_share_prefix .. ":route_point_" .. index .. "_x", nil)
        sys_api.set_share(state.nav_worker_share_prefix .. ":route_point_" .. index .. "_y", nil)
        sys_api.set_share(state.nav_worker_share_prefix .. ":route_point_" .. index .. "_z", nil)
        sys_api.set_share(state.nav_worker_share_prefix .. ":route_point_" .. index .. "_index", nil)
    end
end

local function nav_worker_target_signature(target)
    if type(target) ~= "table" then
        return nil
    end

    return table.concat({
        tostring(target.source or ""),
        tostring(math.floor((tonumber(target.x) or 0) * 10 + 0.5)),
        tostring(math.floor((tonumber(target.y) or 0) * 10 + 0.5)),
        tostring(tonumber(target.path_index) or 0)
    }, "|")
end

function now_ms(ctx)
    local sys_api = type(ctx) == "table" and ctx.sys or sys
    if type(sys_api) == "table" and type(sys_api.time) == "function" then
        return sys_api.time()
    end
    return 0
end

local function sleep_ms(ctx, delay_ms)
    local sys_api = type(ctx) == "table" and ctx.sys or sys
    if type(sys_api) == "table" and type(sys_api.sleep) == "function" then
        sys_api.sleep(math.max(0, tonumber(delay_ms) or 0))
    end
end

local function safe_call(fn, ...)
    if type(fn) ~= "function" then
        return false, "target is not callable"
    end
    return pcall(fn, ...)
end

local function as_number(value)
    if type(value) == "number" then
        return value
    end
    if type(value) == "string" then
        return tonumber(value)
    end
    return nil
end

local function trim(value)
    return tostring(value or ""):gsub("^%s+", ""):gsub("%s+$", "")
end

local function normalize_monster_name(value)
    local text = trim(value)
    if text == "" then
        return nil
    end
    text = text:gsub("%s+", "")
    if text == "" then
        return nil
    end
    return text
end

local function is_force_kite_monster_name(value)
    local target_name = normalize_monster_name(value)
    if target_name == nil or type(M.FORCE_KITE_MONSTER_NAMES) ~= "table" then
        return false, target_name
    end

    if M.FORCE_KITE_MONSTER_NAMES[target_name] == true then
        return true, target_name
    end

    for candidate_name, enabled in pairs(M.FORCE_KITE_MONSTER_NAMES) do
        if enabled == true and normalize_monster_name(candidate_name) == target_name then
            return true, candidate_name
        end
    end

    return false, target_name
end

local function distance_2d(x1, y1, x2, y2)
    local dx = (tonumber(x1) or 0) - (tonumber(x2) or 0)
    local dy = (tonumber(y1) or 0) - (tonumber(y2) or 0)
    return math.sqrt(dx * dx + dy * dy)
end

local function is_valid_world_point(point)
    if type(point) ~= "table" then
        return false
    end

    local x = tonumber(point.x)
    local y = tonumber(point.y)
    if x == nil or y == nil then
        return false
    end

    if math.abs(x) < 0.001 and math.abs(y) < 0.001 then
        return false
    end

    return true
end

function M.format_world_point_for_log(point)
    if type(point) ~= "table" then
        return tostring(point)
    end

    return string.format(
        "x=%s y=%s z=%s source=%s raw=%s",
        tostring(point.x),
        tostring(point.y),
        tostring(point.z),
        tostring(point.source or ""),
        type(point.raw) == "table" and string.format(
            "x=%s y=%s z=%s",
            tostring(point.raw.x or point.raw.X or point.raw.posX or point.raw.PosX),
            tostring(point.raw.y or point.raw.Y or point.raw.posY or point.raw.PosY),
            tostring(point.raw.z or point.raw.Z or point.raw.posZ or point.raw.PosZ)
        ) or tostring(point.raw or "")
    )
end

local function log_throttled(ctx, key, level, interval_ms, message)
    local current_time = now_ms(ctx)
    local last_time = tonumber(state.last_logs[key]) or 0
    if current_time - last_time < (tonumber(interval_ms) or LOG_THROTTLE_MS) then
        return
    end

    state.last_logs[key] = current_time
    local log_api = logger(ctx)
    local log_fn = type(log_api[level]) == "function" and log_api[level] or log_api.info
    log_fn(message)
end

local function nav_api(ctx)
    if type(ctx) == "table" and type(ctx.nav) == "table" then
        return ctx.nav
    end
    return nav
end

function M.nav_debug_state_text(ctx)
    local nav_mod = nav_api(ctx)
    if type(nav_mod) == "table" and type(nav_mod.debug_state) == "function" then
        return tostring(nav_mod.debug_state() or "")
    end
    return ""
end

function M.format_last_main_task_call_debug(current_time)
    current_time = tonumber(current_time) or 0
    local started_at = tonumber(state.last_main_task_call_started_at) or 0
    local age_ms = started_at > 0 and math.max(0, current_time - started_at) or -1
    return string.format(
        "stage=%s phase=%s result=%s age_ms=%s elapsed_ms=%s queries=%s detail=%s nav=%s ui=%s",
        tostring(state.last_main_task_call_stage or ""),
        tostring(state.last_main_task_call_phase or ""),
        tostring(state.last_main_task_call_result or ""),
        age_ms >= 0 and tostring(age_ms) or "",
        tostring(tonumber(state.last_main_task_call_elapsed_ms) or 0),
        tostring(state.last_main_task_call_queries or ""),
        tostring(state.last_main_task_call_detail or ""),
        tostring(state.last_main_task_call_nav or ""),
        tostring(state.last_main_task_call_ui or "")
    )
end

local function ensure_nav_ready(ctx, current_time)
    local nav_mod = nav_api(ctx)
    if type(nav_mod) ~= "table" then
        return false, "nav module is unavailable."
    end

    if type(nav_mod.is_initialized) == "function" and nav_mod.is_initialized() then
        return true
    end

    current_time = tonumber(current_time) or now_ms(ctx)
    if current_time < (tonumber(state.next_nav_retry_at) or 0) then
        return false, state.last_nav_error or "nav init is waiting for retry."
    end

    state.next_nav_retry_at = current_time + NAV_RETRY_INTERVAL_MS

    local init_ok, init_err
    if type(nav_mod.ensure_initialized) == "function" then
        init_ok, init_err = nav_mod.ensure_initialized(
            type(ctx) == "table" and ctx.process_name or nil,
            type(ctx) == "table" and ctx.runtime_mode or nil
        )
    elseif type(nav_mod.init) == "function" then
        init_ok, init_err = nav_mod.init(
            type(ctx) == "table" and ctx.process_name or nil,
            type(ctx) == "table" and ctx.runtime_mode or nil
        )
    else
        init_ok, init_err = false, "nav init entry is unavailable."
    end

    if init_ok then
        state.last_nav_error = nil
        state.next_input_prepare_at = 0
        return true
    end

    local nav_detail = M.nav_debug_state_text(ctx)
    state.last_nav_error = tostring(init_err or "nav init failed.")
    if nav_detail ~= "" then
        state.last_nav_error = state.last_nav_error .. " | nav=" .. nav_detail
    end
    return false, state.last_nav_error
end

local function start_nav_worker(ctx, current_time, force_enabled)
    if LEVELING_USE_NAV_WORKER ~= true and force_enabled ~= true then
        state.nav_worker_force_direct = true
        return false, "leveling nav worker disabled."
    end

    local task_mod = task_api()
    local sys_api = share_api(ctx)
    if type(task_mod) ~= "table" or type(task_mod.run) ~= "function" or not sys_api then
        state.nav_worker_force_direct = true
        return false, "task.run or sys share API is unavailable."
    end

    if tonumber(state.nav_worker_task_id) and tonumber(state.nav_worker_task_id) > 0 then
        return true
    end

    current_time = tonumber(current_time) or now_ms(ctx)
    local current_task_id = type(task_mod.id) == "function" and tonumber(task_mod.id()) or 0
    state.nav_worker_share_prefix = string.format(
        "%s_%d_%d",
        NAV_WORKER_SHARE_PREFIX_BASE,
        tonumber(current_time) or 0,
        tonumber(current_task_id) or 0
    )
    state.nav_worker_target_version = 0
    state.nav_worker_target_signature = nil
    state.nav_worker_paused = true
    state.nav_worker_last_status = nil
    state.nav_worker_last_issue_at = 0
    state.nav_worker_last_error = nil
    state.nav_worker_next_check_at = current_time + NAV_WORKER_CHECK_INTERVAL_MS
    state.nav_worker_force_direct = false
    nav_worker_clear_shares(ctx)
    nav_worker_set(ctx, "stop", false)
    nav_worker_set(ctx, "paused", true)
    nav_worker_set(ctx, "target_version", 0)
    nav_worker_set(ctx, "move_interval_ms", MOVE_INTERVAL_MS)
    nav_worker_set(ctx, "mode", "target")

    local worker_id = task_mod.run("scripts/AvePointLevelingNavWorker.lua", {
        name = "AvePointLevelingNavWorker",
        priority = "high",
        share_prefix = tostring(state.nav_worker_share_prefix),
        process_name = tostring(type(ctx) == "table" and ctx.process_name or ""),
        runtime_mode = tostring(type(ctx) == "table" and ctx.runtime_mode or "")
    })
    if type(worker_id) ~= "number" or worker_id <= 0 then
        state.nav_worker_share_prefix = nil
        state.nav_worker_force_direct = true
        return false, "task.run returned invalid worker id."
    end

    state.nav_worker_task_id = worker_id
    logger(ctx).info(string.format(
        "[Leveling] nav worker started | task_id=%d share=%s",
        worker_id,
        tostring(state.nav_worker_share_prefix)
    ))
    return true
end

local function stop_nav_worker(ctx)
    nav_worker_set(ctx, "stop", true)
    nav_worker_set(ctx, "paused", true)

    local task_mod = task_api()
    local worker_id = tonumber(state.nav_worker_task_id) or 0
    if worker_id > 0 and type(task_mod) == "table" and type(task_mod.stop) == "function" then
        pcall(task_mod.stop, worker_id)
    end
    if type(task_mod) == "table" and type(task_mod.cleanup) == "function" then
        pcall(task_mod.cleanup)
    end

    nav_worker_clear_shares(ctx)
    state.nav_worker_task_id = 0
    state.nav_worker_share_prefix = nil
    state.nav_worker_target_version = 0
    state.nav_worker_target_signature = nil
    state.nav_worker_paused = true
    state.nav_worker_last_status = nil
    state.nav_worker_last_issue_at = 0
    state.nav_worker_last_error = nil
    state.nav_worker_next_check_at = 0
    state.nav_worker_force_direct = false
    state.nav_worker_target_published_at = 0
    state.nav_worker_target_path_index = 0
    state.nav_worker_path_route_signature = nil
    state.nav_worker_path_route_version = 0
    state.nav_worker_path_route_window_start = 0
    state.nav_worker_path_route_window_end = 0
    state.nav_worker_path_route_direction = 1
    state.nav_worker_path_route_path_signature = nil
end

local function ensure_nav_worker_running(ctx, current_time, force_enabled)
    if state.nav_worker_force_direct == true and force_enabled ~= true then
        return false, "nav worker direct fallback is enabled."
    end

    current_time = tonumber(current_time) or now_ms(ctx)
    if current_time < (tonumber(state.nav_worker_next_check_at) or 0)
        and tonumber(state.nav_worker_task_id) and tonumber(state.nav_worker_task_id) > 0
    then
        return true
    end

    state.nav_worker_next_check_at = current_time + NAV_WORKER_CHECK_INTERVAL_MS

    local task_mod = task_api()
    local worker_id = tonumber(state.nav_worker_task_id) or 0
    if worker_id <= 0 then
        return start_nav_worker(ctx, current_time, force_enabled)
    end

    if type(task_mod) == "table" and type(task_mod.status) == "function" then
        local status = task_mod.status(worker_id)
        if status ~= nil
            and status ~= "running"
            and status ~= "pending"
            and status ~= "paused"
        then
            local info = type(task_mod.info) == "function" and task_mod.info(worker_id) or nil
            local detail = type(info) == "table" and info.error or status
            log_throttled(ctx, "nav_worker_restart", "warn", LOG_THROTTLE_MS,
                "[Leveling] nav worker stopped unexpectedly, restarting: " .. tostring(detail))
            stop_nav_worker(ctx)
            state.nav_worker_next_check_at = current_time + NAV_WORKER_RESTART_INTERVAL_MS
            return start_nav_worker(ctx, current_time, force_enabled)
        end
    end

    local heartbeat_at = tonumber(nav_worker_get(ctx, "heartbeat_at")) or 0
    if heartbeat_at > 0 and current_time - heartbeat_at > NAV_WORKER_HEARTBEAT_STALE_MS then
        log_throttled(ctx, "nav_worker_stale", "warn", LOG_THROTTLE_MS,
            "[Leveling] nav worker heartbeat stale, restarting.")
        stop_nav_worker(ctx)
        state.nav_worker_next_check_at = current_time + NAV_WORKER_RESTART_INTERVAL_MS
        return start_nav_worker(ctx, current_time, force_enabled)
    end

    return true
end

local function sync_nav_worker_feedback(ctx, current_time)
    if LEVELING_USE_NAV_WORKER ~= true
        and (tonumber(state.nav_worker_task_id) == nil or tonumber(state.nav_worker_task_id) <= 0)
    then
        return
    end

    current_time = tonumber(current_time) or now_ms(ctx)
    if tonumber(state.nav_worker_task_id) == nil or tonumber(state.nav_worker_task_id) <= 0 then
        return
    end

    local worker_status = tostring(nav_worker_get(ctx, "worker_status") or "")
    if worker_status ~= "" and worker_status ~= tostring(state.nav_worker_last_status or "") then
        state.nav_worker_last_status = worker_status
        log_throttled(ctx, "nav_worker_status_" .. worker_status, "info", LOG_THROTTLE_MS,
            "[Leveling] nav worker status | " .. worker_status)
    end

    local last_issue_at = tonumber(nav_worker_get(ctx, "last_issue_at")) or 0
    if last_issue_at > (tonumber(state.nav_worker_last_issue_at) or 0) then
        state.nav_worker_last_issue_at = last_issue_at
        state.last_move_call_at = last_issue_at
        state.move_guard_until = math.max(
            tonumber(state.move_guard_until) or 0,
            last_issue_at + MOVE_COMBAT_GUARD_MS
        )
        log_throttled(ctx, "move_call_issued", "info", 1500, string.format(
            "[Leveling] MoveTo issued | target=%.2f, %.2f source=%s path_index=%d interval_ms=%d via=nav_worker worker_mode=%s route_index=%d/%d route_dir=%d route_distance=%.2f route_point=%.2f, %.2f original_index=%d",
            tonumber(nav_worker_get(ctx, "last_target_x")) or 0,
            tonumber(nav_worker_get(ctx, "last_target_y")) or 0,
            tostring(nav_worker_get(ctx, "target_source") or ""),
            tonumber(nav_worker_get(ctx, "target_path_index")) or 0,
            tonumber(nav_worker_get(ctx, "move_interval_ms")) or 0,
            tostring(nav_worker_get(ctx, "last_route_mode") or ""),
            tonumber(nav_worker_get(ctx, "last_route_index")) or 0,
            tonumber(nav_worker_get(ctx, "last_route_count")) or 0,
            tonumber(nav_worker_get(ctx, "last_route_direction")) or 0,
            tonumber(nav_worker_get(ctx, "last_route_distance")) or 0,
            tonumber(nav_worker_get(ctx, "last_route_point_x")) or 0,
            tonumber(nav_worker_get(ctx, "last_route_point_y")) or 0,
            tonumber(nav_worker_get(ctx, "last_route_original_index")) or 0
        ))
    end

    local last_error = trim(nav_worker_get(ctx, "last_error") or "")
    if last_error ~= "" and last_error ~= tostring(state.nav_worker_last_error or "") then
        state.nav_worker_last_error = last_error
        log_throttled(ctx, "nav_worker_last_error", "warn", LOG_THROTTLE_MS,
            "[Leveling] nav worker error: " .. tostring(last_error))
    elseif last_error == "" then
        state.nav_worker_last_error = nil
    end
end

local function hold_navigation(ctx, current_time, reason)
    current_time = tonumber(current_time) or now_ms(ctx)
    if tonumber(state.nav_worker_task_id) and tonumber(state.nav_worker_task_id) > 0 then
        nav_worker_set(ctx, "paused", true)
        state.nav_worker_paused = true
    end
    state.next_move_at = current_time
    state.last_move_call_at = 0
    if reason then
        log_throttled(ctx, "nav_hold_" .. tostring(reason), "info", LOG_THROTTLE_MS,
            "[Leveling] navigation hold | reason=" .. tostring(reason))
    end
end

function M.stabilize_navigation_for_interaction(ctx, current_time, reason, player_x, player_y)
    current_time = tonumber(current_time) or now_ms(ctx)
    hold_navigation(ctx, current_time, reason)
    release_async_combat_inputs(ctx, current_time, true)
    state.pause_combat_until = math.max(
        tonumber(state.pause_combat_until) or 0,
        current_time + math.max(900, POST_UI_PAUSE_MS)
    )
    state.next_follow_move_pulse_at = math.max(
        tonumber(state.next_follow_move_pulse_at) or 0,
        current_time + FOLLOW_MOVE_PULSE_INTERVAL_MS
    )

    local stop_x = tonumber(player_x)
    local stop_y = tonumber(player_y)
    if stop_x == nil or stop_y == nil then
        local nav_mod = nav_api(ctx)
        if type(nav_mod) == "table" and type(nav_mod.player_pos) == "function" then
            local pos_ok, current_x, current_y = safe_call(nav_mod.player_pos)
            if pos_ok then
                stop_x = tonumber(current_x)
                stop_y = tonumber(current_y)
            end
        end
    end

    local nav_mod = nav_api(ctx)
    if stop_x ~= nil
        and stop_y ~= nil
        and type(nav_mod) == "table"
        and type(nav_mod.move_call) == "function"
    then
        local move_ok, move_result, move_err = safe_call(nav_mod.move_call, stop_x, stop_y, {
            move_call_mouse_sync = {
                enabled = false
            }
        })
        if move_ok and move_result ~= false then
            log_throttled(ctx, "interaction_nav_hard_stop_" .. tostring(reason), "info", LOG_THROTTLE_MS, string.format(
                "[Leveling] interaction navigation hard stop issued | reason=%s pos=%.2f, %.2f",
                tostring(reason or ""),
                stop_x,
                stop_y
            ))
        else
            log_throttled(ctx, "interaction_nav_hard_stop_failed_" .. tostring(reason), "info", LOG_THROTTLE_MS, string.format(
                "[Leveling] interaction navigation hard stop failed | reason=%s pos=%.2f, %.2f err=%s",
                tostring(reason or ""),
                stop_x,
                stop_y,
                tostring(move_ok and move_err or move_result)
            ))
        end
    end
end

function M.pause_task_combat_kite_route_worker(ctx)
    if state.task_combat_kite_route_worker_active ~= true then
        return
    end
    nav_worker_set(ctx, "paused", true)
    nav_worker_set(ctx, "mode", "target")
    state.nav_worker_paused = true
    state.task_combat_kite_route_worker_active = false
    state.task_combat_kite_route_worker_signature = nil
end

local function read_player_pos(ctx)
    local nav_mod = nav_api(ctx)
    if type(nav_mod) ~= "table" or type(nav_mod.player_pos) ~= "function" then
        return nil, nil, nil, "nav.player_pos is unavailable."
    end
    return nav_mod.player_pos()
end

local function read_player_info(ctx)
    local nav_mod = nav_api(ctx)
    if type(nav_mod) ~= "table" or type(nav_mod.player_info) ~= "function" then
        return nil, "nav.player_info is unavailable."
    end
    return nav_mod.player_info()
end

local function extract_player_hp_values(info)
    if type(info) ~= "table" then
        return nil, nil, nil, nil
    end

    local hp, hp_source = nil, nil
    if type(avepoint_extract_player_hp) == "function" then
        hp, hp_source = avepoint_extract_player_hp(info)
    end

    local max_hp, max_hp_source = nil, nil
    if type(avepoint_find_named_number) == "function" then
        max_hp, max_hp_source = avepoint_find_named_number(info, {
            "maxHp", "MaxHp", "maxHP", "MaxHP",
            "maximumHp", "MaximumHp", "maximumHP", "MaximumHP",
            "maxHealth", "MaxHealth", "maximumHealth", "MaximumHealth",
            "maxLife", "MaxLife", "maximumLife", "MaximumLife",
            "maxBlood", "MaxBlood", "maximumBlood", "MaximumBlood",
            "\u{6700}\u{5927}\u{8840}\u{91CF}", "\u{8840}\u{91CF}\u{4E0A}\u{9650}"
        }, 4)
    end

    if hp == nil or max_hp == nil or max_hp <= 0 then
        return hp, max_hp, nil, hp_source or max_hp_source
    end

    return hp, max_hp, hp / max_hp, string.format("%s/%s", tostring(hp_source or ""), tostring(max_hp_source or ""))
end

local function refresh_player_status(ctx, current_time, force_refresh)
    current_time = tonumber(current_time) or now_ms(ctx)
    if force_refresh ~= true and current_time < (tonumber(state.next_player_info_refresh_at) or 0) then
        return state.cached_player_info, state.cached_player_hp, state.cached_player_max_hp, state.cached_player_hp_ratio
    end

    state.next_player_info_refresh_at = current_time + PLAYER_INFO_REFRESH_INTERVAL_MS

    local info, info_err = read_player_info(ctx)
    if type(info) ~= "table" then
        log_throttled(ctx, "player_info_failed", "warn", LOG_THROTTLE_MS,
            "[Leveling] player info unavailable: " .. tostring(info_err))
        return state.cached_player_info, state.cached_player_hp, state.cached_player_max_hp, state.cached_player_hp_ratio
    end

    state.cached_player_info = info
    state.last_player_info_at = current_time
    state.cached_player_hp, state.cached_player_max_hp, state.cached_player_hp_ratio, state.cached_player_hp_source =
        extract_player_hp_values(info)
    return state.cached_player_info, state.cached_player_hp, state.cached_player_max_hp, state.cached_player_hp_ratio
end

normalize_map_name = function(value)
    if type(M._leveling_policy) == "table"
        and type(M._leveling_policy.normalize_map_name) == "function"
    then
        return M._leveling_policy.normalize_map_name(value)
    end
    local text = trim(value)
    if text == "" then
        return nil
    end
    return text
end

function M.normalize_task_title_key(value)
    local text = normalize_map_name(value)
    if text == nil then
        return nil
    end
    text = trim(text:gsub("^主线%s*", ""))
    text = trim(text:gsub("^涓荤嚎%s*", ""))
    text = trim(text:gsub("^涓荤窔%s*", ""))
    text = trim(text:gsub("^Main%s*Quest%s*[:锛?-]*%s*", ""))
    if text == "" then
        return nil
    end
    return text
end

M.TASK_PANEL_ENTRY_CACHE_FRESH_MS = 1800

function M.copy_task_panel_entry(entry)
    if type(entry) ~= "table" then
        return nil
    end
    return {
        title = trim(entry.title or ""),
        raw_text = trim(entry.raw_text or ""),
        kind = trim(entry.kind or ""),
        detail = trim(entry.detail or ""),
        detail_texts = type(entry.detail_texts) == "table" and entry.detail_texts or nil,
        detail_debug_candidates = type(entry.detail_debug_candidates) == "table" and entry.detail_debug_candidates or nil,
        title_addr = tonumber(entry.title_addr) or entry.title_addr,
        title_name = tostring(entry.title_name or ""),
        title_fullname = tostring(entry.title_fullname or ""),
        button_addr = tonumber(entry.button_addr) or entry.button_addr,
        button_x = tonumber(entry.button_x) or tonumber(entry.x),
        button_y = tonumber(entry.button_y) or tonumber(entry.y),
        button_name = tostring(entry.button_name or ""),
        button_fullname = tostring(entry.button_fullname or ""),
        button_kind = tostring(entry.button_kind or ""),
        button_anchor_score = tonumber(entry.button_anchor_score) or 0,
        x = tonumber(entry.x),
        y = tonumber(entry.y)
    }
end

function M.remember_task_panel_entry(entry, current_time)
    local cached = M.copy_task_panel_entry(entry)
    if type(cached) ~= "table" then
        return nil
    end
    state.last_task_panel_entry = cached
    state.last_task_panel_task_name = trim(cached.title ~= "" and cached.title or cached.raw_text)
    state.last_task_panel_task_detail = trim(cached.detail or "")
    state.last_task_panel_updated_at = tonumber(current_time) or 0
    return cached
end

function M.get_cached_task_panel_entry(current_time, preferred_task_name)
    local cached = state.last_task_panel_entry
    if type(cached) ~= "table" then
        return nil
    end
    local updated_at = tonumber(state.last_task_panel_updated_at) or 0
    if updated_at <= 0
        or ((tonumber(current_time) or 0) - updated_at) > (tonumber(M.TASK_PANEL_ENTRY_CACHE_FRESH_MS) or 1800)
    then
        return nil
    end

    local preferred_key = M.normalize_task_title_key(preferred_task_name)
    local title_key = M.normalize_task_title_key(cached.title ~= "" and cached.title or cached.raw_text)
    local detail_key = normalize_map_name(cached.detail)
    local kind = tostring(cached.kind or "")

    if preferred_key == nil then
        return M.copy_task_panel_entry(cached)
    end

    if title_key ~= nil and (
        title_key == preferred_key
        or title_key:find(preferred_key, 1, true) ~= nil
        or preferred_key:find(title_key, 1, true) ~= nil
    ) then
        return M.copy_task_panel_entry(cached)
    end

    if detail_key ~= nil and (
        detail_key == preferred_key
        or detail_key:find(preferred_key, 1, true) ~= nil
        or preferred_key:find(detail_key, 1, true) ~= nil
    ) then
        return M.copy_task_panel_entry(cached)
    end

    if kind:find("主线", 1, true) ~= nil or kind:find("涓荤嚎", 1, true) ~= nil then
        return M.copy_task_panel_entry(cached)
    end

    return nil
end

function M.extract_main_task_button_target(target_like)
    if type(target_like) ~= "table" then
        return nil
    end

    local source = type(target_like._main_task_clicked_target) == "table"
        and target_like._main_task_clicked_target
        or target_like

    local kind = tostring(source.kind or source.button_kind or target_like.button_kind or "")
    local addr = tonumber(source.addr or source.button_addr or target_like.button_addr)
    local x = tonumber(source.x or source.button_x or target_like.button_x or target_like.x)
    local y = tonumber(source.y or source.button_y or target_like.button_y or target_like.y)
    local name = tostring(source.name or source.button_name or target_like.button_name or "")
    local fullname = tostring(
        source.fullname
            or source.Fullname
            or source.button_fullname
            or target_like.button_fullname
            or ""
    )
    if addr == nil or addr == 0 or x == nil or y == nil then
        return nil
    end

    local target = {
        kind = "button",
        addr = addr,
        name = name,
        text = tostring(source.text or target_like.text or ""),
        fullname = fullname,
        x = x,
        y = y,
        related_text = tostring(
            source.related_text
                or target_like.title
                or target_like.raw_text
                or ""
        ),
        related_distance = tonumber(source.related_distance),
        distance = tonumber(source.distance)
    }

    local buttons = type(M._leveling_buttons) == "table" and M._leveling_buttons or nil
    if type(buttons) == "table" and type(buttons.target_matches_slot) == "function" then
        local ok = select(1, buttons.target_matches_slot("main_task", target))
        if not ok then
            return nil
        end
    else
        local identity = (fullname .. " " .. name):lower()
        local is_button = kind == "button"
            or identity:find("taskitem_c.widgettree.taskbtn", 1, true) ~= nil
        if not is_button then
            return nil
        end
    end

    return target
end

function M.copy_main_task_button_cache_fields(cached)
    if type(cached) ~= "table" then
        return nil
    end

    return {
        kind = cached.kind,
        addr = cached.addr,
        name = cached.name,
        fullname = cached.fullname,
        x = cached.x,
        y = cached.y,
        text = cached.text,
        related_text = cached.related_text,
        related_distance = cached.related_distance,
        captured_at = cached.captured_at,
        source = cached.source,
        hint_ratio_x = cached.hint_ratio_x,
        hint_ratio_y = cached.hint_ratio_y,
        pid = cached.pid,
        session_key = cached.session_key,
        query = cached.query,
        query_key = cached.query_key,
        cache_context = cached.cache_context
    }
end

M._button_session_state = nil
M._button_session_state_loaded = false

function M.default_button_session_state()
    return {
        version = 1,
        main_task = nil,
        dialogue_jump = nil,
        treasure_task = nil,
        interaction_prompt = nil,
        task_entry_send = nil,
        treasure_restart_portal = nil,
        treasure_exit_portal = nil
    }
end

function M.serialize_button_session_lua_scalar(value)
    local value_type = type(value)
    if value_type == "nil" then
        return "nil"
    end
    if value_type == "number" or value_type == "boolean" then
        return tostring(value)
    end
    return string.format("%q", tostring(value))
end

function M.serialize_button_session_lua_table(value, indent)
    if type(value) ~= "table" then
        return M.serialize_button_session_lua_scalar(value)
    end

    indent = indent or 0
    local next_indent = indent + 2
    local lines = { "{" }
    local keys = {}
    for key in pairs(value) do
        keys[#keys + 1] = key
    end
    table.sort(keys, function(left, right)
        return tostring(left) < tostring(right)
    end)

    for _, key in ipairs(keys) do
        local rendered_key
        if type(key) == "string" and key:match("^[A-Za-z_][A-Za-z0-9_]*$") then
            rendered_key = key
        else
            rendered_key = "[" .. M.serialize_button_session_lua_scalar(key) .. "]"
        end
        lines[#lines + 1] = string.format(
            "%s%s = %s,",
            string.rep(" ", next_indent),
            rendered_key,
            M.serialize_button_session_lua_table(value[key], next_indent)
        )
    end

    lines[#lines + 1] = string.rep(" ", indent) .. "}"
    return table.concat(lines, "\n")
end

function M.load_button_session_state()
    local chunk = loadfile(M.BUTTON_SESSION_STATE_FILE_PATH)
    if not chunk then
        return M.default_button_session_state()
    end

    local ok, data = pcall(chunk)
    if not ok or type(data) ~= "table" then
        return M.default_button_session_state()
    end

    if type(data.main_task) ~= "table" then
        data.main_task = nil
    end
    if type(data.dialogue_jump) ~= "table" then
        data.dialogue_jump = nil
    end
    if type(data.treasure_task) ~= "table" then
        data.treasure_task = nil
    end
    if type(data.interaction_prompt) ~= "table" then
        data.interaction_prompt = nil
    end
    if type(data.task_entry_send) ~= "table" then
        data.task_entry_send = nil
    end
    if type(data.treasure_restart_portal) ~= "table" then
        data.treasure_restart_portal = nil
    end
    if type(data.treasure_exit_portal) ~= "table" then
        data.treasure_exit_portal = nil
    end
    data.version = tonumber(data.version) or 1
    return data
end

function M.ensure_button_session_state()
    if M._button_session_state_loaded ~= true then
        M._button_session_state = M.load_button_session_state()
        M._button_session_state_loaded = true
    end
    if type(M._button_session_state) ~= "table" then
        M._button_session_state = M.default_button_session_state()
    end
    return M._button_session_state
end

function M.save_button_session_state()
    local data = M.ensure_button_session_state()
    local file, err = io.open(M.BUTTON_SESSION_STATE_FILE_PATH, "w")
    if not file then
        return false, err
    end
    file:write("return ")
    file:write(M.serialize_button_session_lua_table(data, 0))
    file:write("\n")
    file:close()
    return true
end

M._recipe_progress_state = nil
M._recipe_progress_state_loaded = false

function M.default_recipe_progress_state()
    return {
        version = 1,
        packages = {}
    }
end

function M.load_recipe_progress_state()
    local chunk = loadfile(M.RECIPE_PROGRESS_STATE_FILE_PATH)
    if not chunk then
        return M.default_recipe_progress_state()
    end

    local ok, data = pcall(chunk)
    if not ok or type(data) ~= "table" then
        return M.default_recipe_progress_state()
    end
    if type(data.packages) ~= "table" then
        data.packages = {}
    end
    data.version = tonumber(data.version) or 1
    return data
end

function M.ensure_recipe_progress_state()
    if M._recipe_progress_state_loaded ~= true then
        M._recipe_progress_state = M.load_recipe_progress_state()
        M._recipe_progress_state_loaded = true
    end
    if type(M._recipe_progress_state) ~= "table" then
        M._recipe_progress_state = M.default_recipe_progress_state()
    end
    if type(M._recipe_progress_state.packages) ~= "table" then
        M._recipe_progress_state.packages = {}
    end
    return M._recipe_progress_state
end

function M.save_recipe_progress_state()
    local data = M.ensure_recipe_progress_state()
    local file, err = io.open(M.RECIPE_PROGRESS_STATE_FILE_PATH, "w")
    if not file then
        return false, err
    end
    file:write("return ")
    file:write(M.serialize_button_session_lua_table(data, 0))
    file:write("\n")
    file:close()
    return true
end

function M.ensure_recipe_package_record(package_key)
    package_key = trim(package_key or "")
    if package_key == "" then
        return nil
    end
    local data = M.ensure_recipe_progress_state()
    if type(data.packages[package_key]) ~= "table" then
        data.packages[package_key] = {
            key = package_key,
            completed_side_tasks = {}
        }
    end
    local record = data.packages[package_key]
    if type(record.completed_side_tasks) ~= "table" then
        record.completed_side_tasks = {}
    end
    return record
end

function M.recipe_progress_side_completed(package_key, side_task_key)
    package_key = trim(package_key or "")
    side_task_key = trim(side_task_key or "")
    if package_key == "" or side_task_key == "" then
        return false
    end
    local data = M.ensure_recipe_progress_state()
    local record = type(data.packages) == "table" and data.packages[package_key] or nil
    return type(record) == "table"
        and type(record.completed_side_tasks) == "table"
        and record.completed_side_tasks[side_task_key] ~= nil
end

function M.find_recipe_package_config(package_key)
    package_key = trim(package_key or "")
    if package_key == "" or type(M.TASK_NAME_CONFIGS) ~= "table" then
        return nil, nil
    end

    for _, cfg in pairs(M.TASK_NAME_CONFIGS) do
        local recipe_package = type(cfg) == "table" and cfg.recipe_package or nil
        if type(recipe_package) == "table" and trim(recipe_package.key or "") == package_key then
            return recipe_package, cfg
        end
    end

    return nil, nil
end

function M.recipe_progress_value_matches(value, pattern)
    local text = normalize_map_name(value)
    local key = normalize_map_name(pattern)
    if text == nil or key == nil then
        return false
    end
    return text:find(key, 1, true) ~= nil or key:find(text, 1, true) ~= nil
end

function M.recipe_progress_matches_any(patterns, values)
    if type(patterns) ~= "table" or type(values) ~= "table" then
        return false
    end
    for _, pattern in ipairs(patterns) do
        for _, value in ipairs(values) do
            if M.recipe_progress_value_matches(value, pattern) then
                return true
            end
        end
    end
    return false
end

function M.recipe_progress_blocker_matches_values(blocker, values)
    if type(blocker) ~= "table" or type(values) ~= "table" then
        return false
    end
    local task_name = values.task_name
    local task_detail = values.task_detail
    local candidates = {
        task_name,
        task_detail,
        values.raw_text,
        values.title,
        values.detail
    }

    if M.recipe_progress_value_matches(task_name, blocker.task_name)
        or M.recipe_progress_value_matches(task_detail, blocker.task_detail)
        or M.recipe_progress_value_matches(task_detail, blocker.task_name)
        or M.recipe_progress_value_matches(task_name, blocker.task_detail)
    then
        return true
    end

    if M.recipe_progress_matches_any(blocker.task_patterns, candidates)
        or M.recipe_progress_matches_any(blocker.task_detail_patterns, candidates)
    then
        return true
    end

    local queries = blocker.queries
    if type(queries) ~= "table" then
        queries = { blocker.query, blocker.task_name, blocker.task_detail }
    end
    return M.recipe_progress_matches_any(queries, candidates)
end

function M.recipe_progress_panel_entry_matches_blocker(entry, blocker)
    if type(entry) ~= "table" then
        return false
    end
    return M.recipe_progress_blocker_matches_values(blocker, {
        raw_text = entry.raw_text,
        title = entry.title,
        detail = entry.detail
    })
end

function M.detect_live_recipe_context(package_key, package_task_cfg, task_name, task_detail)
    package_key = trim(package_key or "")
    if package_key == "" or type(package_task_cfg) ~= "table" then
        return nil, nil, "missing_package_config"
    end

    if M.matches_task_constraints(package_task_cfg, {
        task_name = task_name,
        task_detail = task_detail
    }) then
        return "parent", nil, "parent_task_match"
    end

    local blockers = package_task_cfg.blocking_side_tasks
    if type(blockers) == "table" then
        for _, blocker in ipairs(blockers) do
            if type(blocker) == "table"
                and blocker.enabled ~= false
                and trim(blocker.recipe_package_key or package_key) == package_key
                and M.recipe_progress_blocker_matches_values(blocker, {
                    task_name = task_name,
                    task_detail = task_detail
                })
            then
                local side_key = trim(blocker.recipe_side_task_key or M.blocking_side_task_key(blocker) or "")
                return "side", side_key ~= "" and side_key or nil, "blocking_side_task_match"
            end
        end
    end

    return nil, nil, "not_in_package"
end

function M.clear_recipe_record_active_action(record, reason, current_time)
    if type(record) ~= "table" then
        return false
    end
    local old_action_key = trim(record.active_action_key or "")
    local old_side_key = trim(record.active_side_task_key or "")
    if old_action_key == "" and old_side_key == "" then
        return false
    end
    record.active_action_key = nil
    record.active_action_mode = nil
    record.active_side_task_key = nil
    record.active_step_key = nil
    record.active_source = nil
    record.active_clear_reason = tostring(reason or "")
    record.updated_at_ms = tonumber(current_time) or now_ms()
    record.updated_at = os and os.time and os.time() or nil
    return true, old_action_key, old_side_key
end

function M.align_recipe_progress_with_live_task(ctx, current_time, opts)
    opts = type(opts) == "table" and opts or {}
    current_time = tonumber(current_time) or now_ms(ctx)
    if opts.force ~= true and (tonumber(state.next_recipe_progress_alignment_at) or 0) > current_time then
        return true, "throttled"
    end
    state.next_recipe_progress_alignment_at = current_time + (tonumber(opts.interval_ms) or 1000)

    if state.task_info_stability_gate_active == true then
        log_throttled(ctx, "recipe_progress_align_task_gate", "debug", LOG_THROTTLE_MS,
            "[Leveling] recipe progress alignment deferred | reason=task_info_stability_gate")
        return false, "task_info_stability_gate"
    end

    local raw_task_name = normalize_map_name(state.current_task_name)
    local raw_task_detail = normalize_map_name(state.current_task_detail)
    if raw_task_name == nil and raw_task_detail == nil then
        log_throttled(ctx, "recipe_progress_align_task_vacuum", "debug", LOG_THROTTLE_MS,
            "[Leveling] recipe progress alignment deferred | reason=task_info_vacuum")
        return false, "task_info_vacuum"
    end

    local task_name = raw_task_name or normalize_map_name(M.current_task_log_name())
    local task_detail = raw_task_detail or normalize_map_name(M.current_task_log_detail())
    local data = M.ensure_recipe_progress_state()
    if type(data.packages) ~= "table" then
        return true, "no_packages"
    end

    local nav_mod = nil
    local snapshot = opts.ui_snapshot
    if type(snapshot) ~= "table" and opts.allow_enum ~= false then
        nav_mod = nav_api(ctx)
        if type(nav_mod) == "table" and type(nav_mod.enum_ui) == "function" then
            local ok, result = pcall(nav_mod.enum_ui)
            if ok and type(result) == "table" then
                snapshot = result
            end
        end
    else
        nav_mod = nav_api(ctx)
    end

    local panel_entries = nil
    if type(snapshot) == "table" then
        if type(snapshot.tasks) == "table" then
            panel_entries = snapshot.tasks
        elseif type(nav_mod) == "table" and type(nav_mod.get_task_panel_info) == "function" then
            local ok, info = pcall(nav_mod.get_task_panel_info, snapshot)
            if ok and type(info) == "table" and type(info.tasks) == "table" then
                panel_entries = info.tasks
            end
        end
    end

    local changed = false
    for package_key, record in pairs(data.packages) do
        if type(record) == "table" then
            local recipe_package, package_task_cfg = M.find_recipe_package_config(package_key)
            local active_action_key = trim(record.active_action_key or "")
            if type(recipe_package) ~= "table" or type(package_task_cfg) ~= "table" then
                if active_action_key ~= "" then
                    local cleared, old_action, old_side = M.clear_recipe_record_active_action(
                        record,
                        "package_config_missing",
                        current_time
                    )
                    if cleared then
                        changed = true
                        logger(ctx).warn(string.format(
                            "[Leveling] recipe progress active checkpoint dropped | package=%s action=%s side=%s reason=package_config_missing source=%s",
                            tostring(package_key),
                            tostring(old_action or ""),
                            tostring(old_side or ""),
                            tostring(opts.source or "")
                        ))
                    end
                end
            else
                local live_kind, live_side_key, live_reason = M.detect_live_recipe_context(
                    package_key,
                    package_task_cfg,
                    task_name,
                    task_detail
                )
                if live_kind == nil then
                    if active_action_key ~= "" then
                        local cleared, old_action, old_side = M.clear_recipe_record_active_action(
                            record,
                            "live_task_outside_package",
                            current_time
                        )
                        if cleared then
                            changed = true
                            logger(ctx).info(string.format(
                                "[Leveling] recipe progress active checkpoint dropped | package=%s action=%s side=%s live_task=%s live_detail=%s reason=live_task_outside_package source=%s",
                                tostring(package_key),
                                tostring(old_action or ""),
                                tostring(old_side or ""),
                                tostring(task_name or ""),
                                tostring(task_detail or ""),
                                tostring(opts.source or "")
                            ))
                        end
                    end
                else
                    if type(panel_entries) == "table" then
                        local blockers = package_task_cfg.blocking_side_tasks
                        if type(blockers) == "table" then
                            for _, blocker in ipairs(blockers) do
                                if type(blocker) == "table" then
                                    local side_key = trim(blocker.recipe_side_task_key or M.blocking_side_task_key(blocker) or "")
                                    if side_key ~= ""
                                        and type(record.completed_side_tasks) == "table"
                                        and record.completed_side_tasks[side_key] ~= nil
                                    then
                                        for _, entry in ipairs(panel_entries) do
                                            local entry_status_text = tostring(entry.raw_text or entry.title or "")
                                                .. " "
                                                .. tostring(entry.detail or "")
                                            local entry_looks_completed = entry_status_text:find("完成", 1, true) ~= nil
                                            if not entry_looks_completed
                                                and M.recipe_progress_panel_entry_matches_blocker(entry, blocker)
                                            then
                                                record.completed_side_tasks[side_key] = nil
                                                local blocker_key = M.blocking_side_task_key(blocker)
                                                if type(state.completed_blocking_side_tasks) == "table" then
                                                    state.completed_blocking_side_tasks[side_key] = nil
                                                    if blocker_key ~= nil then
                                                        state.completed_blocking_side_tasks[blocker_key] = nil
                                                    end
                                                end
                                                changed = true
                                                logger(ctx).warn(string.format(
                                                    "[Leveling] recipe progress completed side cleared by live panel | package=%s side=%s blocker=%s raw=%s detail=%s source=%s",
                                                    tostring(package_key),
                                                    side_key,
                                                    tostring(blocker_key or ""),
                                                    tostring(entry.raw_text or entry.title or ""),
                                                    tostring(entry.detail or ""),
                                                    tostring(opts.source or "")
                                                ))
                                                break
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end

                    active_action_key = trim(record.active_action_key or "")
                    if active_action_key ~= "" then
                        local drop_reason = nil
                        local action = M.find_route_point_action_by_key(active_action_key)
                        if type(action) ~= "table" then
                            drop_reason = "active_action_missing"
                        elseif trim(action.recipe_package_key or "") ~= tostring(package_key) then
                            drop_reason = "active_action_package_mismatch"
                        else
                            local action_side_key = trim(action.recipe_side_task_key or record.active_side_task_key or "")
                            if live_kind == "side"
                                and live_side_key ~= nil
                                and action_side_key ~= ""
                                and action_side_key ~= live_side_key
                            then
                                drop_reason = "live_side_task_changed"
                            elseif action_side_key ~= ""
                                and M.recipe_progress_side_completed(package_key, action_side_key)
                            then
                                drop_reason = "active_side_completed"
                            elseif not M.route_point_action_matches_task(action) then
                                drop_reason = "active_action_task_mismatch"
                            elseif type(opts.player_x) == "number" and type(opts.player_y) == "number" then
                                local near_resume = M.recipe_resume_player_near_action(
                                    action,
                                    opts.player_x,
                                    opts.player_y,
                                    opts.player_z
                                )
                                if near_resume ~= true then
                                    drop_reason = "player_not_near_active_action"
                                end
                            end
                        end

                        if drop_reason ~= nil then
                            local cleared, old_action, old_side = M.clear_recipe_record_active_action(
                                record,
                                drop_reason,
                                current_time
                            )
                            if cleared then
                                changed = true
                                logger(ctx).info(string.format(
                                    "[Leveling] recipe progress active checkpoint dropped | package=%s action=%s side=%s live_kind=%s live_side=%s live_task=%s live_detail=%s reason=%s live_reason=%s source=%s",
                                    tostring(package_key),
                                    tostring(old_action or ""),
                                    tostring(old_side or ""),
                                    tostring(live_kind or ""),
                                    tostring(live_side_key or ""),
                                    tostring(task_name or ""),
                                    tostring(task_detail or ""),
                                    tostring(drop_reason),
                                    tostring(live_reason or ""),
                                    tostring(opts.source or "")
                                ))
                            end
                        end
                    end
                end
            end
        end
    end

    if changed then
        local ok, err = M.save_recipe_progress_state()
        if not ok then
            log_throttled(ctx, "recipe_progress_align_save_failed", "warn", LOG_THROTTLE_MS,
                "[Leveling] recipe progress alignment save failed: " .. tostring(err or ""))
            return false, "save_failed"
        end
    end
    return true, changed and "changed" or "unchanged"
end

function M.persist_recipe_action_checkpoint(ctx, current_time, action, source)
    if type(action) ~= "table" then
        return false
    end
    local package_key = trim(action.recipe_package_key or "")
    if package_key == "" then
        return false
    end
    local action_key = trim(action.key or action.label or "")
    if action_key == "" then
        return false
    end

    local record = M.ensure_recipe_package_record(package_key)
    if type(record) ~= "table" then
        return false
    end
    local previous_action_key = trim(record.active_action_key or "")
    record.active_action_key = action_key
    record.active_action_mode = tostring(action.mode or "")
    record.active_side_task_key = trim(action.recipe_side_task_key or "")
    record.active_step_key = trim(action.recipe_step_key or action_key)
    record.active_source = tostring(source or "")
    record.active_task_name = tostring(M.current_task_log_name() or state.current_task_name or "")
    record.active_task_detail = tostring(M.current_task_log_detail() or state.current_task_detail or "")
    record.updated_at_ms = tonumber(current_time) or now_ms(ctx)
    record.updated_at = os and os.time and os.time() or nil

    local ok, err = M.save_recipe_progress_state()
    if ok then
        logger(ctx).info(string.format(
            "[Leveling] recipe progress checkpoint saved | package=%s action=%s side=%s mode=%s source=%s previous=%s",
            package_key,
            action_key,
            tostring(record.active_side_task_key or ""),
            tostring(record.active_action_mode or ""),
            tostring(source or ""),
            tostring(previous_action_key or "")
        ))
    else
        log_throttled(ctx, "recipe_progress_checkpoint_save_failed_" .. package_key, "warn", LOG_THROTTLE_MS,
            "[Leveling] recipe progress checkpoint save failed: " .. tostring(err or ""))
    end
    return ok == true
end

function M.mark_recipe_side_task_completed(ctx, current_time, package_key, side_task_key, source)
    package_key = trim(package_key or "")
    side_task_key = trim(side_task_key or "")
    if package_key == "" or side_task_key == "" then
        return false
    end
    local record = M.ensure_recipe_package_record(package_key)
    if type(record) ~= "table" then
        return false
    end
    local was_completed = type(record.completed_side_tasks) == "table"
        and record.completed_side_tasks[side_task_key] ~= nil
    record.completed_side_tasks[side_task_key] = tonumber(current_time) or now_ms(ctx)
    if trim(record.active_side_task_key or "") == side_task_key then
        record.active_action_key = nil
        record.active_action_mode = nil
        record.active_step_key = nil
        record.active_source = nil
    end
    record.updated_at_ms = tonumber(current_time) or now_ms(ctx)
    record.updated_at = os and os.time and os.time() or nil
    if type(state.completed_blocking_side_tasks) ~= "table" then
        state.completed_blocking_side_tasks = {}
    end
    state.completed_blocking_side_tasks[side_task_key] = tonumber(current_time) or now_ms(ctx)

    local ok, err = M.save_recipe_progress_state()
    if ok then
        logger(ctx).info(string.format(
            "[Leveling] recipe side task completed persisted | package=%s side=%s source=%s already=%s",
            package_key,
            side_task_key,
            tostring(source or ""),
            was_completed and "true" or "false"
        ))
    else
        log_throttled(ctx, "recipe_progress_side_save_failed_" .. package_key, "warn", LOG_THROTTLE_MS,
            "[Leveling] recipe side task completion save failed: " .. tostring(err or ""))
    end
    return true
end

function M.mark_recipe_action_completed(ctx, current_time, action, source)
    if type(action) ~= "table" then
        return false
    end
    local package_key = trim(action.recipe_package_key or "")
    local complete_side_key = trim(action.recipe_complete_side_task_key or "")
    if package_key == "" or complete_side_key == "" then
        return false
    end
    return M.mark_recipe_side_task_completed(ctx, current_time, package_key, complete_side_key, source)
end

function M.recipe_resume_player_near_action(action, player_x, player_y, player_z)
    if type(action) ~= "table" or type(player_x) ~= "number" or type(player_y) ~= "number" then
        return false, nil
    end
    local max_distance = math.max(900, tonumber(action.recipe_resume_radius) or 2600)
    local z_tolerance = math.max(0, tonumber(action.recipe_resume_z_tolerance) or 520)
    local best_distance = nil
    local best_z_gap = 0

    local function consider(point)
        if type(point) ~= "table" then
            return
        end
        local x = tonumber(point.x)
        local y = tonumber(point.y)
        if x == nil or y == nil then
            return
        end
        local d = distance_2d(player_x, player_y, x, y)
        local z = tonumber(point.z)
        local zg = z ~= nil and type(player_z) == "number"
            and math.abs((tonumber(player_z) or 0) - z)
            or 0
        if best_distance == nil or d < best_distance then
            best_distance = d
            best_z_gap = zg
        end
    end

    consider(action.trigger)
    consider(action.objective_point)
    if type(action.waypoints) == "table" then
        for _, point in ipairs(action.waypoints) do
            consider(point)
        end
    end

    if best_distance == nil then
        return false, nil
    end
    return best_distance <= max_distance and best_z_gap <= z_tolerance, best_distance, best_z_gap
end

function M.find_persisted_recipe_route_point_candidate(ctx, current_time, player_x, player_y, player_z, opts)
    opts = type(opts) == "table" and opts or {}
    if opts.skip_alignment ~= true then
        M.align_recipe_progress_with_live_task(ctx, current_time, {
            source = opts.source or "persisted_resume",
            player_x = player_x,
            player_y = player_y,
            player_z = player_z
        })
    end
    local data = M.ensure_recipe_progress_state()
    if type(data.packages) ~= "table" then
        return nil
    end

    for package_key, record in pairs(data.packages) do
        local action_key = trim(type(record) == "table" and record.active_action_key or "")
        if action_key ~= "" then
            local action = M.find_route_point_action_by_key(action_key)
            if type(action) == "table" and trim(action.recipe_package_key or "") == tostring(package_key) then
                local side_key = trim(action.recipe_side_task_key or record.active_side_task_key or "")
                local completed = side_key ~= "" and M.recipe_progress_side_completed(package_key, side_key)
                local allow_without_task_target = action.allow_without_task_target == true
                local allow_wait_task_path_recover = action.allow_wait_task_path_recover == true
                local allow_candidate = completed ~= true
                if allow_candidate and opts.require_allow_without_task_target == true and not allow_without_task_target then
                    allow_candidate = false
                end
                if allow_candidate and opts.require_wait_task_path_recover == true and not allow_wait_task_path_recover then
                    allow_candidate = false
                end
                if allow_candidate and not M.route_point_action_matches_task(action) then
                    allow_candidate = false
                end
                local near_resume, resume_distance, resume_z_gap = false, nil, nil
                if allow_candidate then
                    near_resume, resume_distance, resume_z_gap = M.recipe_resume_player_near_action(action, player_x, player_y, player_z)
                    if near_resume ~= true then
                        allow_candidate = false
                    end
                end
                if allow_candidate then
                    local skip_reason = select(1, M.route_point_action_skip_reason(ctx, action, current_time))
                    if skip_reason ~= nil then
                        allow_candidate = false
                    end
                end
                if allow_candidate then
                    local map_match = select(1, M.route_point_action_matches_current_map(ctx, action, current_time))
                    local destination_match = select(1, M.route_point_action_destination_matches(action, player_x, player_y))
                    if map_match ~= true or destination_match ~= true then
                        allow_candidate = false
                    end
                end
                if allow_candidate then
                    logger(ctx).info(string.format(
                        "[Leveling] recipe progress resume candidate | package=%s action=%s side=%s distance=%s z_gap=%s",
                        tostring(package_key),
                        action_key,
                        side_key,
                        resume_distance ~= nil and string.format("%.2f", resume_distance) or "nil",
                        resume_z_gap ~= nil and string.format("%.2f", resume_z_gap) or "nil"
                    ))
                    return M.build_task_intent_candidate(
                        M.route_point_action_intent_kind(action),
                        "recipe_persisted_resume",
                        action_key,
                        action,
                        "persisted_route_action_checkpoint"
                    )
                end
            end
        end
    end

    return nil
end

function M.get_button_session_process_path(nav_mod)
    local pid = tonumber(type(nav_mod) == "table" and nav_mod.pid or 0) or 0
    if pid <= 0 then
        return ""
    end

    local proc_api = rawget(_G, "proc") or proc
    if type(proc_api) ~= "table" or type(proc_api.path) ~= "function" then
        return ""
    end

    local ok, process_path = pcall(proc_api.path, pid)
    if not ok then
        return ""
    end
    return trim(process_path):lower()
end

function M.build_button_session_key(nav_mod)
    local pid = tonumber(type(nav_mod) == "table" and nav_mod.pid or 0) or 0
    local hwnd = nil
    if type(nav_mod) == "table" and type(nav_mod.window_hwnd) == "function" then
        hwnd = select(1, nav_mod.window_hwnd())
    end
    local process_path = M.get_button_session_process_path(nav_mod)
    return string.format(
        "pid=%s|hwnd=%s|path=%s",
        tostring(pid > 0 and pid or ""),
        tostring(hwnd or ""),
        tostring(process_path or "")
    )
end

function M.read_button_session_entry(nav_mod, slot)
    local data = M.ensure_button_session_state()
    local cached = type(data) == "table" and type(data[slot]) == "table" and data[slot] or nil
    if type(cached) ~= "table" then
        return nil, "session cache missing."
    end

    local current_session_key = M.build_button_session_key(nav_mod)
    local cached_session_key = trim(cached.session_key or "")
    local session_ok = current_session_key ~= "" and cached_session_key ~= "" and cached_session_key == current_session_key
    if not session_ok and type(M._leveling_buttons) == "table"
        and type(M._leveling_buttons.cache_matches_process) == "function"
    then
        session_ok = select(1, M._leveling_buttons.cache_matches_process(cached, current_session_key)) == true
    end
    if not session_ok then
        data[slot] = nil
        M.save_button_session_state()
        return nil, "session cache key mismatch."
    end

    return M.copy_main_task_button_cache_fields(cached)
end

function M.persist_button_session_entry(slot, cached)
    local data = M.ensure_button_session_state()
    data[slot] = M.copy_main_task_button_cache_fields(cached)
    return M.save_button_session_state()
end

function M.log_button_slot_addr_change(ctx, slot, previous, current, source)
    if type(previous) ~= "table" or type(current) ~= "table" then
        return
    end
    local previous_addr = tonumber(previous.addr)
    local current_addr = tonumber(current.addr)
    if previous_addr == nil or previous_addr == 0 or current_addr == nil or current_addr == 0 then
        return
    end
    if previous_addr == current_addr then
        return
    end

    local previous_pid = tonumber(previous.pid) or 0
    local current_pid = tonumber(current.pid) or 0
    local previous_session = trim(previous.session_key or "")
    local current_session = trim(current.session_key or "")
    local same_pid = previous_pid > 0 and current_pid > 0 and previous_pid == current_pid
    local same_session = previous_session ~= "" and current_session ~= "" and previous_session == current_session
    logger(ctx).warn(string.format(
        "[Leveling] button slot addr changed | slot=%s same_pid=%s same_session=%s old_addr=%s new_addr=%s old_pid=%s new_pid=%s source=%s old_source=%s new_source=%s",
        tostring(slot or ""),
        same_pid and "true" or "false",
        same_session and "true" or "false",
        tostring(previous_addr),
        tostring(current_addr),
        tostring(previous_pid > 0 and previous_pid or ""),
        tostring(current_pid > 0 and current_pid or ""),
        tostring(source or ""),
        tostring(previous.source or ""),
        tostring(current.source or "")
    ))
end

function M.clear_button_session_entry(slot)
    local data = M.ensure_button_session_state()
    data[slot] = nil
    return M.save_button_session_state()
end

function M.is_generic_cached_button_slot(slot)
    local def = type(M.button_slot_definition) == "function"
        and select(1, M.button_slot_definition(slot))
        or nil
    if type(def) ~= "table" then
        return false
    end
    return def.generic_session_cache == true
        or tostring(def.role or "") == "fight_interactive_portal"
end

function M.apply_registered_button_slot_step_defaults(slot, step)
    if type(step) ~= "table" then
        return step
    end

    local slot_def = type(M.button_slot_definition) == "function"
        and select(1, M.button_slot_definition(slot))
        or nil
    local hover_cfg = type(slot_def) == "table" and type(slot_def.hover_capture) == "table"
        and slot_def.hover_capture
        or nil
    if hover_cfg ~= nil then
        if step.hover_capture_enabled == nil then
            step.hover_capture_enabled = true
        end
        if step.hover_capture_client_left == nil then
            step.hover_capture_client_left = tonumber(hover_cfg.client_left)
        end
        if step.hover_capture_client_top == nil then
            step.hover_capture_client_top = tonumber(hover_cfg.client_top)
        end
        if step.hover_capture_client_right == nil then
            step.hover_capture_client_right = tonumber(hover_cfg.client_right)
        end
        if step.hover_capture_client_bottom == nil then
            step.hover_capture_client_bottom = tonumber(hover_cfg.client_bottom)
        end
        if step.hover_capture_retry_ms == nil then
            step.hover_capture_retry_ms = tonumber(hover_cfg.retry_ms)
        end
    end

    return step
end

function M.extract_registered_button_slot_target(slot, target_like)
    if type(target_like) ~= "table" then
        return nil
    end

    local target = {
        kind = tostring(target_like.kind or "button"),
        addr = tonumber(target_like.addr),
        name = tostring(target_like.name or ""),
        fullname = tostring(target_like.fullname or target_like.Fullname or target_like.identity or ""),
        text = tostring(target_like.text or target_like.label or ""),
        x = tonumber(target_like.x or target_like.client_x),
        y = tonumber(target_like.y or target_like.client_y),
        related_text = tostring(target_like.related_text or target_like.nearest_text or target_like.rel1_text or ""),
        related_distance = tonumber(target_like.related_distance or target_like.nearest_distance or target_like.rel1_distance),
        distance = tonumber(target_like.distance or target_like.hint_distance)
    }
    if target.kind == "" then
        target.kind = "button"
    end

    local buttons = type(M._leveling_buttons) == "table" and M._leveling_buttons or nil
    if type(buttons) == "table" and type(buttons.target_matches_slot) == "function" then
        local ok = select(1, buttons.target_matches_slot(slot, target))
        if not ok then
            return nil
        end
    elseif target.addr == nil or target.addr == 0 then
        return nil
    end

    return target
end

function M.ensure_registered_button_slot_cache_tables()
    if type(state.cached_button_slot_targets) ~= "table" then
        state.cached_button_slot_targets = {}
    end
    if type(state.cached_button_slot_target_ats) ~= "table" then
        state.cached_button_slot_target_ats = {}
    end
    if type(_G.AVEPOINT_CACHED_BUTTON_SLOT_TARGETS) ~= "table" then
        _G.AVEPOINT_CACHED_BUTTON_SLOT_TARGETS = {}
    end
    return state.cached_button_slot_targets, state.cached_button_slot_target_ats, _G.AVEPOINT_CACHED_BUTTON_SLOT_TARGETS
end

function M.clear_cached_registered_button_slot_target(slot)
    slot = tostring(slot or "")
    local mem, ats, global = M.ensure_registered_button_slot_cache_tables()
    mem[slot] = nil
    ats[slot] = nil
    global[slot] = nil
    M.clear_button_session_entry(slot)
end

function M.cache_registered_button_slot_target(ctx, slot, target_like, current_time, source, step, opts)
    slot = tostring(slot or "")
    opts = type(opts) == "table" and opts or {}
    local target = M.extract_registered_button_slot_target(slot, target_like)
    if type(target) ~= "table" then
        logger(ctx).warn(string.format(
            "[Leveling] registered button slot cache extract failed | slot=%s source=%s raw=%s",
            slot,
            tostring(source or ""),
            M.format_main_task_click_target_brief(type(target_like) == "table" and target_like or {})
        ))
        return nil
    end

    local cached = {
        kind = "button",
        slot = slot,
        addr = tonumber(target.addr),
        name = tostring(target.name or ""),
        fullname = tostring(target.fullname or ""),
        x = tonumber(target.x),
        y = tonumber(target.y),
        text = tostring(target.text or ""),
        related_text = tostring(target.related_text or ""),
        related_distance = tonumber(target.related_distance),
        captured_at = tonumber(current_time) or now_ms(ctx),
        source = tostring(source or ""),
        cache_context = tostring(opts.cache_context or "")
    }

    local nav_mod = nav_api(ctx)
    local wnd_api = type(ctx) == "table" and ctx.wnd or wnd
    if type(nav_mod) == "table"
        and type(nav_mod.window_hwnd) == "function"
        and type(wnd_api) == "table"
        and type(wnd_api.client_rect) == "function"
    then
        local hwnd = select(1, nav_mod.window_hwnd())
        if hwnd then
            local _, _, client_w, client_h = wnd_api.client_rect(hwnd)
            if type(client_w) == "number" and client_w > 0 and cached.x ~= nil then
                cached.hint_ratio_x = cached.x / client_w
            elseif type(step) == "table" then
                cached.hint_ratio_x = tonumber(step.hint_ratio_x)
            end
            if type(client_h) == "number" and client_h > 0 and cached.y ~= nil then
                cached.hint_ratio_y = cached.y / client_h
            elseif type(step) == "table" then
                cached.hint_ratio_y = tonumber(step.hint_ratio_y)
            end
        end
    end

    local current_pid = tonumber(type(nav_mod) == "table" and nav_mod.pid or 0)
    if current_pid ~= nil and current_pid > 0 then
        cached.pid = current_pid
    end
    cached.session_key = M.build_button_session_key(nav_mod)
    if M.button_call_cache_disabled() then
        return cached
    end

    local mem, ats, global = M.ensure_registered_button_slot_cache_tables()
    local previous_cached = type(mem[slot]) == "table" and mem[slot]
        or type(global[slot]) == "table" and global[slot]
        or nil
    M.log_button_slot_addr_change(ctx, slot, previous_cached, cached, source)
    mem[slot] = cached
    ats[slot] = cached.captured_at
    global[slot] = M.copy_main_task_button_cache_fields(cached)
    M.persist_button_session_entry(slot, cached)
    return cached
end

function M.resolve_cached_registered_button_slot_target(nav_mod, current_time, slot, opts)
    slot = tostring(slot or "")
    opts = type(opts) == "table" and opts or {}
    local mem, ats, global = M.ensure_registered_button_slot_cache_tables()
    local cached = mem[slot]
    if type(cached) ~= "table" and type(global[slot]) == "table" then
        cached = global[slot]
    end
    if type(cached) ~= "table" then
        cached = M.read_button_session_entry(nav_mod, slot)
        if type(cached) == "table" then
            mem[slot] = cached
            ats[slot] = tonumber(cached.captured_at) or 0
            global[slot] = M.copy_main_task_button_cache_fields(cached)
        end
    end
    if type(cached) ~= "table" then
        return nil, "cached registered button slot target unavailable."
    end

    local addr = tonumber(cached.addr)
    local x = tonumber(cached.x)
    local y = tonumber(cached.y)
    if addr == nil or addr == 0 or x == nil or y == nil then
        M.clear_cached_registered_button_slot_target(slot)
        return nil, "cached registered button slot target is invalid."
    end

    local requested_context = trim(opts.cache_context or "")
    local cached_context = trim(cached.cache_context or "")
    if requested_context ~= "" and cached_context ~= requested_context then
        M.clear_cached_registered_button_slot_target(slot)
        return nil, string.format(
            "cached registered button slot context changed. cached=%s requested=%s",
            cached_context,
            requested_context
        )
    end

    local cached_pid = tonumber(cached.pid or 0)
    local current_pid = tonumber(type(nav_mod) == "table" and nav_mod.pid or 0)
    if cached_pid > 0 and current_pid > 0 and cached_pid ~= current_pid then
        M.clear_cached_registered_button_slot_target(slot)
        return nil, string.format(
            "cached registered button slot pid changed. cached=%d current=%d",
            cached_pid,
            current_pid
        )
    end

    local buttons = type(M._leveling_buttons) == "table" and M._leveling_buttons or nil
    if type(buttons) == "table" and type(buttons.cache_matches_process) == "function" then
        local process_ok, process_reason = buttons.cache_matches_process(
            cached,
            M.build_button_session_key(nav_mod)
        )
        if not process_ok then
            M.clear_cached_registered_button_slot_target(slot)
            return nil, "cached registered button slot process changed: " .. tostring(process_reason or "")
        end
    end

    local target = {
        kind = "button",
        addr = addr,
        name = tostring(cached.name or ""),
        text = tostring(cached.text or ""),
        fullname = tostring(cached.fullname or ""),
        x = x,
        y = y,
        related_text = tostring(cached.related_text or ""),
        related_distance = tonumber(cached.related_distance),
        distance = 0,
        source = tostring(cached.source or ""),
        pid = cached_pid > 0 and cached_pid or nil
    }

    if type(buttons) == "table" and type(buttons.target_matches_slot) == "function" then
        local ok, reject = buttons.target_matches_slot(slot, target)
        if not ok then
            return nil, "cached registered button slot target rejected by registry: " .. tostring(reject or "")
        end
    end

    local captured_at = tonumber(ats[slot]) or tonumber(cached.captured_at) or 0
    if captured_at > 0 and tonumber(current_time) ~= nil then
        ats[slot] = captured_at
    end

    return target
end

function M.clear_cached_registered_button_slot_addr_with_log(ctx, slot, reason)
    M.clear_cached_registered_button_slot_target(slot)
    logger(ctx).info(string.format(
        "[Leveling] cleared cached registered button slot addr | slot=%s reason=%s",
        tostring(slot or ""),
        tostring(reason or "")
    ))
end

function M.try_cached_registered_button_slot_click(ctx, nav_mod, current_time, slot, step, reason, opts)
    opts = type(opts) == "table" and opts or {}
    if type(nav_mod) ~= "table" or type(nav_mod.control_click) ~= "function" then
        return false, "nav.control_click is unavailable."
    end

    local cached_target, cached_err = M.resolve_cached_registered_button_slot_target(nav_mod, current_time, slot, opts)
    if type(cached_target) ~= "table" then
        return false, cached_err
    end

    local click_ok, click_err = nav_mod.control_click(cached_target.addr)
    if not click_ok then
        if M.is_control_click_hard_failure(click_err) then
            M.clear_cached_registered_button_slot_addr_with_log(ctx, slot, click_err or "cached button slot addr click failed")
        else
            log_throttled(ctx, "registered_button_slot_cached_click_preserved_" .. tostring(slot), "info", LOG_THROTTLE_MS,
                "[Leveling] preserve cached registered button slot addr | slot="
                    .. tostring(slot)
                    .. " reason="
                    .. tostring(click_err or "cached button slot addr click failed"))
        end
        return false, click_err, nil, "click_failed"
    end

    logger(ctx).info(string.format(
        "[Leveling] registered button slot clicked | slot=%s source=cached_addr addr=%s pos=(%s,%s) cache_source=%s reason=%s",
        tostring(slot or ""),
        tostring(cached_target.addr or ""),
        tostring(cached_target.x or ""),
        tostring(cached_target.y or ""),
        tostring(cached_target.source or ""),
        tostring(reason or "")
    ))
    return true, cached_target
end

function M.try_capture_registered_button_slot_via_hover(ctx, nav_mod, current_time, slot, step, reason, opts)
    opts = type(opts) == "table" and opts or {}
    if type(step) ~= "table" then
        return nil, "registered button slot step unavailable."
    end
    step = M.apply_registered_button_slot_step_defaults(slot, step)
    local captured_target, capture_err = M.try_capture_locator_button_via_hover(ctx, current_time, step, reason)
    if type(captured_target) ~= "table" then
        return nil, capture_err
    end
    local cached = M.cache_registered_button_slot_target(ctx, slot, captured_target, current_time, "hover_capture", step, opts)
    if type(cached) ~= "table" then
        return nil, "registered button slot captured target rejected."
    end
    return captured_target
end

function M.clear_cached_main_task_button_target()
    state.cached_main_task_button_target = nil
    state.cached_main_task_button_target_at = 0
    state.main_task_button_cache_warmed_this_run = false
    _G.AVEPOINT_CACHED_MAIN_TASK_BUTTON_TARGET = nil
    M.clear_button_session_entry("main_task")
end

function M.cache_main_task_button_target(ctx, target_like, current_time, source)
    if M.main_task_button_cache_disabled() then
        return nil
    end

    local target = M.extract_main_task_button_target(target_like)
    if type(target) ~= "table" then
        return nil
    end

    local buttons = type(M._leveling_buttons) == "table" and M._leveling_buttons or nil
    if type(buttons) == "table" and type(buttons.target_matches_slot) == "function" then
        local ok, reject = buttons.target_matches_slot("main_task", target)
        if not ok then
            logger(ctx).warn(string.format(
                "[Leveling] main task cache rejected by button registry | reject=%s target=%s",
                tostring(reject or ""),
                M.format_main_task_click_target_brief(target)
            ))
            return nil
        end
    end

    local cached = {
        kind = "button",
        slot = "main_task",
        addr = tonumber(target.addr),
        name = tostring(target.name or ""),
        fullname = tostring(target.fullname or ""),
        x = tonumber(target.x),
        y = tonumber(target.y),
        text = tostring(target.text or ""),
        related_text = tostring(target.related_text or ""),
        related_distance = tonumber(target.related_distance),
        captured_at = tonumber(current_time) or 0,
        source = tostring(source or "")
    }

    local nav_mod = nav_api(ctx)
    local wnd_api = type(ctx) == "table" and ctx.wnd or wnd
    if type(nav_mod) == "table"
        and type(nav_mod.window_hwnd) == "function"
        and type(wnd_api) == "table"
        and type(wnd_api.client_rect) == "function"
    then
        local hwnd = select(1, nav_mod.window_hwnd())
        if hwnd then
            local _, _, client_w, client_h = wnd_api.client_rect(hwnd)
            if type(client_w) == "number" and client_w > 0 and cached.x ~= nil then
                cached.hint_ratio_x = cached.x / client_w
            end
            if type(client_h) == "number" and client_h > 0 and cached.y ~= nil then
                cached.hint_ratio_y = cached.y / client_h
            end
        end
    end

    local current_pid = tonumber(type(nav_mod) == "table" and nav_mod.pid or 0)
    if current_pid ~= nil and current_pid > 0 then
        cached.pid = current_pid
    end
    cached.session_key = M.build_button_session_key(nav_mod)

    state.cached_main_task_button_target = cached
    state.cached_main_task_button_target_at = cached.captured_at
    state.main_task_button_cache_warmed_this_run = true
    _G.AVEPOINT_CACHED_MAIN_TASK_BUTTON_TARGET = M.copy_main_task_button_cache_fields(cached)
    M.persist_button_session_entry("main_task", cached)
    return cached
end

function M.remember_success_main_task_button(ctx, target_like, current_time, source)
    if M.main_task_button_cache_disabled() then
        return nil
    end

    local cached = M.cache_main_task_button_target(ctx, target_like, current_time, source)
    if type(cached) ~= "table" then
        return nil
    end

    state.last_success_main_task_button = M.copy_main_task_button_cache_fields(cached)
    state.last_success_main_task_button_at = cached.captured_at
    _G.AVEPOINT_LAST_SUCCESS_MAIN_TASK_BUTTON = M.copy_main_task_button_cache_fields(cached)
    return cached
end

function M.resolve_cached_main_task_button_target(nav_mod, current_time, opts)
    if M.main_task_button_cache_disabled() then
        return nil, "main task TaskBtn cache disabled; live enum text-distance required."
    end

    local allow_session_restore = true
    if type(opts) == "table" and opts.allow_session_restore == false then
        allow_session_restore = false
    end

    local cached = state.cached_main_task_button_target
    if type(cached) ~= "table" and type(_G.AVEPOINT_CACHED_MAIN_TASK_BUTTON_TARGET) == "table" then
        cached = _G.AVEPOINT_CACHED_MAIN_TASK_BUTTON_TARGET
    end
    if type(cached) ~= "table" and allow_session_restore then
        cached = M.read_button_session_entry(nav_mod, "main_task")
        if type(cached) == "table" then
            state.cached_main_task_button_target = cached
            state.cached_main_task_button_target_at = tonumber(cached.captured_at) or 0
            _G.AVEPOINT_CACHED_MAIN_TASK_BUTTON_TARGET = M.copy_main_task_button_cache_fields(cached)
        end
    end
    if type(cached) ~= "table" then
        if allow_session_restore ~= true then
            return nil, "cached main task session restore deferred until live reacquire."
        end
        return nil, "cached main task button target unavailable."
    end

    local addr = tonumber(cached.addr)
    local x = tonumber(cached.x)
    local y = tonumber(cached.y)
    if addr == nil or addr == 0 or x == nil or y == nil then
        M.clear_cached_main_task_button_target()
        return nil, "cached main task button target is invalid."
    end

    local cached_pid = tonumber(cached.pid or 0)
    local current_pid = tonumber(type(nav_mod) == "table" and nav_mod.pid or 0)
    if cached_pid > 0 and current_pid > 0 and cached_pid ~= current_pid then
        M.clear_cached_main_task_button_target()
        return nil, string.format(
            "cached main task button target pid changed. cached=%d current=%d",
            cached_pid,
            current_pid
        )
    end

    local cached_session_key = trim(cached.session_key or "")
    local current_session_key = M.build_button_session_key(nav_mod)
    if cached_session_key ~= "" and current_session_key ~= "" and cached_session_key ~= current_session_key then
        local buttons = type(M._leveling_buttons) == "table" and M._leveling_buttons or nil
        local process_ok = false
        if type(buttons) == "table" and type(buttons.cache_matches_process) == "function" then
            process_ok = select(1, buttons.cache_matches_process(cached, current_session_key)) == true
        end
        if process_ok then
            cached.session_key = current_session_key
            state.cached_main_task_button_target = cached
            _G.AVEPOINT_CACHED_MAIN_TASK_BUTTON_TARGET = M.copy_main_task_button_cache_fields(cached)
            M.persist_button_session_entry("main_task", cached)
        else
            M.clear_cached_main_task_button_target()
            return nil, string.format(
                "cached main task button target session changed. cached=%s current=%s",
                cached_session_key,
                current_session_key
            )
        end
    end

    local captured_at = tonumber(state.cached_main_task_button_target_at) or tonumber(cached.captured_at) or 0
    if captured_at > 0 and tonumber(current_time) ~= nil then
        state.cached_main_task_button_target_at = captured_at
    end

    local target = {
        kind = "button",
        addr = addr,
        name = tostring(cached.name or ""),
        text = tostring(cached.text or ""),
        fullname = tostring(cached.fullname or ""),
        x = x,
        y = y,
        related_text = tostring(cached.related_text or ""),
        related_distance = tonumber(cached.related_distance),
        distance = 0,
        source = tostring(cached.source or ""),
        pid = cached_pid > 0 and cached_pid or nil
    }

    local buttons = type(M._leveling_buttons) == "table" and M._leveling_buttons or nil
    if type(buttons) == "table" and type(buttons.target_matches_slot) == "function" then
        local ok, reject = buttons.target_matches_slot("main_task", target)
        if not ok then
            return nil, "cached main task button target rejected by registry: " .. tostring(reject or "")
        end
    end

    return target
end

function M.extract_dialogue_jump_button_target(target_like)
    if type(target_like) ~= "table" then
        return nil
    end

    local source = type(target_like._dialogue_jump_clicked_target) == "table"
        and target_like._dialogue_jump_clicked_target
        or target_like

    local kind = tostring(source.kind or source.button_kind or target_like.button_kind or "")
    local addr = tonumber(source.addr or source.button_addr or target_like.button_addr)
    local x = tonumber(source.x or source.button_x or target_like.button_x or target_like.x)
    local y = tonumber(source.y or source.button_y or target_like.button_y or target_like.y)
    local name = tostring(source.name or source.button_name or target_like.button_name or "")
    local fullname = tostring(
        source.fullname
            or source.Fullname
            or source.button_fullname
            or target_like.button_fullname
            or ""
    )
    if addr == nil or addr == 0 or x == nil or y == nil then
        return nil
    end

    local target = {
        kind = "button",
        addr = addr,
        name = name,
        text = tostring(source.text or target_like.text or ""),
        fullname = fullname,
        x = x,
        y = y,
        related_text = tostring(source.related_text or source.rel1_text or target_like.related_text or ""),
        related_distance = tonumber(source.related_distance),
        distance = tonumber(source.distance)
    }

    local buttons = type(M._leveling_buttons) == "table" and M._leveling_buttons or nil
    if type(buttons) == "table" and type(buttons.target_matches_slot) == "function" then
        local ok = select(1, buttons.target_matches_slot("dialogue_jump", target))
        if not ok then
            return nil
        end
    else
        local identity = (fullname .. " " .. name):lower()
        local is_button = kind == "button"
            or identity:find("dialoguetalk_c.widgettree.jumpbtn", 1, true) ~= nil
        if not is_button then
            return nil
        end
    end

    return target
end

function M.resolve_dialogue_jump_selected_target(nav_mod, step)
    if type(nav_mod) ~= "table" or type(nav_mod.get_current_selected_button) ~= "function" then
        return nil, "nav.get_current_selected_button is unavailable."
    end

    local selected, selected_err = nav_mod.get_current_selected_button()
    if type(selected) ~= "table" then
        return nil, selected_err or "Current selected button not found."
    end

    local addr = tonumber(selected.addr)
    local x = tonumber(selected.x)
    local y = tonumber(selected.y)
    local fullname = tostring(selected.Fullname or selected.fullname or "")
    local name = tostring(selected.name or "")
    local selected_text = tostring(selected.text or "")
    local related_text = tostring(selected.rel1_text or "")
    if addr == nil or addr == 0 or x == nil or y == nil then
        return nil, string.format(
            "GetCurrentSelected returned invalid JumpBtn data. addr=%s pos=(%s,%s) name=%s fullname=%s text=%s related=%s",
            tostring(selected.addr or ""),
            tostring(selected.x or ""),
            tostring(selected.y or ""),
            name,
            fullname,
            selected_text,
            related_text
        )
    end

    local selected_target = {
        kind = "button",
        addr = addr,
        name = name,
        text = selected_text,
        fullname = fullname,
        x = x,
        y = y,
        related_text = related_text
    }
    local buttons = type(M._leveling_buttons) == "table" and M._leveling_buttons or nil
    local selected_matches = false
    local selected_reject = nil
    if type(buttons) == "table" and type(buttons.target_matches_slot) == "function" then
        selected_matches, selected_reject = buttons.target_matches_slot("dialogue_jump", selected_target)
    else
        local identity = (fullname .. " " .. name):lower()
        selected_matches = identity:find("dialoguetalk_c.widgettree.jumpbtn", 1, true) ~= nil
    end
    if selected_matches ~= true then
        return nil, string.format(
            "GetCurrentSelected is not JumpBtn. addr=%s pos=(%s,%s) name=%s fullname=%s text=%s related=%s reject=%s",
            tostring(addr or ""),
            tostring(x or ""),
            tostring(y or ""),
            name,
            fullname,
            selected_text,
            related_text,
            tostring(selected_reject or "")
        )
    end

    local hint_x = tonumber(type(step) == "table" and step.hint_client_x or nil)
    local hint_y = tonumber(type(step) == "table" and step.hint_client_y or nil)
    local distance = 0
    if hint_x ~= nil and hint_y ~= nil then
        distance = distance_2d(hint_x, hint_y, x, y)
        if distance > math.max(tonumber(type(step) == "table" and step.hint_max_distance or 80) or 80, 96) then
            return nil, string.format(
                "GetCurrentSelected JumpBtn too far from hint: %.2f selected=(%.2f,%.2f) hint=(%.2f,%.2f)",
                tonumber(distance) or 0,
                x,
                y,
                tonumber(hint_x) or 0,
                tonumber(hint_y) or 0
            )
        end
    end

    local anchor_text = trim(type(step) == "table" and step.distance_anchor_exact_text or "")
    local related_line = trim(related_text)
    local selected_line = trim(selected_text)
    local anchor_relaxed = false
    if anchor_text ~= "" then
        local matches_anchor = related_line == anchor_text
            or selected_line == anchor_text
            or related_line:find(anchor_text, 1, true) ~= nil
            or selected_line:find(anchor_text, 1, true) ~= nil
        if not matches_anchor then
            if related_line == "" and selected_line == "" then
                anchor_relaxed = true
            else
                return nil, string.format(
                    "GetCurrentSelected JumpBtn anchor mismatch. anchor=%s related=%s text=%s",
                    anchor_text,
                    related_line,
                    selected_line
                )
            end
        end
    end

    local related_dx = tonumber(selected.rel1_dx)
    local related_dy = tonumber(selected.rel1_dy)
    local related_distance = nil
    if related_dx ~= nil and related_dy ~= nil then
        related_distance = math.sqrt(related_dx * related_dx + related_dy * related_dy)
    end

    selected_target.related_distance = related_distance
    selected_target.distance = distance
    selected_target.anchor_relaxed = anchor_relaxed
    return selected_target
end

function M.clear_cached_dialogue_jump_button_target()
    state.cached_dialogue_jump_button_target = nil
    state.cached_dialogue_jump_button_target_at = 0
    _G.AVEPOINT_CACHED_DIALOGUE_JUMP_BUTTON_TARGET = nil
    M.clear_button_session_entry("dialogue_jump")
end

function M.clear_dialogue_jump_window_state()
    state.dialogue_jump_window_until = 0
    state.dialogue_jump_window_origin = nil
end

function M.clear_dialogue_jump_session_state()
    state.dialogue_jump_consumed = false
    state.dialogue_jump_consumed_at = 0
    state.dialogue_jump_consumed_source = nil
    state.dialogue_jump_consumed_addr = 0
end

function M.mark_dialogue_jump_consumed(ctx, current_time, target, source, interaction_origin)
    local consumed_at = tonumber(current_time) or now_ms(ctx)
    local target_addr = type(target) == "table" and tonumber(target.addr) or nil
    state.dialogue_jump_consumed = true
    state.dialogue_jump_consumed_at = consumed_at
    state.dialogue_jump_consumed_source = tostring(source or "")
    state.dialogue_jump_consumed_addr = target_addr or 0
    logger(ctx).info(string.format(
        "[Leveling] dialogue jump consumed | task=%s origin=%s source=%s addr=%s at=%d",
        tostring(state.current_task_name or ""),
        tostring(interaction_origin or state.pending_interaction_origin or ""),
        tostring(source or ""),
        tostring(target_addr or ""),
        consumed_at
    ))
end

function M.cache_dialogue_jump_button_target(ctx, target_like, current_time, source, step)
    local target = M.extract_dialogue_jump_button_target(target_like)
    if type(target) ~= "table" then
        return nil
    end

    local buttons = type(M._leveling_buttons) == "table" and M._leveling_buttons or nil
    if type(buttons) == "table" and type(buttons.target_matches_slot) == "function" then
        local ok, reject = buttons.target_matches_slot("dialogue_jump", target)
        if not ok then
            logger(ctx).warn(string.format(
                "[Leveling] dialogue jump cache rejected by button registry | reject=%s target=%s",
                tostring(reject or ""),
                M.format_main_task_click_target_brief(target)
            ))
            return nil
        end
    end

    local cached = {
        kind = "button",
        slot = "dialogue_jump",
        addr = tonumber(target.addr),
        name = tostring(target.name or ""),
        fullname = tostring(target.fullname or ""),
        x = tonumber(target.x),
        y = tonumber(target.y),
        text = tostring(target.text or ""),
        related_text = tostring(target.related_text or ""),
        related_distance = tonumber(target.related_distance),
        captured_at = tonumber(current_time) or 0,
        source = tostring(source or "")
    }

    local nav_mod = nav_api(ctx)
    local wnd_api = type(ctx) == "table" and ctx.wnd or wnd
    if type(nav_mod) == "table"
        and type(nav_mod.window_hwnd) == "function"
        and type(wnd_api) == "table"
        and type(wnd_api.client_rect) == "function"
    then
        local hwnd = select(1, nav_mod.window_hwnd())
        if hwnd then
            local _, _, client_w, client_h = wnd_api.client_rect(hwnd)
            if type(client_w) == "number" and client_w > 0 and cached.x ~= nil then
                cached.hint_ratio_x = cached.x / client_w
            elseif type(step) == "table" then
                cached.hint_ratio_x = tonumber(step.hint_ratio_x)
            end
            if type(client_h) == "number" and client_h > 0 and cached.y ~= nil then
                cached.hint_ratio_y = cached.y / client_h
            elseif type(step) == "table" then
                cached.hint_ratio_y = tonumber(step.hint_ratio_y)
            end
        end
    end

    local current_pid = tonumber(type(nav_mod) == "table" and nav_mod.pid or 0)
    if current_pid ~= nil and current_pid > 0 then
        cached.pid = current_pid
    end
    cached.session_key = M.build_button_session_key(nav_mod)
    if M.button_call_cache_disabled() then
        return cached
    end

    local previous_cached = type(state.cached_dialogue_jump_button_target) == "table"
        and state.cached_dialogue_jump_button_target
        or type(_G.AVEPOINT_CACHED_DIALOGUE_JUMP_BUTTON_TARGET) == "table"
            and _G.AVEPOINT_CACHED_DIALOGUE_JUMP_BUTTON_TARGET
        or nil
    M.log_button_slot_addr_change(ctx, "dialogue_jump", previous_cached, cached, source)
    state.cached_dialogue_jump_button_target = cached
    state.cached_dialogue_jump_button_target_at = cached.captured_at
    _G.AVEPOINT_CACHED_DIALOGUE_JUMP_BUTTON_TARGET = M.copy_main_task_button_cache_fields(cached)
    M.persist_button_session_entry("dialogue_jump", cached)
    return cached
end

function M.resolve_cached_dialogue_jump_button_target(nav_mod, current_time)
    local cached = state.cached_dialogue_jump_button_target
    if type(cached) ~= "table" and type(_G.AVEPOINT_CACHED_DIALOGUE_JUMP_BUTTON_TARGET) == "table" then
        cached = _G.AVEPOINT_CACHED_DIALOGUE_JUMP_BUTTON_TARGET
    end
    if type(cached) ~= "table" then
        cached = M.read_button_session_entry(nav_mod, "dialogue_jump")
        if type(cached) == "table" then
            state.cached_dialogue_jump_button_target = cached
            state.cached_dialogue_jump_button_target_at = tonumber(cached.captured_at) or 0
            _G.AVEPOINT_CACHED_DIALOGUE_JUMP_BUTTON_TARGET = M.copy_main_task_button_cache_fields(cached)
        end
    end
    if type(cached) ~= "table" then
        return nil, "cached dialogue jump button target unavailable."
    end

    local addr = tonumber(cached.addr)
    local x = tonumber(cached.x)
    local y = tonumber(cached.y)
    if addr == nil or addr == 0 or x == nil or y == nil then
        M.clear_cached_dialogue_jump_button_target()
        return nil, "cached dialogue jump button target is invalid."
    end

    local cached_pid = tonumber(cached.pid or 0)
    local current_pid = tonumber(type(nav_mod) == "table" and nav_mod.pid or 0)
    if cached_pid > 0 and current_pid > 0 and cached_pid ~= current_pid then
        M.clear_cached_dialogue_jump_button_target()
        return nil, string.format(
            "cached dialogue jump button target pid changed. cached=%d current=%d",
            cached_pid,
            current_pid
        )
    end

    local cached_session_key = trim(cached.session_key or "")
    local current_session_key = M.build_button_session_key(nav_mod)
    if cached_session_key ~= "" and current_session_key ~= "" and cached_session_key ~= current_session_key then
        M.clear_cached_dialogue_jump_button_target()
        return nil, string.format(
            "cached dialogue jump button target session changed. cached=%s current=%s",
            cached_session_key,
            current_session_key
        )
    end

    local buttons = type(M._leveling_buttons) == "table" and M._leveling_buttons or nil
    if type(buttons) == "table" and type(buttons.cache_matches_process) == "function" then
        local process_ok, process_reason = buttons.cache_matches_process(
            cached,
            M.build_button_session_key(nav_mod)
        )
        if not process_ok then
            M.clear_cached_dialogue_jump_button_target()
            return nil, "cached dialogue jump button target process changed: " .. tostring(process_reason or "")
        end
    end

    local captured_at = tonumber(state.cached_dialogue_jump_button_target_at) or tonumber(cached.captured_at) or 0
    if captured_at > 0 and tonumber(current_time) ~= nil then
        state.cached_dialogue_jump_button_target_at = captured_at
    end

    local target = {
        kind = "button",
        addr = addr,
        name = tostring(cached.name or ""),
        text = tostring(cached.text or ""),
        fullname = tostring(cached.fullname or ""),
        x = x,
        y = y,
        related_text = tostring(cached.related_text or ""),
        related_distance = tonumber(cached.related_distance),
        distance = 0,
        source = tostring(cached.source or ""),
        pid = cached_pid > 0 and cached_pid or nil
    }

    if type(buttons) == "table" and type(buttons.target_matches_slot) == "function" then
        local ok, reject = buttons.target_matches_slot("dialogue_jump", target)
        if not ok then
            return nil, "cached dialogue jump button target rejected by registry: " .. tostring(reject or "")
        end
    end

    return target
end

function M.clear_cached_dialogue_jump_addr_with_log(ctx, reason)
    M.clear_cached_dialogue_jump_button_target()
    logger(ctx).info(string.format(
        "[Leveling] cleared cached dialogue jump addr | reason=%s",
        tostring(reason or "")
    ))
end

function M.try_cached_dialogue_jump_button_click(ctx, nav_mod, current_time, step, reason)
    if type(nav_mod) ~= "table" or type(nav_mod.control_click) ~= "function" then
        return false, "nav.control_click is unavailable."
    end

    local cached_target, cached_err = M.resolve_cached_dialogue_jump_button_target(nav_mod, current_time)
    if type(cached_target) ~= "table" then
        return false, cached_err
    end

    local click_ok, click_err = nav_mod.control_click(cached_target.addr)
    if not click_ok then
        M.clear_cached_dialogue_jump_addr_with_log(ctx, click_err or "cached dialogue jump addr click failed")
        return false, click_err
    end

    logger(ctx).info(string.format(
        "[Leveling] dialogue jump button clicked | source=cached_addr addr=%s pos=(%s,%s) anchor=%s cache_source=%s reason=%s",
        tostring(cached_target.addr or ""),
        tostring(cached_target.x or ""),
        tostring(cached_target.y or ""),
        tostring(type(step) == "table" and step.distance_anchor_exact_text or ""),
        tostring(cached_target.source or ""),
        tostring(reason or "")
    ))
    return true, cached_target
end

function M.try_capture_dialogue_jump_button_via_hover(ctx, nav_mod, current_time, step, reason)
    if M.button_call_hover_capture_disabled() then
        return nil, "dialogue jump hover capture globally disabled."
    end

    if type(step) ~= "table" then
        return nil, "dialogue jump step unavailable."
    end

    local retry_gate = tonumber(state.next_dialogue_jump_hover_capture_at) or 0
    if retry_gate > current_time then
        return nil, string.format(
            "dialogue jump hover capture cooldown until=%d now=%d",
            retry_gate,
            current_time
        )
    end
    if type(nav_mod) ~= "table" or type(nav_mod.move_mouse_to_client) ~= "function" then
        return nil, "nav.move_mouse_to_client is unavailable."
    end

    local capture_bounds, bounds_summary = M.resolve_main_task_hover_capture_bounds(step)
    if type(capture_bounds) ~= "table" then
        state.next_dialogue_jump_hover_capture_at = current_time
            + math.max(300, tonumber(step.hover_capture_retry_ms) or 900)
        return nil, bounds_summary
    end

    local original_cursor = nil
    if type(nav_mod.cursor_client_pos) == "function" then
        original_cursor = select(1, nav_mod.cursor_client_pos({
            allow_outside = true
        }))
    end

    local capture_candidate, capture_summary = M.choose_main_task_hover_candidate(
        "capture",
        original_cursor,
        capture_bounds,
        step,
        "jump"
    )
    if type(capture_candidate) ~= "table" then
        state.next_dialogue_jump_hover_capture_at = current_time
            + math.max(300, tonumber(step.hover_capture_retry_ms) or 900)
        return nil, capture_summary
    end

    local moved, move_result = nav_mod.move_mouse_to_client(capture_candidate.x, capture_candidate.y, {
        mouse_mode = "api",
        min_duration_ms = capture_candidate.move_min_ms,
        max_duration_ms = capture_candidate.move_max_ms,
        hover_ms = capture_candidate.hover_ms,
        set_foreground = true
    })
    if moved then
        local capture_entry = {
            x = capture_candidate.x,
            y = capture_candidate.y,
            zone = capture_candidate.zone,
            angle_deg = capture_candidate.angle_deg,
            move_min_ms = capture_candidate.move_min_ms,
            move_max_ms = capture_candidate.move_max_ms,
            hover_ms = capture_candidate.hover_ms,
            move_duration_ms = tonumber(type(move_result) == "table" and move_result.duration_ms),
            move_style = tostring(type(move_result) == "table" and move_result.move_style or ""),
            sample_attempt = capture_candidate.sample_attempt,
            score = capture_candidate.score,
            outcome = "hover_probe"
        }
        M.push_main_task_hover_history("capture", capture_entry, capture_candidate.history_limit, "jump")
        state.last_dialogue_jump_hover_capture_meta = capture_entry

        local selected_target, selected_err = M.resolve_dialogue_jump_selected_target(nav_mod, step)
        if type(selected_target) == "table" then
            local cached = M.cache_dialogue_jump_button_target(
                ctx,
                selected_target,
                current_time,
                "hover_capture:randomized",
                step
            )
            if type(cached) == "table" then
                state.next_dialogue_jump_hover_capture_at = 0
                local return_note = "return=skipped"
                local return_bounds, return_bounds_err = M.resolve_main_task_hover_return_bounds(nav_mod, step)
                if type(return_bounds) == "table" then
                    local return_origin = {
                        client_x = capture_candidate.x,
                        client_y = capture_candidate.y
                    }
                    local return_candidate, return_summary = M.choose_main_task_hover_candidate(
                        "return",
                        return_origin,
                        return_bounds,
                        step,
                        "jump"
                    )
                    if type(return_candidate) == "table" then
                        local returned, return_result = nav_mod.move_mouse_to_client(return_candidate.x, return_candidate.y, {
                            mouse_mode = "api",
                            min_duration_ms = return_candidate.move_min_ms,
                            max_duration_ms = return_candidate.move_max_ms,
                            hover_ms = return_candidate.hover_ms
                        })
                        if returned then
                            local return_entry = {
                                x = return_candidate.x,
                                y = return_candidate.y,
                                zone = return_candidate.zone,
                                angle_deg = return_candidate.angle_deg,
                                move_min_ms = return_candidate.move_min_ms,
                                move_max_ms = return_candidate.move_max_ms,
                                hover_ms = return_candidate.hover_ms,
                                move_duration_ms = tonumber(type(return_result) == "table" and return_result.duration_ms),
                                move_style = tostring(type(return_result) == "table" and return_result.move_style or ""),
                                sample_attempt = return_candidate.sample_attempt,
                                score = return_candidate.score,
                                outcome = "safe_return"
                            }
                            M.push_main_task_hover_history("return", return_entry, return_candidate.history_limit, "jump")
                            state.last_dialogue_jump_hover_return_meta = return_entry
                            return_note = string.format(
                                "return=%s move_style=%s move_duration=%s summary=%s",
                                M.format_main_task_hover_candidate_brief(return_candidate),
                                tostring(return_entry.move_style or ""),
                                tostring(return_entry.move_duration_ms or ""),
                                tostring(return_summary or "")
                            )
                        else
                            return_note = string.format(
                                "return_move_failed=%s candidate=%s summary=%s",
                                tostring(return_result or ""),
                                M.format_main_task_hover_candidate_brief(return_candidate),
                                tostring(return_summary or "")
                            )
                        end
                    else
                        return_note = "return_candidate_failed=" .. tostring(return_summary or "")
                    end
                else
                    return_note = "return_bounds_failed=" .. tostring(return_bounds_err or "")
                end

                logger(ctx).info(string.format(
                    "[Leveling] cached dialogue jump addr via hover | hover=%s move_style=%s move_duration=%s target=%s bounds=%s capture_summary=%s %s anchor_relaxed=%s reason=%s",
                    M.format_main_task_hover_candidate_brief(capture_candidate),
                    tostring(type(move_result) == "table" and move_result.move_style or ""),
                    tostring(type(move_result) == "table" and move_result.duration_ms or ""),
                    M.format_main_task_click_target_brief(selected_target),
                    tostring(bounds_summary or ""),
                    tostring(capture_summary or ""),
                    tostring(return_note or ""),
                    tostring(selected_target.anchor_relaxed == true),
                    tostring(reason or "")
                ))
                return selected_target
            end
            selected_err = "cache_failed"
        end

        if step.hover_capture_restore_cursor_on_failure ~= false and type(original_cursor) == "table" then
            local restore_timing = M.randomize_main_task_hover_timing("return", step)
            nav_mod.move_mouse_to_client(original_cursor.client_x, original_cursor.client_y, {
                mouse_mode = "api",
                min_duration_ms = restore_timing.move_min_ms,
                max_duration_ms = restore_timing.move_max_ms,
                hover_ms = math.min(24, math.max(0, math.floor((tonumber(restore_timing.hover_ms) or 0) * 0.35)))
            })
        end

        state.next_dialogue_jump_hover_capture_at = current_time
            + math.max(300, tonumber(step.hover_capture_retry_ms) or 900)
        return nil, string.format(
            "dialogue_jump_hover_selected_failed=%s hover=%s move_style=%s move_duration=%s bounds=%s capture_summary=%s",
            tostring(selected_err or ""),
            M.format_main_task_hover_candidate_brief(capture_candidate),
            tostring(type(move_result) == "table" and move_result.move_style or ""),
            tostring(type(move_result) == "table" and move_result.duration_ms or ""),
            tostring(bounds_summary or ""),
            tostring(capture_summary or "")
        )
    end

    if step.hover_capture_restore_cursor_on_failure ~= false and type(original_cursor) == "table" then
        local restore_timing = M.randomize_main_task_hover_timing("return", step)
        nav_mod.move_mouse_to_client(original_cursor.client_x, original_cursor.client_y, {
            mouse_mode = "api",
            min_duration_ms = restore_timing.move_min_ms,
            max_duration_ms = restore_timing.move_max_ms,
            hover_ms = math.min(24, math.max(0, math.floor((tonumber(restore_timing.hover_ms) or 0) * 0.35)))
        })
    end

    state.next_dialogue_jump_hover_capture_at = current_time
        + math.max(300, tonumber(step.hover_capture_retry_ms) or 900)
    return nil, string.format(
        "dialogue_jump_hover_move_failed=%s hover=%s bounds=%s capture_summary=%s",
        tostring(move_result or ""),
        M.format_main_task_hover_candidate_brief(capture_candidate),
        tostring(bounds_summary or ""),
        tostring(capture_summary or "")
    )
end

function M.extract_interaction_prompt_button_target(target_like)
    if type(target_like) ~= "table" then
        return nil
    end

    local source = type(target_like._interaction_prompt_clicked_target) == "table"
        and target_like._interaction_prompt_clicked_target
        or target_like

    local kind = tostring(source.kind or source.button_kind or target_like.button_kind or "")
    local addr = tonumber(source.addr or source.button_addr or target_like.button_addr)
    local x = tonumber(source.x or source.button_x or target_like.button_x or target_like.x)
    local y = tonumber(source.y or source.button_y or target_like.button_y or target_like.y)
    local name = tostring(source.name or source.button_name or target_like.button_name or "")
    local fullname = tostring(
        source.fullname
            or source.Fullname
            or source.button_fullname
            or target_like.button_fullname
            or ""
    )
    if addr == nil or addr == 0 or x == nil or y == nil then
        return nil
    end

    local target = {
        kind = "button",
        addr = addr,
        name = name,
        text = tostring(source.text or target_like.text or ""),
        fullname = fullname,
        x = x,
        y = y,
        related_text = tostring(source.related_text or source.rel1_text or target_like.related_text or ""),
        related_distance = tonumber(source.related_distance),
        distance = tonumber(source.distance)
    }

    local buttons = type(M._leveling_buttons) == "table" and M._leveling_buttons or nil
    if type(buttons) == "table" and type(buttons.target_matches_slot) == "function" then
        local ok = select(1, buttons.target_matches_slot("interaction_prompt", target))
        if not ok then
            return nil
        end
    else
        local identity = (fullname .. " " .. name):lower()
        local is_button = kind == "button"
            or identity:find("fightinteractiveview_c.widgettree.functionbtn", 1, true) ~= nil
        if not is_button then
            return nil
        end
    end

    return target
end

function M.resolve_interaction_prompt_selected_target(nav_mod, step)
    if type(nav_mod) ~= "table" or type(nav_mod.get_current_selected_button) ~= "function" then
        return nil, "nav.get_current_selected_button is unavailable."
    end

    local selected, selected_err = nav_mod.get_current_selected_button()
    if type(selected) ~= "table" then
        return nil, selected_err or "Current selected button not found."
    end

    local addr = tonumber(selected.addr)
    local x = tonumber(selected.x)
    local y = tonumber(selected.y)
    local fullname = tostring(selected.Fullname or selected.fullname or "")
    local name = tostring(selected.name or "")
    local selected_text = tostring(selected.text or "")
    local related_text = tostring(selected.rel1_text or "")
    if addr == nil or addr == 0 or x == nil or y == nil then
        return nil, string.format(
            "GetCurrentSelected returned invalid FunctionBtn data. addr=%s pos=(%s,%s) name=%s fullname=%s text=%s related=%s",
            tostring(selected.addr or ""),
            tostring(selected.x or ""),
            tostring(selected.y or ""),
            name,
            fullname,
            selected_text,
            related_text
        )
    end

    local selected_target = {
        kind = "button",
        addr = addr,
        name = name,
        text = selected_text,
        fullname = fullname,
        x = x,
        y = y,
        related_text = related_text
    }
    local buttons = type(M._leveling_buttons) == "table" and M._leveling_buttons or nil
    local selected_matches = false
    local selected_reject = nil
    if type(buttons) == "table" and type(buttons.target_matches_slot) == "function" then
        selected_matches, selected_reject = buttons.target_matches_slot("interaction_prompt", selected_target)
    else
        local identity = (fullname .. " " .. name):lower()
        selected_matches = identity:find("fightinteractiveview_c.widgettree.functionbtn", 1, true) ~= nil
    end
    if selected_matches ~= true then
        return nil, string.format(
            "GetCurrentSelected is not FunctionBtn. addr=%s pos=(%s,%s) name=%s fullname=%s text=%s related=%s reject=%s",
            tostring(addr or ""),
            tostring(x or ""),
            tostring(y or ""),
            name,
            fullname,
            selected_text,
            related_text,
            tostring(selected_reject or "")
        )
    end

    local hint_x = tonumber(type(step) == "table" and step.hint_client_x or nil)
    local hint_y = tonumber(type(step) == "table" and step.hint_client_y or nil)
    local distance = 0
    if hint_x ~= nil and hint_y ~= nil then
        distance = distance_2d(hint_x, hint_y, x, y)
        if distance > math.max(tonumber(type(step) == "table" and step.hint_max_distance or 96) or 96, 120) then
            return nil, string.format(
                "GetCurrentSelected FunctionBtn too far from hint: %.2f selected=(%.2f,%.2f) hint=(%.2f,%.2f)",
                tonumber(distance) or 0,
                x,
                y,
                tonumber(hint_x) or 0,
                tonumber(hint_y) or 0
            )
        end
    end

    local related_dx = tonumber(selected.rel1_dx)
    local related_dy = tonumber(selected.rel1_dy)
    local related_distance = tonumber(selected.rel1_distance)
    if related_distance == nil and related_dx ~= nil and related_dy ~= nil then
        related_distance = math.sqrt(related_dx * related_dx + related_dy * related_dy)
    end

    selected_target.related_distance = related_distance
    selected_target.distance = distance
    return selected_target
end

function M.clear_cached_interaction_prompt_button_target()
    state.cached_interaction_prompt_target = nil
    state.cached_interaction_prompt_target_at = 0
    state.cached_interaction_prompt_error = nil
    _G.AVEPOINT_CACHED_INTERACTION_PROMPT_TARGET = nil
    M.clear_button_session_entry("interaction_prompt")
end

function M.cache_interaction_prompt_button_target(ctx, target_like, current_time, source, step)
    local target = M.extract_interaction_prompt_button_target(target_like)
    if type(target) ~= "table" then
        return nil
    end

    local buttons = type(M._leveling_buttons) == "table" and M._leveling_buttons or nil
    if type(buttons) == "table" and type(buttons.target_matches_slot) == "function" then
        local ok, reject = buttons.target_matches_slot("interaction_prompt", target)
        if not ok then
            logger(ctx).warn(string.format(
                "[Leveling] interaction prompt cache rejected by button registry | reject=%s target=%s",
                tostring(reject or ""),
                M.format_main_task_click_target_brief(target)
            ))
            return nil
        end
    end

    local cached = {
        kind = "button",
        slot = "interaction_prompt",
        addr = tonumber(target.addr),
        name = tostring(target.name or ""),
        fullname = tostring(target.fullname or ""),
        x = tonumber(target.x),
        y = tonumber(target.y),
        text = tostring(target.text or ""),
        related_text = tostring(target.related_text or ""),
        related_distance = tonumber(target.related_distance),
        captured_at = tonumber(current_time) or 0,
        source = tostring(source or "")
    }

    local nav_mod = nav_api(ctx)
    local wnd_api = type(ctx) == "table" and ctx.wnd or wnd
    if type(nav_mod) == "table"
        and type(nav_mod.window_hwnd) == "function"
        and type(wnd_api) == "table"
        and type(wnd_api.client_rect) == "function"
    then
        local hwnd = select(1, nav_mod.window_hwnd())
        if hwnd then
            local _, _, client_w, client_h = wnd_api.client_rect(hwnd)
            if type(client_w) == "number" and client_w > 0 and cached.x ~= nil then
                cached.hint_ratio_x = cached.x / client_w
            elseif type(step) == "table" then
                cached.hint_ratio_x = tonumber(step.hint_ratio_x)
            end
            if type(client_h) == "number" and client_h > 0 and cached.y ~= nil then
                cached.hint_ratio_y = cached.y / client_h
            elseif type(step) == "table" then
                cached.hint_ratio_y = tonumber(step.hint_ratio_y)
            end
        end
    end

    local current_pid = tonumber(type(nav_mod) == "table" and nav_mod.pid or 0)
    if current_pid ~= nil and current_pid > 0 then
        cached.pid = current_pid
    end
    cached.session_key = M.build_button_session_key(nav_mod)
    if M.button_call_cache_disabled() then
        return cached
    end

    local previous_cached = type(state.cached_interaction_prompt_target) == "table"
        and state.cached_interaction_prompt_target
        or type(_G.AVEPOINT_CACHED_INTERACTION_PROMPT_TARGET) == "table"
            and _G.AVEPOINT_CACHED_INTERACTION_PROMPT_TARGET
        or nil
    M.log_button_slot_addr_change(ctx, "interaction_prompt", previous_cached, cached, source)
    state.cached_interaction_prompt_target = cached
    state.cached_interaction_prompt_target_at = cached.captured_at
    state.cached_interaction_prompt_error = nil
    _G.AVEPOINT_CACHED_INTERACTION_PROMPT_TARGET = M.copy_main_task_button_cache_fields(cached)
    M.persist_button_session_entry("interaction_prompt", cached)
    return cached
end

function M.resolve_cached_interaction_prompt_button_target(nav_mod, current_time)
    local cached = state.cached_interaction_prompt_target
    if type(cached) ~= "table" and type(_G.AVEPOINT_CACHED_INTERACTION_PROMPT_TARGET) == "table" then
        cached = _G.AVEPOINT_CACHED_INTERACTION_PROMPT_TARGET
    end
    if type(cached) ~= "table" then
        cached = M.read_button_session_entry(nav_mod, "interaction_prompt")
        if type(cached) == "table" then
            state.cached_interaction_prompt_target = cached
            state.cached_interaction_prompt_target_at = tonumber(cached.captured_at) or 0
            state.cached_interaction_prompt_error = nil
            _G.AVEPOINT_CACHED_INTERACTION_PROMPT_TARGET = M.copy_main_task_button_cache_fields(cached)
        end
    end
    if type(cached) ~= "table" then
        return nil, "cached interaction prompt button target unavailable."
    end

    local addr = tonumber(cached.addr)
    local x = tonumber(cached.x)
    local y = tonumber(cached.y)
    if addr == nil or addr == 0 or x == nil or y == nil then
        M.clear_cached_interaction_prompt_button_target()
        return nil, "cached interaction prompt button target is invalid."
    end

    local cached_pid = tonumber(cached.pid or 0)
    local current_pid = tonumber(type(nav_mod) == "table" and nav_mod.pid or 0)
    if cached_pid > 0 and current_pid > 0 and cached_pid ~= current_pid then
        M.clear_cached_interaction_prompt_button_target()
        return nil, string.format(
            "cached interaction prompt button target pid changed. cached=%d current=%d",
            cached_pid,
            current_pid
        )
    end

    local cached_session_key = trim(cached.session_key or "")
    local current_session_key = M.build_button_session_key(nav_mod)
    if cached_session_key ~= "" and current_session_key ~= "" and cached_session_key ~= current_session_key then
        M.clear_cached_interaction_prompt_button_target()
        return nil, string.format(
            "cached interaction prompt button target session changed. cached=%s current=%s",
            cached_session_key,
            current_session_key
        )
    end

    local buttons = type(M._leveling_buttons) == "table" and M._leveling_buttons or nil
    if type(buttons) == "table" and type(buttons.cache_matches_process) == "function" then
        local process_ok, process_reason = buttons.cache_matches_process(
            cached,
            M.build_button_session_key(nav_mod)
        )
        if not process_ok then
            M.clear_cached_interaction_prompt_button_target()
            return nil, "cached interaction prompt button target process changed: " .. tostring(process_reason or "")
        end
    end

    local captured_at = tonumber(state.cached_interaction_prompt_target_at) or tonumber(cached.captured_at) or 0
    if captured_at > 0 and tonumber(current_time) ~= nil then
        state.cached_interaction_prompt_target_at = captured_at
    end

    local target = {
        kind = "button",
        addr = addr,
        name = tostring(cached.name or ""),
        text = tostring(cached.text or ""),
        fullname = tostring(cached.fullname or ""),
        x = x,
        y = y,
        related_text = tostring(cached.related_text or ""),
        related_distance = tonumber(cached.related_distance),
        distance = 0,
        source = tostring(cached.source or ""),
        pid = cached_pid > 0 and cached_pid or nil
    }

    if type(buttons) == "table" and type(buttons.target_matches_slot) == "function" then
        local ok, reject = buttons.target_matches_slot("interaction_prompt", target)
        if not ok then
            return nil, "cached interaction prompt button target rejected by registry: " .. tostring(reject or "")
        end
    end

    return target
end

function M.clear_cached_interaction_prompt_addr_with_log(ctx, reason)
    M.clear_cached_interaction_prompt_button_target()
    logger(ctx).info(string.format(
        "[Leveling] cleared cached interaction prompt addr | reason=%s",
        tostring(reason or "")
    ))
end

function M.try_cached_interaction_prompt_button_click(ctx, nav_mod, current_time, step, reason)
    local cached_target, cached_err = M.resolve_cached_interaction_prompt_button_target(nav_mod, current_time)
    if type(cached_target) ~= "table" then
        return false, cached_err
    end

    return false, string.format(
        "cached interaction prompt target requires live guard before click. addr=%s pos=(%s,%s) cache_source=%s reason=%s",
        tostring(cached_target.addr or ""),
        tostring(cached_target.x or ""),
        tostring(cached_target.y or ""),
        tostring(cached_target.source or ""),
        tostring(reason or "")
    )
end

function M.try_capture_interaction_prompt_button_via_hover(ctx, nav_mod, current_time, step, reason, opts)
    if M.button_call_hover_capture_disabled() then
        return nil, "interaction prompt hover capture globally disabled."
    end

    if type(step) ~= "table" then
        return nil, "interaction prompt step unavailable."
    end

    opts = type(opts) == "table" and opts or {}
    local retry_gate = tonumber(state.next_interaction_prompt_hover_capture_at) or 0
    if retry_gate > current_time and opts.ignore_retry_gate ~= true then
        return nil, string.format(
            "interaction prompt hover capture cooldown until=%d now=%d",
            retry_gate,
            current_time
        )
    elseif retry_gate > current_time and opts.ignore_retry_gate == true then
        logger(ctx).info(string.format(
            "[Leveling] interaction prompt hover capture cooldown bypassed | until=%d now=%d reason=%s",
            retry_gate,
            current_time,
            tostring(reason or "")
        ))
    end
    if type(nav_mod) ~= "table" or type(nav_mod.move_mouse_to_client) ~= "function" then
        return nil, "nav.move_mouse_to_client is unavailable."
    end

    local capture_bounds, bounds_summary = M.resolve_main_task_hover_capture_bounds(step)
    if type(capture_bounds) ~= "table" then
        state.next_interaction_prompt_hover_capture_at = current_time
            + math.max(300, tonumber(step.hover_capture_retry_ms) or 900)
        return nil, bounds_summary
    end

    local original_cursor = nil
    if type(nav_mod.cursor_client_pos) == "function" then
        original_cursor = select(1, nav_mod.cursor_client_pos({
            allow_outside = true
        }))
    end

    local capture_candidate, capture_summary = M.choose_main_task_hover_candidate(
        "capture",
        original_cursor,
        capture_bounds,
        step,
        "interaction_prompt"
    )
    if type(capture_candidate) ~= "table" then
        state.next_interaction_prompt_hover_capture_at = current_time
            + math.max(300, tonumber(step.hover_capture_retry_ms) or 900)
        return nil, capture_summary
    end

    local moved, move_result = nav_mod.move_mouse_to_client(capture_candidate.x, capture_candidate.y, {
        mouse_mode = "api",
        min_duration_ms = capture_candidate.move_min_ms,
        max_duration_ms = capture_candidate.move_max_ms,
        hover_ms = capture_candidate.hover_ms,
        set_foreground = true
    })
    if moved then
        local capture_entry = {
            x = capture_candidate.x,
            y = capture_candidate.y,
            zone = capture_candidate.zone,
            angle_deg = capture_candidate.angle_deg,
            move_min_ms = capture_candidate.move_min_ms,
            move_max_ms = capture_candidate.move_max_ms,
            hover_ms = capture_candidate.hover_ms,
            move_duration_ms = tonumber(type(move_result) == "table" and move_result.duration_ms),
            move_style = tostring(type(move_result) == "table" and move_result.move_style or ""),
            sample_attempt = capture_candidate.sample_attempt,
            score = capture_candidate.score,
            outcome = "hover_probe"
        }
        M.push_main_task_hover_history("capture", capture_entry, capture_candidate.history_limit, "interaction_prompt")
        state.last_interaction_prompt_hover_capture_meta = capture_entry

        local selected_target, selected_err = M.resolve_interaction_prompt_selected_target(nav_mod, step)
        if type(selected_target) == "table" then
            local cached = M.cache_interaction_prompt_button_target(
                ctx,
                selected_target,
                current_time,
                "hover_capture:randomized",
                step
            )
            if type(cached) == "table" then
                state.next_interaction_prompt_hover_capture_at = 0
                local return_note = "return=skipped"
                local return_bounds, return_bounds_err = M.resolve_main_task_hover_return_bounds(nav_mod, step)
                if type(return_bounds) == "table" then
                    local return_origin = {
                        client_x = capture_candidate.x,
                        client_y = capture_candidate.y
                    }
                    local return_candidate, return_summary = M.choose_main_task_hover_candidate(
                        "return",
                        return_origin,
                        return_bounds,
                        step,
                        "interaction_prompt"
                    )
                    if type(return_candidate) == "table" then
                        local returned, return_result = nav_mod.move_mouse_to_client(return_candidate.x, return_candidate.y, {
                            mouse_mode = "api",
                            min_duration_ms = return_candidate.move_min_ms,
                            max_duration_ms = return_candidate.move_max_ms,
                            hover_ms = return_candidate.hover_ms
                        })
                        if returned then
                            local return_entry = {
                                x = return_candidate.x,
                                y = return_candidate.y,
                                zone = return_candidate.zone,
                                angle_deg = return_candidate.angle_deg,
                                move_min_ms = return_candidate.move_min_ms,
                                move_max_ms = return_candidate.move_max_ms,
                                hover_ms = return_candidate.hover_ms,
                                move_duration_ms = tonumber(type(return_result) == "table" and return_result.duration_ms),
                                move_style = tostring(type(return_result) == "table" and return_result.move_style or ""),
                                sample_attempt = return_candidate.sample_attempt,
                                score = return_candidate.score,
                                outcome = "safe_return"
                            }
                            M.push_main_task_hover_history("return", return_entry, return_candidate.history_limit, "interaction_prompt")
                            state.last_interaction_prompt_hover_return_meta = return_entry
                            return_note = string.format(
                                "return=%s move_style=%s move_duration=%s summary=%s",
                                M.format_main_task_hover_candidate_brief(return_candidate),
                                tostring(return_entry.move_style or ""),
                                tostring(return_entry.move_duration_ms or ""),
                                tostring(return_summary or "")
                            )
                        else
                            return_note = string.format(
                                "return_move_failed=%s candidate=%s summary=%s",
                                tostring(return_result or ""),
                                M.format_main_task_hover_candidate_brief(return_candidate),
                                tostring(return_summary or "")
                            )
                        end
                    else
                        return_note = "return_candidate_failed=" .. tostring(return_summary or "")
                    end
                else
                    return_note = "return_bounds_failed=" .. tostring(return_bounds_err or "")
                end

                logger(ctx).info(string.format(
                    "[Leveling] cached interaction prompt addr via hover | hover=%s move_style=%s move_duration=%s target=%s bounds=%s capture_summary=%s %s reason=%s",
                    M.format_main_task_hover_candidate_brief(capture_candidate),
                    tostring(type(move_result) == "table" and move_result.move_style or ""),
                    tostring(type(move_result) == "table" and move_result.duration_ms or ""),
                    M.format_main_task_click_target_brief(selected_target),
                    tostring(bounds_summary or ""),
                    tostring(capture_summary or ""),
                    tostring(return_note or ""),
                    tostring(reason or "")
                ))
                return selected_target
            end
            selected_err = "cache_failed"
        end

        if step.hover_capture_restore_cursor_on_failure ~= false and type(original_cursor) == "table" then
            local restore_timing = M.randomize_main_task_hover_timing("return", step)
            nav_mod.move_mouse_to_client(original_cursor.client_x, original_cursor.client_y, {
                mouse_mode = "api",
                min_duration_ms = restore_timing.move_min_ms,
                max_duration_ms = restore_timing.move_max_ms,
                hover_ms = math.min(24, math.max(0, math.floor((tonumber(restore_timing.hover_ms) or 0) * 0.35)))
            })
        end

        state.next_interaction_prompt_hover_capture_at = current_time
            + math.max(300, tonumber(step.hover_capture_retry_ms) or 900)
        return nil, string.format(
            "interaction_prompt_hover_selected_failed=%s hover=%s move_style=%s move_duration=%s bounds=%s capture_summary=%s",
            tostring(selected_err or ""),
            M.format_main_task_hover_candidate_brief(capture_candidate),
            tostring(type(move_result) == "table" and move_result.move_style or ""),
            tostring(type(move_result) == "table" and move_result.duration_ms or ""),
            tostring(bounds_summary or ""),
            tostring(capture_summary or "")
        )
    end

    if step.hover_capture_restore_cursor_on_failure ~= false and type(original_cursor) == "table" then
        local restore_timing = M.randomize_main_task_hover_timing("return", step)
        nav_mod.move_mouse_to_client(original_cursor.client_x, original_cursor.client_y, {
            mouse_mode = "api",
            min_duration_ms = restore_timing.move_min_ms,
            max_duration_ms = restore_timing.move_max_ms,
            hover_ms = math.min(24, math.max(0, math.floor((tonumber(restore_timing.hover_ms) or 0) * 0.35)))
        })
    end

    state.next_interaction_prompt_hover_capture_at = current_time
        + math.max(300, tonumber(step.hover_capture_retry_ms) or 900)
    return nil, string.format(
        "interaction_prompt_hover_move_failed=%s hover=%s bounds=%s capture_summary=%s",
        tostring(move_result or ""),
        M.format_main_task_hover_candidate_brief(capture_candidate),
        tostring(bounds_summary or ""),
        tostring(capture_summary or "")
    )
end

function M.extract_task_entry_send_button_target(target_like)
    if type(target_like) ~= "table" then
        return nil
    end

    local source = type(target_like._task_entry_send_clicked_target) == "table"
        and target_like._task_entry_send_clicked_target
        or target_like

    local kind = tostring(source.kind or source.button_kind or target_like.button_kind or "")
    local addr = tonumber(source.addr or source.button_addr or target_like.button_addr)
    local x = tonumber(source.x or source.button_x or target_like.button_x or target_like.x)
    local y = tonumber(source.y or source.button_y or target_like.button_y or target_like.y)
    local name = tostring(source.name or source.button_name or target_like.button_name or "")
    local fullname = tostring(
        source.fullname
            or source.Fullname
            or source.button_fullname
            or target_like.button_fullname
            or ""
    )
    if addr == nil or addr == 0 or x == nil or y == nil then
        return nil
    end

    local target = {
        kind = "button",
        addr = addr,
        name = name,
        text = tostring(source.text or target_like.text or ""),
        fullname = fullname,
        x = x,
        y = y,
        related_text = tostring(source.related_text or source.rel1_text or target_like.related_text or ""),
        related_distance = tonumber(source.related_distance),
        distance = tonumber(source.distance)
    }

    local buttons = type(M._leveling_buttons) == "table" and M._leveling_buttons or nil
    if type(buttons) == "table" and type(buttons.target_matches_slot) == "function" then
        local ok = select(1, buttons.target_matches_slot("task_entry_send", target))
        if not ok then
            return nil
        end
    else
        local identity = (fullname .. " " .. name):lower()
        local is_button = kind == "button"
            or identity:find("worldmapdetail_c.widgettree.worldmapdetailitem.widgettree.sendbtn", 1, true) ~= nil
        if not is_button then
            return nil
        end
    end

    return target
end

function M.resolve_task_entry_send_selected_target(nav_mod, step)
    if type(nav_mod) ~= "table" or type(nav_mod.get_current_selected_button) ~= "function" then
        return nil, "nav.get_current_selected_button is unavailable."
    end

    local selected, selected_err = nav_mod.get_current_selected_button()
    if type(selected) ~= "table" then
        return nil, selected_err or "Current selected button not found."
    end

    local addr = tonumber(selected.addr)
    local x = tonumber(selected.x)
    local y = tonumber(selected.y)
    local fullname = tostring(selected.Fullname or selected.fullname or "")
    local name = tostring(selected.name or "")
    local selected_text = tostring(selected.text or "")
    local related_text = tostring(selected.rel1_text or "")
    if addr == nil or addr == 0 or x == nil or y == nil then
        return nil, string.format(
            "GetCurrentSelected returned invalid SendBtn data. addr=%s pos=(%s,%s) name=%s fullname=%s text=%s related=%s",
            tostring(selected.addr or ""),
            tostring(selected.x or ""),
            tostring(selected.y or ""),
            name,
            fullname,
            selected_text,
            related_text
        )
    end

    local selected_target = {
        kind = "button",
        addr = addr,
        name = name,
        text = selected_text,
        fullname = fullname,
        x = x,
        y = y,
        related_text = related_text
    }
    local buttons = type(M._leveling_buttons) == "table" and M._leveling_buttons or nil
    local selected_matches = false
    local selected_reject = nil
    if type(buttons) == "table" and type(buttons.target_matches_slot) == "function" then
        selected_matches, selected_reject = buttons.target_matches_slot("task_entry_send", selected_target)
    else
        local identity = (fullname .. " " .. name):lower()
        selected_matches = identity:find("worldmapdetail_c.widgettree.worldmapdetailitem.widgettree.sendbtn", 1, true) ~= nil
    end
    if selected_matches ~= true then
        return nil, string.format(
            "GetCurrentSelected is not SendBtn. addr=%s pos=(%s,%s) name=%s fullname=%s text=%s related=%s reject=%s",
            tostring(addr or ""),
            tostring(x or ""),
            tostring(y or ""),
            name,
            fullname,
            selected_text,
            related_text,
            tostring(selected_reject or "")
        )
    end

    local hint_x = tonumber(type(step) == "table" and step.hint_client_x or nil)
    local hint_y = tonumber(type(step) == "table" and step.hint_client_y or nil)
    local distance = 0
    if hint_x ~= nil and hint_y ~= nil then
        distance = distance_2d(hint_x, hint_y, x, y)
        if distance > math.max(tonumber(type(step) == "table" and step.hint_max_distance or 80) or 80, 120) then
            return nil, string.format(
                "GetCurrentSelected SendBtn too far from hint: %.2f selected=(%.2f,%.2f) hint=(%.2f,%.2f)",
                tonumber(distance) or 0,
                x,
                y,
                tonumber(hint_x) or 0,
                tonumber(hint_y) or 0
            )
        end
    end

    local related_dx = tonumber(selected.rel1_dx)
    local related_dy = tonumber(selected.rel1_dy)
    local related_distance = tonumber(selected.rel1_distance)
    if related_distance == nil and related_dx ~= nil and related_dy ~= nil then
        related_distance = math.sqrt(related_dx * related_dx + related_dy * related_dy)
    end

    selected_target.related_distance = related_distance
    selected_target.distance = distance
    return selected_target
end

function M.clear_cached_task_entry_send_button_target()
    state.cached_task_entry_send_target = nil
    state.cached_task_entry_send_target_at = 0
    state.cached_task_entry_send_error = nil
    _G.AVEPOINT_CACHED_TASK_ENTRY_SEND_TARGET = nil
    M.clear_button_session_entry("task_entry_send")
end

function M.cache_task_entry_send_button_target(ctx, target_like, current_time, source, step)
    local target = M.extract_task_entry_send_button_target(target_like)
    if type(target) ~= "table" then
        return nil
    end

    local buttons = type(M._leveling_buttons) == "table" and M._leveling_buttons or nil
    if type(buttons) == "table" and type(buttons.target_matches_slot) == "function" then
        local ok, reject = buttons.target_matches_slot("task_entry_send", target)
        if not ok then
            logger(ctx).warn(string.format(
                "[Leveling] task entry send cache rejected by button registry | reject=%s target=%s",
                tostring(reject or ""),
                M.format_main_task_click_target_brief(target)
            ))
            return nil
        end
    end

    local cached = {
        kind = "button",
        slot = "task_entry_send",
        addr = tonumber(target.addr),
        name = tostring(target.name or ""),
        fullname = tostring(target.fullname or ""),
        x = tonumber(target.x),
        y = tonumber(target.y),
        text = tostring(target.text or ""),
        related_text = tostring(target.related_text or ""),
        related_distance = tonumber(target.related_distance),
        captured_at = tonumber(current_time) or 0,
        source = tostring(source or "")
    }

    local nav_mod = nav_api(ctx)
    local wnd_api = type(ctx) == "table" and ctx.wnd or wnd
    if type(nav_mod) == "table"
        and type(nav_mod.window_hwnd) == "function"
        and type(wnd_api) == "table"
        and type(wnd_api.client_rect) == "function"
    then
        local hwnd = select(1, nav_mod.window_hwnd())
        if hwnd then
            local _, _, client_w, client_h = wnd_api.client_rect(hwnd)
            if type(client_w) == "number" and client_w > 0 and cached.x ~= nil then
                cached.hint_ratio_x = cached.x / client_w
            elseif type(step) == "table" then
                cached.hint_ratio_x = tonumber(step.hint_ratio_x)
            end
            if type(client_h) == "number" and client_h > 0 and cached.y ~= nil then
                cached.hint_ratio_y = cached.y / client_h
            elseif type(step) == "table" then
                cached.hint_ratio_y = tonumber(step.hint_ratio_y)
            end
        end
    end

    local current_pid = tonumber(type(nav_mod) == "table" and nav_mod.pid or 0)
    if current_pid ~= nil and current_pid > 0 then
        cached.pid = current_pid
    end
    cached.session_key = M.build_button_session_key(nav_mod)
    if M.button_call_cache_disabled() then
        return cached
    end

    local previous_cached = type(state.cached_task_entry_send_target) == "table"
        and state.cached_task_entry_send_target
        or type(_G.AVEPOINT_CACHED_TASK_ENTRY_SEND_TARGET) == "table"
            and _G.AVEPOINT_CACHED_TASK_ENTRY_SEND_TARGET
        or nil
    M.log_button_slot_addr_change(ctx, "task_entry_send", previous_cached, cached, source)
    state.cached_task_entry_send_target = cached
    state.cached_task_entry_send_target_at = cached.captured_at
    state.cached_task_entry_send_error = nil
    _G.AVEPOINT_CACHED_TASK_ENTRY_SEND_TARGET = M.copy_main_task_button_cache_fields(cached)
    M.persist_button_session_entry("task_entry_send", cached)
    return cached
end

function M.resolve_cached_task_entry_send_button_target(nav_mod, current_time)
    local cached = state.cached_task_entry_send_target
    if type(cached) ~= "table" and type(_G.AVEPOINT_CACHED_TASK_ENTRY_SEND_TARGET) == "table" then
        cached = _G.AVEPOINT_CACHED_TASK_ENTRY_SEND_TARGET
    end
    if type(cached) ~= "table" then
        cached = M.read_button_session_entry(nav_mod, "task_entry_send")
        if type(cached) == "table" then
            state.cached_task_entry_send_target = cached
            state.cached_task_entry_send_target_at = tonumber(cached.captured_at) or 0
            state.cached_task_entry_send_error = nil
            _G.AVEPOINT_CACHED_TASK_ENTRY_SEND_TARGET = M.copy_main_task_button_cache_fields(cached)
        end
    end
    if type(cached) ~= "table" then
        return nil, "cached task entry send button target unavailable."
    end

    local addr = tonumber(cached.addr)
    local x = tonumber(cached.x)
    local y = tonumber(cached.y)
    if addr == nil or addr == 0 or x == nil or y == nil then
        M.clear_cached_task_entry_send_button_target()
        return nil, "cached task entry send button target is invalid."
    end

    local cached_pid = tonumber(cached.pid or 0)
    local current_pid = tonumber(type(nav_mod) == "table" and nav_mod.pid or 0)
    if cached_pid > 0 and current_pid > 0 and cached_pid ~= current_pid then
        M.clear_cached_task_entry_send_button_target()
        return nil, string.format(
            "cached task entry send button target pid changed. cached=%d current=%d",
            cached_pid,
            current_pid
        )
    end

    local buttons = type(M._leveling_buttons) == "table" and M._leveling_buttons or nil
    if type(buttons) == "table" and type(buttons.cache_matches_process) == "function" then
        local process_ok, process_reason = buttons.cache_matches_process(
            cached,
            M.build_button_session_key(nav_mod)
        )
        if not process_ok then
            M.clear_cached_task_entry_send_button_target()
            return nil, "cached task entry send button target process changed: " .. tostring(process_reason or "")
        end
    end

    local captured_at = tonumber(state.cached_task_entry_send_target_at) or tonumber(cached.captured_at) or 0
    if captured_at > 0 and tonumber(current_time) ~= nil then
        state.cached_task_entry_send_target_at = captured_at
    end

    local target = {
        kind = "button",
        addr = addr,
        name = tostring(cached.name or ""),
        text = tostring(cached.text or ""),
        fullname = tostring(cached.fullname or ""),
        x = x,
        y = y,
        related_text = tostring(cached.related_text or ""),
        related_distance = tonumber(cached.related_distance),
        distance = 0,
        source = tostring(cached.source or ""),
        pid = cached_pid > 0 and cached_pid or nil
    }

    if type(buttons) == "table" and type(buttons.target_matches_slot) == "function" then
        local ok, reject = buttons.target_matches_slot("task_entry_send", target)
        if not ok then
            return nil, "cached task entry send button target rejected by registry: " .. tostring(reject or "")
        end
    end

    return target
end

function M.clear_cached_task_entry_send_addr_with_log(ctx, reason)
    M.clear_cached_task_entry_send_button_target()
    logger(ctx).info(string.format(
        "[Leveling] cleared cached task entry send addr | reason=%s",
        tostring(reason or "")
    ))
end

function M.try_cached_task_entry_send_button_click(ctx, nav_mod, current_time, step, reason)
    if type(nav_mod) ~= "table" or type(nav_mod.control_click) ~= "function" then
        return false, "nav.control_click is unavailable."
    end

    local cached_target, cached_err = M.resolve_cached_task_entry_send_button_target(nav_mod, current_time)
    if type(cached_target) ~= "table" then
        return false, cached_err
    end

    local click_ok, click_err = nav_mod.control_click(cached_target.addr)
    if not click_ok then
        log_throttled(ctx, "task_entry_send_cached_click_preserved", "info", LOG_THROTTLE_MS,
            "[Leveling] preserve cached task entry send addr | reason=" .. tostring(click_err or "cached task entry send addr click failed"))
        return false, click_err
    end

    logger(ctx).info(string.format(
        "[Leveling] task entry send button clicked | source=cached_addr addr=%s pos=(%s,%s) anchor=%s cache_source=%s reason=%s",
        tostring(cached_target.addr or ""),
        tostring(cached_target.x or ""),
        tostring(cached_target.y or ""),
        tostring(type(step) == "table" and step.distance_anchor_exact_text or ""),
        tostring(cached_target.source or ""),
        tostring(reason or "")
    ))
    return true, cached_target
end

function M.try_capture_task_entry_send_button_via_hover(ctx, nav_mod, current_time, step, reason)
    if M.button_call_hover_capture_disabled() then
        return nil, "task entry send hover capture globally disabled."
    end

    if type(step) ~= "table" then
        return nil, "task entry send step unavailable."
    end

    local retry_gate = tonumber(state.next_task_entry_send_hover_capture_at) or 0
    if retry_gate > current_time then
        return nil, string.format(
            "task entry send hover capture cooldown until=%d now=%d",
            retry_gate,
            current_time
        )
    end
    if type(nav_mod) ~= "table" or type(nav_mod.move_mouse_to_client) ~= "function" then
        return nil, "nav.move_mouse_to_client is unavailable."
    end

    local capture_bounds, bounds_summary = M.resolve_main_task_hover_capture_bounds(step)
    if type(capture_bounds) ~= "table" then
        state.next_task_entry_send_hover_capture_at = current_time
            + math.max(300, tonumber(step.hover_capture_retry_ms) or 900)
        return nil, bounds_summary
    end

    local original_cursor = nil
    if type(nav_mod.cursor_client_pos) == "function" then
        original_cursor = select(1, nav_mod.cursor_client_pos({
            allow_outside = true
        }))
    end

    local capture_candidate, capture_summary = M.choose_main_task_hover_candidate(
        "capture",
        original_cursor,
        capture_bounds,
        step,
        "task_entry_send"
    )
    if type(capture_candidate) ~= "table" then
        state.next_task_entry_send_hover_capture_at = current_time
            + math.max(300, tonumber(step.hover_capture_retry_ms) or 900)
        return nil, capture_summary
    end

    local moved, move_result = nav_mod.move_mouse_to_client(capture_candidate.x, capture_candidate.y, {
        mouse_mode = "api",
        min_duration_ms = capture_candidate.move_min_ms,
        max_duration_ms = capture_candidate.move_max_ms,
        hover_ms = capture_candidate.hover_ms,
        set_foreground = true
    })
    if moved then
        local capture_entry = {
            x = capture_candidate.x,
            y = capture_candidate.y,
            zone = capture_candidate.zone,
            angle_deg = capture_candidate.angle_deg,
            move_min_ms = capture_candidate.move_min_ms,
            move_max_ms = capture_candidate.move_max_ms,
            hover_ms = capture_candidate.hover_ms,
            move_duration_ms = tonumber(type(move_result) == "table" and move_result.duration_ms),
            move_style = tostring(type(move_result) == "table" and move_result.move_style or ""),
            sample_attempt = capture_candidate.sample_attempt,
            score = capture_candidate.score,
            outcome = "hover_probe"
        }
        M.push_main_task_hover_history("capture", capture_entry, capture_candidate.history_limit, "task_entry_send")
        state.last_task_entry_send_hover_capture_meta = capture_entry

        local selected_target, selected_err = M.resolve_task_entry_send_selected_target(nav_mod, step)
        if type(selected_target) == "table" then
            local cached = M.cache_task_entry_send_button_target(
                ctx,
                selected_target,
                current_time,
                "hover_capture:randomized",
                step
            )
            if type(cached) == "table" then
                state.next_task_entry_send_hover_capture_at = 0
                local return_note = "return=skipped"
                local return_bounds, return_bounds_err = M.resolve_main_task_hover_return_bounds(nav_mod, step)
                if type(return_bounds) == "table" then
                    local return_origin = {
                        client_x = capture_candidate.x,
                        client_y = capture_candidate.y
                    }
                    local return_candidate, return_summary = M.choose_main_task_hover_candidate(
                        "return",
                        return_origin,
                        return_bounds,
                        step,
                        "task_entry_send"
                    )
                    if type(return_candidate) == "table" then
                        local returned, return_result = nav_mod.move_mouse_to_client(return_candidate.x, return_candidate.y, {
                            mouse_mode = "api",
                            min_duration_ms = return_candidate.move_min_ms,
                            max_duration_ms = return_candidate.move_max_ms,
                            hover_ms = return_candidate.hover_ms
                        })
                        if returned then
                            local return_entry = {
                                x = return_candidate.x,
                                y = return_candidate.y,
                                zone = return_candidate.zone,
                                angle_deg = return_candidate.angle_deg,
                                move_min_ms = return_candidate.move_min_ms,
                                move_max_ms = return_candidate.move_max_ms,
                                hover_ms = return_candidate.hover_ms,
                                move_duration_ms = tonumber(type(return_result) == "table" and return_result.duration_ms),
                                move_style = tostring(type(return_result) == "table" and return_result.move_style or ""),
                                sample_attempt = return_candidate.sample_attempt,
                                score = return_candidate.score,
                                outcome = "safe_return"
                            }
                            M.push_main_task_hover_history("return", return_entry, return_candidate.history_limit, "task_entry_send")
                            state.last_task_entry_send_hover_return_meta = return_entry
                            return_note = string.format(
                                "return=%s move_style=%s move_duration=%s summary=%s",
                                M.format_main_task_hover_candidate_brief(return_candidate),
                                tostring(return_entry.move_style or ""),
                                tostring(return_entry.move_duration_ms or ""),
                                tostring(return_summary or "")
                            )
                        else
                            return_note = string.format(
                                "return_move_failed=%s candidate=%s summary=%s",
                                tostring(return_result or ""),
                                M.format_main_task_hover_candidate_brief(return_candidate),
                                tostring(return_summary or "")
                            )
                        end
                    else
                        return_note = "return_candidate_failed=" .. tostring(return_summary or "")
                    end
                else
                    return_note = "return_bounds_failed=" .. tostring(return_bounds_err or "")
                end

                logger(ctx).info(string.format(
                    "[Leveling] cached task entry send addr via hover | hover=%s move_style=%s move_duration=%s target=%s bounds=%s capture_summary=%s %s reason=%s",
                    M.format_main_task_hover_candidate_brief(capture_candidate),
                    tostring(type(move_result) == "table" and move_result.move_style or ""),
                    tostring(type(move_result) == "table" and move_result.duration_ms or ""),
                    M.format_main_task_click_target_brief(selected_target),
                    tostring(bounds_summary or ""),
                    tostring(capture_summary or ""),
                    tostring(return_note or ""),
                    tostring(reason or "")
                ))
                return selected_target
            end
            selected_err = "cache_failed"
        end

        if step.hover_capture_restore_cursor_on_failure ~= false and type(original_cursor) == "table" then
            local restore_timing = M.randomize_main_task_hover_timing("return", step)
            nav_mod.move_mouse_to_client(original_cursor.client_x, original_cursor.client_y, {
                mouse_mode = "api",
                min_duration_ms = restore_timing.move_min_ms,
                max_duration_ms = restore_timing.move_max_ms,
                hover_ms = math.min(24, math.max(0, math.floor((tonumber(restore_timing.hover_ms) or 0) * 0.35)))
            })
        end

        state.next_task_entry_send_hover_capture_at = current_time
            + math.max(300, tonumber(step.hover_capture_retry_ms) or 900)
        return nil, string.format(
            "task_entry_send_hover_selected_failed=%s hover=%s move_style=%s move_duration=%s bounds=%s capture_summary=%s",
            tostring(selected_err or ""),
            M.format_main_task_hover_candidate_brief(capture_candidate),
            tostring(type(move_result) == "table" and move_result.move_style or ""),
            tostring(type(move_result) == "table" and move_result.duration_ms or ""),
            tostring(bounds_summary or ""),
            tostring(capture_summary or "")
        )
    end

    if step.hover_capture_restore_cursor_on_failure ~= false and type(original_cursor) == "table" then
        local restore_timing = M.randomize_main_task_hover_timing("return", step)
        nav_mod.move_mouse_to_client(original_cursor.client_x, original_cursor.client_y, {
            mouse_mode = "api",
            min_duration_ms = restore_timing.move_min_ms,
            max_duration_ms = restore_timing.move_max_ms,
            hover_ms = math.min(24, math.max(0, math.floor((tonumber(restore_timing.hover_ms) or 0) * 0.35)))
        })
    end

    state.next_task_entry_send_hover_capture_at = current_time
        + math.max(300, tonumber(step.hover_capture_retry_ms) or 900)
    return nil, string.format(
        "task_entry_send_hover_move_failed=%s hover=%s bounds=%s capture_summary=%s",
        tostring(move_result or ""),
        M.format_main_task_hover_candidate_brief(capture_candidate),
        tostring(bounds_summary or ""),
        tostring(capture_summary or "")
    )
end

function M.normalize_treasure_task_query_key(value)
    local text = trim(value)
    if text == "" then
        return nil
    end
    text = text:gsub("^支线%s*", "")
    text = text:gsub("^主线%s*", "")
    text = text:gsub("^藏宝地：%s*", "")
    text = text:gsub("^藏宝地%s*", "")
    text = trim(text)
    if text == "" then
        return "藏宝地"
    end
    return M.normalize_task_title_key(text) or text:lower()
end

function M.treasure_query_matches_text(query, text)
    local text_line = trim(text)
    if text_line == "" then
        return false
    end

    local query_line = trim(query)
    local query_key = M.normalize_treasure_task_query_key(query_line)
    local text_key = M.normalize_treasure_task_query_key(text_line)
    local is_treasure_line = text_line:find("藏宝地", 1, true) ~= nil

    if query_key == nil then
        return is_treasure_line
    end

    if query_key == "藏宝地" then
        return is_treasure_line or text_key == "藏宝地"
    end

    if text_key ~= nil and (
        text_key == query_key
        or text_key:find(query_key, 1, true) ~= nil
        or query_key:find(text_key, 1, true) ~= nil
    ) then
        return true
    end

    return query_line ~= "" and text_line:find(query_line, 1, true) ~= nil
end

function M.treasure_task_target_matches_query(query, target_like)
    if type(target_like) ~= "table" then
        return false
    end

    local candidates = {
        target_like.query,
        target_like.related_text,
        target_like.text,
        target_like.title,
        target_like.raw_text,
        target_like.detail
    }

    for _, candidate in ipairs(candidates) do
        if M.treasure_query_matches_text(query, candidate) then
            return true
        end
    end

    return false
end

function M.extract_treasure_task_button_target(target_like, query)
    local target = M.extract_main_task_button_target(target_like)
    if type(target) ~= "table" then
        return nil
    end

    local buttons = type(M._leveling_buttons) == "table" and M._leveling_buttons or nil
    if type(buttons) == "table" and type(buttons.target_matches_slot) == "function" then
        local ok = select(1, buttons.target_matches_slot("treasure_task", target))
        if not ok then
            return nil
        end
    end

    if not M.treasure_task_target_matches_query(query, target_like)
        and not M.treasure_task_target_matches_query(query, target)
    then
        return nil
    end

    return target
end

function M.clear_cached_treasure_task_button_target()
    state.cached_treasure_task_button_target = nil
    state.cached_treasure_task_button_target_at = 0
    _G.AVEPOINT_CACHED_TREASURE_TASK_BUTTON_TARGET = nil
    M.clear_button_session_entry("treasure_task")
end

function M.cache_treasure_task_button_target(ctx, target_like, current_time, query, source)
    local target = M.extract_treasure_task_button_target(target_like, query)
    if type(target) ~= "table" then
        logger(ctx).warn(string.format(
            "[Leveling] treasure task cache extract failed | query=%s source=%s raw_addr=%s raw_pos=(%s,%s) raw_text=%s raw_related=%s raw_fullname=%s",
            tostring(query or ""),
            tostring(source or ""),
            tostring(type(target_like) == "table" and target_like.addr or ""),
            tostring(type(target_like) == "table" and target_like.x or ""),
            tostring(type(target_like) == "table" and target_like.y or ""),
            tostring(type(target_like) == "table" and target_like.text or ""),
            tostring(type(target_like) == "table" and target_like.related_text or ""),
            tostring(type(target_like) == "table" and target_like.fullname or "")
        ))
        return nil
    end

    local buttons = type(M._leveling_buttons) == "table" and M._leveling_buttons or nil
    if type(buttons) == "table" and type(buttons.target_matches_slot) == "function" then
        local ok, reject = buttons.target_matches_slot("treasure_task", target)
        if not ok then
            logger(ctx).warn(string.format(
                "[Leveling] treasure task cache rejected by button registry | reject=%s target=%s query=%s",
                tostring(reject or ""),
                M.format_main_task_click_target_brief(target),
                tostring(query or "")
            ))
            return nil
        end
    end

    local cached = {
        kind = "button",
        slot = "treasure_task",
        addr = tonumber(target.addr),
        name = tostring(target.name or ""),
        fullname = tostring(target.fullname or ""),
        x = tonumber(target.x),
        y = tonumber(target.y),
        text = tostring(target.text or ""),
        related_text = tostring(target.related_text or ""),
        related_distance = tonumber(target.related_distance),
        captured_at = tonumber(current_time) or 0,
        source = tostring(source or ""),
        query = trim(query),
        query_key = M.normalize_treasure_task_query_key(query)
    }

    local nav_mod = nav_api(ctx)
    local wnd_api = type(ctx) == "table" and ctx.wnd or wnd
    if type(nav_mod) == "table"
        and type(nav_mod.window_hwnd) == "function"
        and type(wnd_api) == "table"
        and type(wnd_api.client_rect) == "function"
    then
        local hwnd = select(1, nav_mod.window_hwnd())
        if hwnd then
            local _, _, client_w, client_h = wnd_api.client_rect(hwnd)
            if type(client_w) == "number" and client_w > 0 and cached.x ~= nil then
                cached.hint_ratio_x = cached.x / client_w
            end
            if type(client_h) == "number" and client_h > 0 and cached.y ~= nil then
                cached.hint_ratio_y = cached.y / client_h
            end
        end
    end

    local current_pid = tonumber(type(nav_mod) == "table" and nav_mod.pid or 0)
    if current_pid ~= nil and current_pid > 0 then
        cached.pid = current_pid
    end
    cached.session_key = M.build_button_session_key(nav_mod)
    if M.button_call_cache_disabled() then
        return cached
    end

    local previous_cached = type(state.cached_treasure_task_button_target) == "table"
        and state.cached_treasure_task_button_target
        or type(_G.AVEPOINT_CACHED_TREASURE_TASK_BUTTON_TARGET) == "table"
            and _G.AVEPOINT_CACHED_TREASURE_TASK_BUTTON_TARGET
        or nil
    M.log_button_slot_addr_change(ctx, "treasure_task", previous_cached, cached, source)
    state.cached_treasure_task_button_target = cached
    state.cached_treasure_task_button_target_at = cached.captured_at
    _G.AVEPOINT_CACHED_TREASURE_TASK_BUTTON_TARGET = M.copy_main_task_button_cache_fields(cached)
    if type(_G.AVEPOINT_CACHED_TREASURE_TASK_BUTTON_TARGET) == "table" then
        _G.AVEPOINT_CACHED_TREASURE_TASK_BUTTON_TARGET.query = cached.query
        _G.AVEPOINT_CACHED_TREASURE_TASK_BUTTON_TARGET.query_key = cached.query_key
    end
    M.persist_button_session_entry("treasure_task", cached)
    return cached
end

function M.resolve_cached_treasure_task_button_target(nav_mod, current_time, query)
    local cached = state.cached_treasure_task_button_target
    if type(cached) ~= "table" and type(_G.AVEPOINT_CACHED_TREASURE_TASK_BUTTON_TARGET) == "table" then
        cached = _G.AVEPOINT_CACHED_TREASURE_TASK_BUTTON_TARGET
    end
    if type(cached) ~= "table" then
        cached = M.read_button_session_entry(nav_mod, "treasure_task")
        if type(cached) == "table" then
            state.cached_treasure_task_button_target = cached
            state.cached_treasure_task_button_target_at = tonumber(cached.captured_at) or 0
            _G.AVEPOINT_CACHED_TREASURE_TASK_BUTTON_TARGET = M.copy_main_task_button_cache_fields(cached)
            if type(_G.AVEPOINT_CACHED_TREASURE_TASK_BUTTON_TARGET) == "table" then
                _G.AVEPOINT_CACHED_TREASURE_TASK_BUTTON_TARGET.query = cached.query
                _G.AVEPOINT_CACHED_TREASURE_TASK_BUTTON_TARGET.query_key = cached.query_key
            end
        end
    end
    if type(cached) ~= "table" then
        return nil, "cached treasure task button target unavailable."
    end

    local addr = tonumber(cached.addr)
    local x = tonumber(cached.x)
    local y = tonumber(cached.y)
    if addr == nil or addr == 0 or x == nil or y == nil then
        M.clear_cached_treasure_task_button_target()
        return nil, "cached treasure task button target is invalid."
    end

    local cached_pid = tonumber(cached.pid or 0)
    local current_pid = tonumber(type(nav_mod) == "table" and nav_mod.pid or 0)
    if cached_pid > 0 and current_pid > 0 and cached_pid ~= current_pid then
        M.clear_cached_treasure_task_button_target()
        return nil, string.format(
            "cached treasure task button target pid changed. cached=%d current=%d",
            cached_pid,
            current_pid
        )
    end

    local cached_session_key = trim(cached.session_key or "")
    local current_session_key = M.build_button_session_key(nav_mod)
    if cached_session_key ~= "" and current_session_key ~= "" and cached_session_key ~= current_session_key then
        M.clear_cached_treasure_task_button_target()
        return nil, string.format(
            "cached treasure task button target session changed. cached=%s current=%s",
            cached_session_key,
            current_session_key
        )
    end

    local requested_key = M.normalize_treasure_task_query_key(query)
    local cached_key = M.normalize_treasure_task_query_key(cached.query or cached.related_text or cached.text)
    if requested_key ~= nil
        and cached_key ~= nil
        and requested_key ~= "藏宝地"
        and cached_key ~= "藏宝地"
        and requested_key ~= cached_key
    then
        M.clear_cached_treasure_task_button_target()
        return nil, string.format(
            "cached treasure task button query changed. cached=%s requested=%s",
            tostring(cached_key or ""),
            tostring(requested_key or "")
        )
    end

    local captured_at = tonumber(state.cached_treasure_task_button_target_at) or tonumber(cached.captured_at) or 0
    if captured_at > 0 and tonumber(current_time) ~= nil then
        state.cached_treasure_task_button_target_at = captured_at
    end

    local target = {
        kind = "button",
        addr = addr,
        name = tostring(cached.name or ""),
        text = tostring(cached.text or ""),
        fullname = tostring(cached.fullname or ""),
        x = x,
        y = y,
        related_text = tostring(cached.related_text or ""),
        related_distance = tonumber(cached.related_distance),
        distance = 0,
        source = tostring(cached.source or ""),
        query = tostring(cached.query or ""),
        pid = cached_pid > 0 and cached_pid or nil
    }

    local buttons = type(M._leveling_buttons) == "table" and M._leveling_buttons or nil
    if type(buttons) == "table" and type(buttons.target_matches_slot) == "function" then
        local ok, reject = buttons.target_matches_slot("treasure_task", target)
        if not ok then
            return nil, "cached treasure task button target rejected by registry: " .. tostring(reject or "")
        end
    end

    return target
end

function M.resolve_recent_success_main_task_button_target(ctx, nav_mod, snapshot, fallback_hint_x, fallback_hint_y, current_time)
    local cached = state.last_success_main_task_button
    if type(cached) ~= "table" and type(_G.AVEPOINT_LAST_SUCCESS_MAIN_TASK_BUTTON) == "table" then
        cached = _G.AVEPOINT_LAST_SUCCESS_MAIN_TASK_BUTTON
    end
    if type(cached) ~= "table" then
        return nil, "recent success pose unavailable."
    end
    if type(nav_mod) ~= "table" or type(nav_mod.find_button_by_locator) ~= "function" then
        return nil, "nav.find_button_by_locator is unavailable."
    end

    local captured_at = tonumber(state.last_success_main_task_button_at) or tonumber(cached.captured_at) or 0
    local ttl_ms = math.max(0, tonumber(MAIN_TASK_BUTTON_STEP.success_pose_ttl_ms) or 300000)
    if captured_at <= 0 or (tonumber(current_time) or 0) - captured_at > ttl_ms then
        return nil, "recent success pose expired."
    end

    local locator = {
        label = "Recent successful main task TaskBtn",
        fullname = cached.fullname ~= "" and cached.fullname or MAIN_TASK_BUTTON_STEP.include_patterns[1],
        include_patterns = MAIN_TASK_BUTTON_STEP.include_patterns,
        hint_client_x = tonumber(cached.x) or tonumber(fallback_hint_x),
        hint_client_y = tonumber(cached.y) or tonumber(fallback_hint_y),
        hint_ratio_x = tonumber(cached.hint_ratio_x or MAIN_TASK_BUTTON_STEP.hint_ratio_x),
        hint_ratio_y = tonumber(cached.hint_ratio_y or MAIN_TASK_BUTTON_STEP.hint_ratio_y),
        hint_max_distance = math.max(0, tonumber(MAIN_TASK_BUTTON_STEP.success_pose_max_distance) or 24),
        distance_button_name = tostring(
            cached.fullname ~= "" and cached.fullname
                or cached.name ~= "" and cached.name
                or MAIN_TASK_BUTTON_STEP.distance_button_name
        )
    }

    if trim(cached.related_text or "") ~= "" and tonumber(cached.related_distance) ~= nil then
        local raw_distance = math.abs(tonumber(cached.related_distance) or 0)
        local tolerance = raw_distance * math.max(0, tonumber(MAIN_TASK_BUTTON_STEP.distance_tolerance_ratio) or 0.03)
        local min_tolerance = math.max(0, tonumber(MAIN_TASK_BUTTON_STEP.distance_tolerance_min) or 0.5)
        local max_tolerance = math.max(min_tolerance, tonumber(MAIN_TASK_BUTTON_STEP.distance_tolerance_max) or 2.5)
        if tolerance < min_tolerance then
            tolerance = min_tolerance
        end
        if tolerance > max_tolerance then
            tolerance = max_tolerance
        end
        locator.distance_anchor_exact_text = tostring(cached.related_text or "")
        locator.distance_min = math.max(0, raw_distance - tolerance)
        locator.distance_max = raw_distance + tolerance
    end

    local target, err = nav_mod.find_button_by_locator(locator, {
        snapshot = snapshot,
        max_distance = tonumber(locator.hint_max_distance) or 24
    })
    if type(target) == "table" then
        target.locator_mode = "recent_success_pose"
        state.last_success_main_task_button = cached
        state.last_success_main_task_button_at = captured_at
        return target
    end

    return nil, err or "recent success pose matched no button."
end

local function should_use_map_runtime_detection()
    return M.ENABLE_MAP_RUNTIME_DETECTION == true
end

function M.is_known_map_name(value)
    local target_name = normalize_map_name(value)
    if target_name == nil then
        return false
    end

    if target_name == normalize_map_name(state.current_map_name) then
        return true
    end

    if type(MAP_TASK_CONFIGS) ~= "table" then
        return false
    end

    for map_name, _ in pairs(MAP_TASK_CONFIGS) do
        if normalize_map_name(map_name) == target_name then
            return true
        end
    end

    return false
end

local function refresh_current_map_info(ctx, current_time)
    if not should_use_map_runtime_detection() then
        state.current_map_name = nil
        state.cached_map_ui = nil
        state.last_map_info_error = nil
        return nil, nil, nil
    end

    current_time = tonumber(current_time) or now_ms(ctx)
    if current_time < (tonumber(state.next_map_info_refresh_at) or 0) then
        return state.current_map_name, state.cached_map_ui, state.last_map_info_error
    end

    state.next_map_info_refresh_at = current_time + MAP_INFO_REFRESH_INTERVAL_MS

    local nav_mod = nav_api(ctx)
    if type(nav_mod) ~= "table" or type(nav_mod.get_map_ui_info) ~= "function" then
        state.last_map_info_error = "nav.get_map_ui_info is unavailable."
        return state.current_map_name, state.cached_map_ui, state.last_map_info_error
    end

    local map_ui, map_err = nav_mod.get_map_ui_info()
    if type(map_ui) ~= "table" then
        state.last_map_info_error = tostring(map_err or "map ui unavailable.")
        return state.current_map_name, state.cached_map_ui, state.last_map_info_error
    end

    state.cached_map_ui = map_ui
    state.last_map_info_error = nil

    local next_map_name = normalize_map_name(
        type(map_ui.current_map) == "table" and map_ui.current_map.text or nil
    )

    if next_map_name ~= nil and next_map_name ~= tostring(state.current_map_name or "") then
        local previous_map_name = normalize_map_name(state.current_map_name)
        state.current_map_name = next_map_name
        if state.revive_reentry_pending == true
            and normalize_map_name(state.revive_reentry_map_name) ~= next_map_name
        then
            state.revive_reentry_pending = false
            state.revive_reentry_map_name = nil
        end
        state.map_transition_triggered = {}
        clear_runtime_objective_caches()
        logger(ctx).info(string.format(
            "[Leveling] current map updated | map=%s previous=%s",
            tostring(next_map_name),
            tostring(previous_map_name or "")
        ))
    elseif next_map_name ~= nil then
        state.current_map_name = next_map_name
    end

    return state.current_map_name, state.cached_map_ui, nil
end

local function current_map_task_config()
    if not should_use_map_runtime_detection() then
        return nil, nil
    end

    if type(M._leveling_policy) == "table"
        and type(M._leveling_policy.current_map_task_config) == "function"
    then
        return M._leveling_policy.current_map_task_config(state.current_map_name, MAP_TASK_CONFIGS)
    end
    local map_name = normalize_map_name(state.current_map_name)
    if map_name == nil then
        return nil
    end
    return MAP_TASK_CONFIGS[map_name], map_name
end

function M.current_task_runtime_config()
    local task_name = normalize_map_name(state.current_task_name)
    local task_detail = normalize_map_name(state.current_task_detail)
    local function cfg_matches_runtime(cfg)
        if type(cfg) ~= "table" then
            return false
        end
        return M.matches_task_constraints(cfg, {
            task_name = task_name,
            task_detail = task_detail
        })
    end

    if type(M._leveling_policy) == "table"
        and type(M._leveling_policy.current_task_config) == "function"
    then
        local cfg, matched_name, matched_source = M._leveling_policy.current_task_config(
            state.current_task_name,
            state.current_task_detail,
            M.TASK_NAME_CONFIGS
        )
        if cfg_matches_runtime(cfg) then
            return cfg, matched_name, matched_source
        end

        if task_detail ~= nil then
            local detail_cfg, detail_name, detail_source = M._leveling_policy.current_task_config(
                nil,
                task_detail,
                M.TASK_NAME_CONFIGS
            )
            if cfg_matches_runtime(detail_cfg) then
                return detail_cfg, detail_name, detail_source
            end
        end

        return nil, task_name or task_detail, matched_source
    end

    if task_name ~= nil and type(M.TASK_NAME_CONFIGS) == "table" then
        local direct = M.TASK_NAME_CONFIGS[task_name]
        if cfg_matches_runtime(direct) then
            return direct, task_name
        end
    end
    if task_detail ~= nil and type(M.TASK_NAME_CONFIGS) == "table" then
        local detail_direct = M.TASK_NAME_CONFIGS[task_detail]
        if cfg_matches_runtime(detail_direct) then
            return detail_direct, task_detail
        end
    end
    return nil, task_name or task_detail
end

function M.matches_task_constraints(cfg, opts)
    if type(cfg) ~= "table" then
        return false
    end

    opts = type(opts) == "table" and opts or {}
    local task_key = normalize_map_name(opts.task_name or M.current_task_log_name() or state.current_task_name)
    local task_detail_key = normalize_map_name(opts.task_detail or M.current_task_log_detail() or state.current_task_detail)

    local function contains_normalized_match(list, value)
        if type(list) ~= "table" or value == nil then
            return false
        end
        for _, item in ipairs(list) do
            local item_key = normalize_map_name(item)
            if item_key ~= nil and item_key == value then
                return true
            end
        end
        return false
    end

    local function contains_normalized_substring(list, value)
        if type(list) ~= "table" or value == nil then
            return false
        end
        for _, item in ipairs(list) do
            local item_key = normalize_map_name(item)
            if item_key ~= nil and value:find(item_key, 1, true) then
                return true
            end
        end
        return false
    end

    local has_task_constraints = type(cfg.task_names) == "table" or type(cfg.task_patterns) == "table"
    local has_detail_constraints = type(cfg.task_detail_names) == "table" or type(cfg.task_detail_patterns) == "table"
    local constraint_mode = tostring(cfg.constraint_mode or cfg.match_mode or "")
    if not has_task_constraints and not has_detail_constraints then
        return true
    end

    if task_key == nil and task_detail_key == nil and cfg.allow_when_task_unknown == true then
        return true
    end

    if contains_normalized_substring(cfg.exclude_task_patterns, task_key)
        or contains_normalized_substring(cfg.exclude_task_detail_patterns, task_detail_key)
    then
        return false
    end

    local task_allowed = contains_normalized_match(cfg.task_names, task_key)
        or contains_normalized_substring(cfg.task_patterns, task_key)
    local task_detail_allowed = contains_normalized_match(cfg.task_detail_names, task_detail_key)
        or contains_normalized_substring(cfg.task_detail_patterns, task_detail_key)

    if has_task_constraints and has_detail_constraints then
        if constraint_mode == "all" then
            return task_allowed and task_detail_allowed
        end
        return task_allowed or task_detail_allowed
    end
    if has_task_constraints then
        return task_allowed
    end
    return task_detail_allowed
end

function M.current_task_entry_action_config(opts)
    opts = type(opts) == "table" and opts or {}
    if type(state.task_entry_action_locked_cfg) == "table"
        and (tonumber(state.task_entry_action_button_click_at) or 0) > 0
    then
        return state.task_entry_action_locked_cfg, state.task_entry_action_locked_task_name
    end

    local task_cfg, task_name, task_cfg_source = M.current_task_runtime_config()
    if type(task_cfg) == "table" and type(task_cfg.entry_action) == "table" then
        if task_cfg.entry_action.defer_until_explicit_arm == true
            and opts.allow_deferred_entry_action ~= true
        then
            return nil, task_name
        end
        return task_cfg.entry_action, task_name
    end
    return nil, task_name
end

function M.current_task_recipe_config()
    local recipes = type(M._leveling_recipes) == "table" and M._leveling_recipes or nil
    if type(recipes) ~= "table" or type(recipes.current_task_recipe) ~= "function" then
        return nil, nil, "recipe_module_unavailable"
    end

    local task_cfg, task_name, task_cfg_source = M.current_task_runtime_config()
    if type(task_cfg) ~= "table" then
        return nil, task_name, "task_cfg_unavailable"
    end

    local recipe, recipe_key, recipe_source = recipes.current_task_recipe(task_cfg, {
        matches_task_constraints = function(recipe_cfg)
            return M.matches_task_constraints(recipe_cfg, {
                task_name = state.current_task_name,
                task_detail = state.current_task_detail
            })
        end
    })
    if type(recipe) ~= "table" then
        return nil, task_name, recipe_source or task_cfg_source
    end
    return recipe, task_name, recipe_source or task_cfg_source, recipe_key
end

function M.button_slot_definition(slot)
    local buttons = type(M._leveling_buttons) == "table" and M._leveling_buttons or nil
    if type(buttons) ~= "table" or type(buttons.slot_definition) ~= "function" then
        return nil, "button registry unavailable"
    end
    return buttons.slot_definition(slot)
end

function M.current_task_dialogue_flow_config()
    local task_cfg, task_name = M.current_task_runtime_config()
    local flow = type(task_cfg) == "table" and type(task_cfg.dialogue_flow) == "table" and task_cfg.dialogue_flow or nil
    if type(flow) ~= "table" or flow.enabled == false then
        return nil, task_name
    end
    if type(flow.steps) ~= "table" or #flow.steps <= 0 then
        return nil, task_name
    end
    return flow, task_name
end

function M.current_task_post_dialogue_flow_config()
    local task_name = normalize_map_name(state.current_task_name)
    local task_detail = normalize_map_name(state.current_task_detail)
    local function valid_post_dialogue_flow(cfg)
        local flow = type(cfg) == "table" and type(cfg.post_dialogue_flow) == "table"
            and cfg.post_dialogue_flow
            or nil
        if type(flow) ~= "table" or flow.enabled == false then
            return nil
        end
        local has_steps = type(flow.steps) == "table" and #flow.steps > 0
        local is_wait_only_refresh_flow = flow.wait_task_info_refresh_after_jump == true
        if not has_steps and not is_wait_only_refresh_flow then
            return nil
        end
        return flow
    end

    if task_detail ~= nil and type(M.TASK_NAME_CONFIGS) == "table" then
        local detail_direct = M.TASK_NAME_CONFIGS[task_detail]
        local detail_flow = valid_post_dialogue_flow(detail_direct)
        if type(detail_flow) == "table" then
            logger(state.log_ctx).info(string.format(
                "[Leveling] post dialogue flow config matched exact detail | task=%s detail=%s matched_source=task_detail_exact",
                tostring(M.current_task_log_name() or state.current_task_name or ""),
                tostring(M.current_task_log_detail() or state.current_task_detail or "")
            ))
            return detail_flow, task_detail
        end

        for cfg_name, cfg in pairs(M.TASK_NAME_CONFIGS) do
            if normalize_map_name(cfg_name) == task_detail then
                detail_flow = valid_post_dialogue_flow(cfg)
                if type(detail_flow) == "table"
                    and M.matches_task_constraints(cfg, {
                        task_name = task_name,
                        task_detail = task_detail
                    })
                then
                    logger(state.log_ctx).info(string.format(
                        "[Leveling] post dialogue flow config fallback to detail | task=%s detail=%s matched_source=task_detail",
                        tostring(M.current_task_log_name() or state.current_task_name or ""),
                        tostring(M.current_task_log_detail() or state.current_task_detail or "")
                    ))
                    return detail_flow, task_detail
                end
            end
        end
    end

    local task_cfg, runtime_task_name = M.current_task_runtime_config()
    local flow = valid_post_dialogue_flow(task_cfg)
    if type(flow) ~= "table" then
        return nil, runtime_task_name
    end

    return flow, runtime_task_name
end

function M.is_task_entry_action_active(current_time)
    local entry_action, task_name = M.current_task_entry_action_config()
    if type(entry_action) ~= "table" or tostring(entry_action.mode or "") ~= "world_map_send" then
        return false, entry_action, task_name
    end

    if type(state.task_target) == "table" then
        return false, entry_action, task_name
    end

    local armed_at = tonumber(state.task_entry_action_button_click_at) or 0
    if armed_at <= 0 then
        return false, entry_action, task_name
    end

    if (tonumber(state.task_entry_action_send_clicked_at) or 0) > 0 then
        return false, entry_action, task_name
    end

    local timeout_ms = math.max(5000, tonumber(entry_action.timeout_ms) or 12000)
    if type(current_time) == "number" and current_time - armed_at > timeout_ms then
        return false, entry_action, task_name
    end

    return true, entry_action, task_name
end

function M.current_task_retry_call_config()
    local task_cfg, task_name = M.current_task_runtime_config()
    if type(task_cfg) == "table" and type(task_cfg.retry_call_task) == "table" then
        local retry_cfg = task_cfg.retry_call_task
        if retry_cfg.enabled ~= false then
            return retry_cfg, task_name
        end
    end
    return nil, task_name
end

function M.should_preserve_current_task_name(current_time, candidate, source)
    local current_task_cfg, current_task_name = M.current_task_runtime_config()
    local current_objective = type(current_task_cfg) == "table" and current_task_cfg.objective or nil
    if type(current_objective) ~= "table" or tostring(current_objective.mode or "") ~= "boss_kite" then
        state.boss_soft_task_change_candidate = nil
        state.boss_soft_task_change_first_at = 0
        state.boss_soft_task_change_seen_count = 0
        state.boss_soft_task_change_confirmed_candidate = nil
        state.boss_soft_task_change_confirmed_at = 0
        return false, nil
    end

    local candidate_name = normalize_map_name(candidate)
    if candidate_name == nil then
        return false, nil
    end

    local candidate_cfg = nil
    if type(M._leveling_policy) == "table"
        and type(M._leveling_policy.current_task_config) == "function"
    then
        candidate_cfg = select(1, M._leveling_policy.current_task_config(candidate_name, M.TASK_NAME_CONFIGS))
    elseif type(M.TASK_NAME_CONFIGS) == "table" then
        candidate_cfg = M.TASK_NAME_CONFIGS[candidate_name]
    end
    if candidate_cfg ~= nil then
        return false, nil
    end

    local candidate_source = tostring(source or "")
    local current_map_name = normalize_map_name(state.current_map_name)
    local sticky_window_active = state.task_combat_force_kite == true
        or (tonumber(state.startup_boss_engage_until) or 0) > (tonumber(current_time) or 0)
        or (tonumber(state.post_revive_boss_engage_until) or 0) > (tonumber(current_time) or 0)
        or tostring(state.stage or "") == "task_reached"
        or tostring(state.stage or "") == "task_combat"
        or tostring(state.stage or "") == "task_combat_kite"
        or tostring(state.stage or "") == "revive"
        or tostring(state.stage or "") == "wait_task"
        or tostring(state.stage or "") == "wait_task_update"
        or tostring(state.stage or "") == "click_task_button"
        or tostring(state.stage or "") == "wait_task_path_after_button"
        or tostring(state.stage or "") == "global_task_portal"
        or tostring(state.stage or "") == "refresh_task_button_after_dialogue"
        or tostring(state.stage or "") == "refresh_task_button_follow"
        or state.require_task_button_refresh == true
        or (tonumber(state.task_update_wait_until) or 0) > (tonumber(current_time) or 0)
    if sticky_window_active ~= true then
        state.boss_soft_task_change_candidate = nil
        state.boss_soft_task_change_first_at = 0
        state.boss_soft_task_change_seen_count = 0
        return false, nil
    end

    local confirmed_task_source = candidate_source == "task_panel_confirmed"
        or candidate_source == "task_panel_guard"
        or candidate_source == "button"
    if confirmed_task_source then
        state.boss_soft_task_change_candidate = nil
        state.boss_soft_task_change_first_at = 0
        state.boss_soft_task_change_seen_count = 0
        state.boss_soft_task_change_confirmed_candidate = nil
        state.boss_soft_task_change_confirmed_at = 0
        return false, nil
    end

    if candidate_source == "nearby_text" then
        local candidate_title_key = M.normalize_task_title_key(candidate_name)
        local current_state_title_key = M.normalize_task_title_key(state.current_task_name)
        local current_log_title_key = M.normalize_task_title_key(M.current_task_log_name())
        local current_cfg_title_key = M.normalize_task_title_key(current_task_name)
        local current_detail_key = M.normalize_task_title_key(M.current_task_log_detail() or state.current_task_detail)
        local locked_task_key = M.normalize_task_title_key(state.task_combat_locked_task_name)
        local locked_detail_key = M.normalize_task_title_key(state.task_combat_locked_task_detail)
        local same_current_context = candidate_title_key ~= nil and (
            candidate_title_key == current_state_title_key
            or candidate_title_key == current_log_title_key
            or candidate_title_key == current_cfg_title_key
            or candidate_title_key == current_detail_key
            or candidate_title_key == locked_task_key
            or candidate_title_key == locked_detail_key
        )
        if same_current_context then
            state.boss_soft_task_change_candidate = nil
            state.boss_soft_task_change_first_at = 0
            state.boss_soft_task_change_seen_count = 0
            return true, string.format(
                "boss_objective_sticky_nearby_same_context current=%s candidate=%s stage=%s",
                tostring(current_task_name or ""),
                tostring(candidate_name or ""),
                tostring(state.stage or "")
            )
        end

        if current_objective.allow_nearby_text_task_change_exit == true then
            local confirm_ms = math.max(300, tonumber(current_objective.nearby_text_task_change_confirm_ms) or 1500)
            local min_count = math.max(1, tonumber(current_objective.nearby_text_task_change_confirm_count) or 2)
            local pending_key = M.normalize_task_title_key(state.boss_soft_task_change_candidate)
            local candidate_matches_pending = pending_key ~= nil
                and candidate_title_key ~= nil
                and pending_key == candidate_title_key
            if not candidate_matches_pending then
                state.boss_soft_task_change_candidate = candidate_name
                state.boss_soft_task_change_first_at = current_time
                state.boss_soft_task_change_seen_count = 1
                state.boss_soft_task_change_confirmed_candidate = nil
                state.boss_soft_task_change_confirmed_at = 0
                return true, string.format(
                    "boss_objective_sticky_nearby_pending current=%s candidate=%s confirm_ms=%d count=1/%d stage=%s",
                    tostring(current_task_name or ""),
                    tostring(candidate_name or ""),
                    confirm_ms,
                    min_count,
                    tostring(state.stage or "")
                )
            end

            state.boss_soft_task_change_seen_count = (tonumber(state.boss_soft_task_change_seen_count) or 1) + 1
            local first_at = tonumber(state.boss_soft_task_change_first_at) or current_time
            local elapsed = math.max(0, current_time - first_at)
            if elapsed >= confirm_ms and (tonumber(state.boss_soft_task_change_seen_count) or 0) >= min_count then
                state.boss_soft_task_change_confirmed_candidate = candidate_name
                state.boss_soft_task_change_confirmed_at = current_time
                return false, nil
            end

            return true, string.format(
                "boss_objective_sticky_nearby_pending current=%s candidate=%s elapsed=%d/%dms count=%d/%d stage=%s",
                tostring(current_task_name or ""),
                tostring(candidate_name or ""),
                elapsed,
                confirm_ms,
                tonumber(state.boss_soft_task_change_seen_count) or 0,
                min_count,
                tostring(state.stage or "")
            )
        end

        return true, string.format(
            "boss_objective_sticky_nearby_unconfirmed current=%s candidate=%s stage=%s",
            tostring(current_task_name or ""),
            tostring(candidate_name or ""),
            tostring(state.stage or "")
        )
    end

    local generic_mainline = candidate_name:match("^主线%s+") ~= nil
    local looks_like_current_map = current_map_name ~= nil and candidate_name == current_map_name
    local looks_like_known_map = M.is_known_map_name(candidate_name)
    if generic_mainline or looks_like_current_map or looks_like_known_map then
        return true, string.format(
            "boss_objective_sticky current=%s candidate=%s stage=%s",
            tostring(current_task_name or ""),
            tostring(candidate_name or ""),
            tostring(state.stage or "")
        )
    end

    return false, nil
end

function M.current_objective_point_config(destination, target)
    if type(M.OBJECTIVE_POINT_CONFIGS) ~= "table" then
        return nil
    end

    local objective_point = nil
    if is_valid_world_point(destination) then
        objective_point = destination
    elseif is_valid_world_point(state.task_pos) then
        objective_point = state.task_pos
    elseif is_valid_world_point(target) then
        objective_point = target
    end

    if not is_valid_world_point(objective_point) then
        return nil
    end

    for _, cfg in ipairs(M.OBJECTIVE_POINT_CONFIGS) do
        local point_x = tonumber(cfg and cfg.x)
        local point_y = tonumber(cfg and cfg.y)
        local point_radius = tonumber(cfg and cfg.radius) or 0
        if point_x ~= nil and point_y ~= nil and point_radius > 0 then
            local point_distance = distance_2d(objective_point.x, objective_point.y, point_x, point_y)
            if point_distance <= point_radius then
                if not M.matches_task_constraints(cfg) then
                    goto continue
                end
                return cfg
            end
        end
        ::continue::
    end

    return nil
end

function M.find_objective_point_config_by_key(key)
    local lookup_key = normalize_map_name(key)
    if lookup_key == nil or type(M.OBJECTIVE_POINT_CONFIGS) ~= "table" then
        return nil
    end

    for _, cfg in ipairs(M.OBJECTIVE_POINT_CONFIGS) do
        local cfg_key = normalize_map_name(type(cfg) == "table" and cfg.key or nil)
        if cfg_key ~= nil and cfg_key == lookup_key then
            return cfg
        end
    end
    return nil
end

function M.extract_revive_reentry_config(cfg)
    if type(cfg) == "table" and type(cfg.revive_reentry) == "table" then
        return cfg.revive_reentry
    end
    return nil
end

function M.lock_boss_combat_context(task_name, objective_cfg, point_objective_cfg)
    state.task_combat_locked_task_name = trim(task_name or M.current_task_log_name())
    state.task_combat_locked_task_detail = trim(M.current_task_log_detail() or state.current_task_detail)
    state.task_combat_locked_objective_key = tostring(
        type(objective_cfg) == "table" and objective_cfg.key
            or type(point_objective_cfg) == "table" and point_objective_cfg.key
            or ""
    )

    local locked_reentry_cfg = M.extract_revive_reentry_config(point_objective_cfg)
        or M.extract_revive_reentry_config(objective_cfg)
    state.task_combat_locked_reentry_cfg = locked_reentry_cfg
    state.task_combat_locked_reentry_source = type(point_objective_cfg) == "table"
            and locked_reentry_cfg == M.extract_revive_reentry_config(point_objective_cfg)
            and "point"
        or (type(objective_cfg) == "table" and locked_reentry_cfg ~= nil and "objective" or nil)
    state.last_boss_context_at = now_ms(nil)
    state.last_boss_locked_task_name = state.task_combat_locked_task_name
    state.last_boss_locked_task_detail = state.task_combat_locked_task_detail
    state.last_boss_locked_objective_key = state.task_combat_locked_objective_key
    state.last_boss_locked_reentry_cfg = locked_reentry_cfg
    state.last_boss_locked_reentry_source = state.task_combat_locked_reentry_source
end

function M.resolve_revive_reentry_config()
    if type(state.task_combat_locked_reentry_cfg) == "table" then
        return state.task_combat_locked_reentry_cfg,
            tostring(state.task_combat_locked_reentry_source or "locked"),
            tostring(state.task_combat_locked_objective_key or "")
    end

    local task_cfg = select(1, M.current_task_runtime_config())
    local objective_cfg = type(task_cfg) == "table" and type(task_cfg.objective) == "table" and task_cfg.objective or nil
    if type(objective_cfg) == "table" and type(objective_cfg.revive_reentry) == "table" then
        return objective_cfg.revive_reentry, "task", tostring(objective_cfg.key or "")
    end

    local locked_point_cfg = M.find_objective_point_config_by_key(state.task_combat_locked_objective_key)
    if type(locked_point_cfg) == "table" and type(locked_point_cfg.revive_reentry) == "table" then
        return locked_point_cfg.revive_reentry, "locked_point", tostring(locked_point_cfg.key or "")
    end

    local sticky_context_at = tonumber(state.last_boss_context_at) or 0
    if sticky_context_at > 0 and now_ms(nil) - sticky_context_at <= 45000 then
        if type(state.last_boss_locked_reentry_cfg) == "table" then
            return state.last_boss_locked_reentry_cfg,
                tostring(state.last_boss_locked_reentry_source or "sticky"),
                tostring(state.last_boss_locked_objective_key or "")
        end

        local sticky_point_cfg = M.find_objective_point_config_by_key(state.last_boss_locked_objective_key)
        if type(sticky_point_cfg) == "table" and type(sticky_point_cfg.revive_reentry) == "table" then
            return sticky_point_cfg.revive_reentry, "sticky_point", tostring(sticky_point_cfg.key or "")
        end
    end

    local map_cfg, map_name = current_map_task_config()
    if type(map_cfg) == "table" and type(map_cfg.revive_reentry) == "table" then
        return map_cfg.revive_reentry, "map", tostring(map_name or "")
    end

    return nil, nil, nil
end

function M.maybe_handle_boss_task_change(ctx, current_time)
    if state.task_combat_force_kite ~= true
        and tostring(state.stage or "") ~= "task_combat_kite"
        and tostring(state.stage or "") ~= "task_combat"
        and tostring(state.stage or "") ~= "post_combat_loot"
    then
        return false
    end

    if current_time < (tonumber(state.next_task_name_probe_at) or 0) then
        return false
    end

    local hint_x = tonumber(MAIN_TASK_BUTTON_STEP and MAIN_TASK_BUTTON_STEP.hint_client_x)
    local hint_y = tonumber(MAIN_TASK_BUTTON_STEP and MAIN_TASK_BUTTON_STEP.hint_client_y)
    if hint_x ~= nil and hint_y ~= nil then
        M.refresh_current_task_name(ctx, current_time, nil, hint_x, hint_y)
    end
    state.next_task_name_probe_at = current_time + 900

    local locked_objective_key = normalize_map_name(state.task_combat_locked_objective_key)
    local locked_task_name = M.normalize_task_title_key(state.task_combat_locked_task_name)
    local locked_task_detail = normalize_map_name(state.task_combat_locked_task_detail)
    local current_task_cfg, current_task_name = M.current_task_runtime_config()
    local current_objective = type(current_task_cfg) == "table" and type(current_task_cfg.objective) == "table" and current_task_cfg.objective or nil
    local current_objective_key = normalize_map_name(type(current_objective) == "table" and current_objective.key or nil)
    local locked_point_cfg = M.find_objective_point_config_by_key(state.task_combat_locked_objective_key)
    local current_log_task_name = M.normalize_task_title_key(M.current_task_log_name())
    local current_log_task_detail = normalize_map_name(M.current_task_log_detail())
    local current_task_source = tostring(state.current_task_name_source or "")
    local current_detail_source = tostring(state.current_task_detail_source or "")
    local detail_changed = locked_task_detail ~= nil
        and current_log_task_detail ~= nil
        and current_log_task_detail ~= locked_task_detail
    local detail_missing_exit_enabled = (
        type(current_objective) == "table"
        and current_objective.exit_kite_on_detail_missing == true
    ) or (
        type(locked_point_cfg) == "table"
        and locked_point_cfg.exit_kite_on_detail_missing == true
    )
    local detail_missing_exit_after_ms = math.max(
        0,
        tonumber(type(current_objective) == "table" and current_objective.exit_kite_on_detail_missing_after_ms)
            or tonumber(type(locked_point_cfg) == "table" and locked_point_cfg.exit_kite_on_detail_missing_after_ms)
            or 0
    )
    local combat_alive_ms = math.max(
        0,
        current_time - (tonumber(state.task_combat_started_at) or current_time)
    )
    local detail_missing_changed = detail_missing_exit_enabled
        and locked_task_detail ~= nil
        and current_log_task_detail == nil
        and combat_alive_ms >= detail_missing_exit_after_ms
        and current_log_task_name ~= nil
        and (
            current_log_task_name == locked_task_name
            or current_log_task_name == locked_task_detail
        )

    local name_changed = current_log_task_name ~= nil
        and current_log_task_name ~= locked_task_name
        and current_objective_key ~= locked_objective_key
    local soft_probe_change = (current_task_source == "nearby_text" and name_changed)
        or (current_detail_source == "nearby_text" and detail_changed)
    if locked_objective_key ~= nil
        and (name_changed or detail_changed or detail_missing_changed)
    then
        if soft_probe_change then
            log_throttled(ctx, "boss_task_change_soft_probe_ignored", "warn", LOG_THROTTLE_MS, string.format(
                "[Leveling] boss task change ignored from soft text probe | old_task=%s old_detail=%s old_objective=%s new_task=%s new_detail=%s new_objective=%s task_source=%s detail_source=%s stage=%s",
                tostring(locked_task_name or ""),
                tostring(locked_task_detail or ""),
                tostring(locked_objective_key or ""),
                tostring(current_log_task_name or current_task_name or ""),
                tostring(current_log_task_detail or ""),
                tostring(current_objective_key or ""),
                tostring(current_task_source or ""),
                tostring(current_detail_source or ""),
                tostring(state.stage or "")
            ))
            return false
        end
        logger(ctx).info(string.format(
            "[Leveling] boss task changed, exit kite | old_task=%s old_detail=%s old_objective=%s new_task=%s new_detail=%s new_objective=%s stage=%s",
            tostring(locked_task_name or ""),
            tostring(locked_task_detail or ""),
            tostring(locked_objective_key or ""),
            tostring(current_log_task_name or current_task_name or ""),
            tostring(current_log_task_detail or ""),
            tostring(current_objective_key or ""),
            tostring(state.stage or "")
        ))
        clear_task_combat_state()
        clear_runtime_objective_caches()
        M.mark_blocking_side_task_completed(
            ctx,
            current_time,
            locked_task_name,
            locked_task_detail,
            "boss_task_changed"
        )
        schedule_task_refresh_after_transition(ctx, current_time, "boss_task_changed", POST_DIALOGUE_SETTLE_MS, {
            force_task_call = true,
            task_pos_reject_extra_ms = 2000,
            previous_task_name = locked_task_name,
            previous_task_detail = locked_task_detail,
            task_info_change_observed = true
        })
        return true
    end

    return false
end

function M.ensure_terminal_task_lock(task_name, objective_cfg)
    if trim(state.terminal_task_locked_name) == "" then
        local lock_name = trim(task_name or M.current_task_log_name())
        if lock_name ~= "" then
            state.terminal_task_locked_name = lock_name
        end
    end

    if trim(state.terminal_task_locked_detail) == "" then
        local lock_detail = trim(M.current_task_log_detail() or state.current_task_detail)
        if lock_detail ~= "" then
            state.terminal_task_locked_detail = lock_detail
        end
    end

    if trim(state.terminal_task_locked_objective_key) == "" then
        local objective_key = trim(type(objective_cfg) == "table" and objective_cfg.key or "")
        if objective_key ~= "" then
            state.terminal_task_locked_objective_key = objective_key
        end
    end
end

function M.is_terminal_task_refresh_stage(stage_name)
    stage_name = tostring(stage_name or state.stage or "")
    return stage_name == "task_reached"
        or stage_name == "task_combat"
        or stage_name == "task_combat_kite"
        or stage_name == "task_combat_settle"
        or stage_name == "task_combat_complete_settle"
        or stage_name == "task_spawn_wait"
        or stage_name == "approach_task_objective"
        or stage_name == "interaction_prompt"
        or stage_name == "npc_dialogue"
end

function M.clear_terminal_task_refresh_marker()
    state.terminal_task_refresh_detected_at = 0
    state.terminal_task_refresh_previous_task_name = nil
    state.terminal_task_refresh_previous_task_detail = nil
    state.terminal_task_refresh_new_task_name = nil
    state.terminal_task_refresh_new_task_detail = nil
    state.terminal_task_refresh_source = nil
end

function M.mark_terminal_task_refresh(ctx, current_time, old_task, old_detail, source)
    if not M.is_terminal_task_refresh_stage() then
        return false
    end

    local previous_task_key = M.normalize_task_title_key(old_task)
        or M.normalize_task_title_key(state.terminal_task_locked_name)
    local previous_detail_key = normalize_map_name(old_detail)
        or normalize_map_name(state.terminal_task_locked_detail)
    local new_task_key = M.normalize_task_title_key(state.current_task_name or M.current_task_log_name())
    local new_detail_key = normalize_map_name(state.current_task_detail or M.current_task_log_detail())
    if new_task_key == nil and new_detail_key == nil then
        return false
    end
    if previous_task_key == new_task_key
        and (
            previous_detail_key == new_detail_key
            or previous_detail_key == nil
            or new_detail_key == nil
        )
    then
        return false
    end

    state.terminal_task_refresh_detected_at = tonumber(current_time) or now_ms(ctx)
    state.terminal_task_refresh_previous_task_name = old_task
    state.terminal_task_refresh_previous_task_detail = old_detail
    state.terminal_task_refresh_new_task_name = state.current_task_name or M.current_task_log_name()
    state.terminal_task_refresh_new_task_detail = state.current_task_detail or M.current_task_log_detail()
    state.terminal_task_refresh_source = tostring(source or "")
    logger(ctx).info(string.format(
        "[Leveling] terminal task refresh detected | old_task=%s old_detail=%s new_task=%s new_detail=%s source=%s stage=%s",
        tostring(old_task or ""),
        tostring(old_detail or ""),
        tostring(state.terminal_task_refresh_new_task_name or ""),
        tostring(state.terminal_task_refresh_new_task_detail or ""),
        tostring(source or ""),
        tostring(state.stage or "")
    ))
    return true
end

function M.consume_terminal_task_refresh_marker(ctx, current_time, stage_name)
    local detected_at = tonumber(state.terminal_task_refresh_detected_at) or 0
    if detected_at <= 0 then
        return false
    end

    local previous_task_name = state.terminal_task_refresh_previous_task_name
    local previous_task_detail = state.terminal_task_refresh_previous_task_detail
    local source = tostring(state.terminal_task_refresh_source or "")
    logger(ctx).info(string.format(
        "[Leveling] task changed, resume next step | old_task=%s old_detail=%s old_objective=%s new_task=%s new_detail=%s new_objective=%s stage=%s source=%s",
        tostring(previous_task_name or state.terminal_task_locked_name or ""),
        tostring(previous_task_detail or state.terminal_task_locked_detail or ""),
        tostring(state.terminal_task_locked_objective_key or ""),
        tostring(M.current_task_log_name() or state.current_task_name or ""),
        tostring(M.current_task_log_detail() or state.current_task_detail or ""),
        "",
        tostring(stage_name or state.stage or ""),
        source
    ))
    clear_task_combat_state()
    clear_runtime_objective_caches()
    M.mark_blocking_side_task_completed(
        ctx,
        current_time,
        previous_task_name,
        previous_task_detail,
        "terminal_task_refresh_marker"
    )
    state.terminal_task_locked_name = nil
    state.terminal_task_locked_detail = nil
    state.terminal_task_locked_objective_key = nil
    M.clear_terminal_task_refresh_marker()
    schedule_task_refresh_after_transition(ctx, current_time, "task_changed", TASK_BUTTON_SETTLE_MS, {
        force_task_call = true,
        task_pos_reject_extra_ms = 2000,
        previous_task_name = previous_task_name,
        previous_task_detail = previous_task_detail,
        task_info_change_observed = true
    })
    return true
end

function M.maybe_handle_terminal_task_change(ctx, current_time)
    local stage_name = tostring(state.stage or "")
    local terminal_stage_active = M.is_terminal_task_refresh_stage(stage_name)
    if not terminal_stage_active then
        return false
    end

    if M.consume_terminal_task_refresh_marker(ctx, current_time, stage_name) then
        return true
    end

    if current_time < (tonumber(state.next_task_name_probe_at) or 0) then
        return false
    end

    local hint_x = tonumber(MAIN_TASK_BUTTON_STEP and MAIN_TASK_BUTTON_STEP.hint_client_x)
    local hint_y = tonumber(MAIN_TASK_BUTTON_STEP and MAIN_TASK_BUTTON_STEP.hint_client_y)
    if hint_x ~= nil and hint_y ~= nil then
        M.refresh_current_task_name(ctx, current_time, nil, hint_x, hint_y)
    end
    state.next_task_name_probe_at = current_time + 900

    if M.consume_terminal_task_refresh_marker(ctx, current_time, stage_name) then
        return true
    end

    local locked_task_name = normalize_map_name(state.terminal_task_locked_name)
    local locked_task_detail = normalize_map_name(state.terminal_task_locked_detail)
    local locked_objective_key = normalize_map_name(state.terminal_task_locked_objective_key)
    local current_task_cfg, current_task_name = M.current_task_runtime_config()
    local current_objective = type(current_task_cfg) == "table" and type(current_task_cfg.objective) == "table"
        and current_task_cfg.objective or nil
    local current_objective_key = normalize_map_name(type(current_objective) == "table" and current_objective.key or nil)
    local current_log_task_name = normalize_map_name(M.current_task_log_name())
    local current_log_task_detail = normalize_map_name(M.current_task_log_detail())
    local function normalize_task_title_drift_key(value)
        local raw = normalize_map_name(value)
        if raw == nil then
            return nil
        end
        raw = raw:gsub("^主线%s*", "")
        return raw ~= "" and raw or nil
    end

    local task_changed = locked_task_name ~= nil
        and current_log_task_name ~= nil
        and current_log_task_name ~= locked_task_name
    local detail_changed = locked_task_detail ~= nil
        and current_log_task_detail ~= nil
        and current_log_task_detail ~= locked_task_detail
    local objective_changed = locked_objective_key ~= nil
        and current_objective_key ~= nil
        and current_objective_key ~= locked_objective_key
    local locked_task_title_key = normalize_task_title_drift_key(locked_task_name)
    local current_task_title_key = normalize_task_title_drift_key(current_log_task_name)
    local task_title_prefix_only_drift = locked_task_title_key ~= nil
        and current_task_title_key ~= nil
        and locked_task_title_key == current_task_title_key
    local prefix_only_title_drift = task_changed
        and not detail_changed
        and not objective_changed
        and task_title_prefix_only_drift

    if prefix_only_title_drift then
        log_throttled(ctx, "terminal_prefix_only_title_drift", "info", LOG_THROTTLE_MS, string.format(
            "[Leveling] terminal task prefix drift ignored | old_task=%s new_task=%s old_detail=%s new_detail=%s stage=%s",
            tostring(state.terminal_task_locked_name or ""),
            tostring(M.current_task_log_name() or current_task_name or ""),
            tostring(state.terminal_task_locked_detail or ""),
            tostring(M.current_task_log_detail() or ""),
            stage_name
        ))
        return false
    end

    if locked_objective_key ~= nil
        and current_objective_key ~= nil
        and current_objective_key == locked_objective_key
        and type(current_objective) == "table"
        and current_objective.ignore_terminal_text_change_when_objective_same == true
        and (task_changed or detail_changed)
    then
        log_throttled(ctx, "terminal_text_change_objective_same", "info", LOG_THROTTLE_MS, string.format(
            "[Leveling] terminal task text drift ignored; objective unchanged | old_task=%s old_detail=%s objective=%s new_task=%s new_detail=%s stage=%s",
            tostring(state.terminal_task_locked_name or ""),
            tostring(state.terminal_task_locked_detail or ""),
            tostring(state.terminal_task_locked_objective_key or ""),
            tostring(M.current_task_log_name() or current_task_name or ""),
            tostring(M.current_task_log_detail() or ""),
            stage_name
        ))
        return false
    end

    local detail_stable_title_drift_stage = stage_name == "task_reached"
        or stage_name == "interaction_prompt"
    local detail_stable_title_drift = detail_stable_title_drift_stage
        and task_changed
        and not detail_changed
        and not objective_changed
        and locked_task_detail ~= nil
        and current_log_task_detail ~= nil
        and current_log_task_detail == locked_task_detail
        and (
            locked_task_name == locked_task_detail
            or current_log_task_name == locked_task_detail
            or task_title_prefix_only_drift
        )
    if detail_stable_title_drift then
        log_throttled(ctx, "terminal_detail_stable_title_drift", "info", LOG_THROTTLE_MS, string.format(
            "[Leveling] terminal task title drift ignored; detail unchanged | old_task=%s old_detail=%s new_task=%s new_detail=%s stage=%s",
            tostring(state.terminal_task_locked_name or ""),
            tostring(state.terminal_task_locked_detail or ""),
            tostring(M.current_task_log_name() or current_task_name or ""),
            tostring(M.current_task_log_detail() or ""),
            stage_name
        ))
        return false
    end

    if not task_changed and not detail_changed and not objective_changed then
        return false
    end

    logger(ctx).info(string.format(
        "[Leveling] task changed, resume next step | old_task=%s old_detail=%s old_objective=%s new_task=%s new_detail=%s new_objective=%s stage=%s",
        tostring(state.terminal_task_locked_name or ""),
        tostring(state.terminal_task_locked_detail or ""),
        tostring(state.terminal_task_locked_objective_key or ""),
        tostring(M.current_task_log_name() or current_task_name or ""),
        tostring(M.current_task_log_detail() or ""),
        tostring(current_objective_key or ""),
        stage_name
    ))
    clear_task_combat_state()
    clear_runtime_objective_caches()
    M.mark_blocking_side_task_completed(
        ctx,
        current_time,
        state.terminal_task_locked_name,
        state.terminal_task_locked_detail,
        "terminal_task_changed"
    )
    state.terminal_task_locked_name = nil
    state.terminal_task_locked_detail = nil
    state.terminal_task_locked_objective_key = nil
    schedule_task_refresh_after_transition(ctx, current_time, "task_changed", TASK_BUTTON_SETTLE_MS, {
        force_task_call = true,
        task_pos_reject_extra_ms = 2000,
        previous_task_name = locked_task_name,
        previous_task_detail = locked_task_detail,
        task_info_change_observed = true
    })
    return true
end

extract_player_hp_values = function(info)
    if type(info) ~= "table" then
        return nil, nil, nil, nil
    end

    local hp, hp_source = nil, nil
    if type(avepoint_extract_player_hp) == "function" then
        hp, hp_source = avepoint_extract_player_hp(info)
    end

    local max_hp, max_hp_source = nil, nil
    if type(avepoint_find_named_number) == "function" then
        max_hp, max_hp_source = avepoint_find_named_number(info, {
            "maxHp", "MaxHp", "maxHP", "MaxHP",
            "hpMax", "HpMax", "HPMax",
            "maximumHp", "MaximumHp", "maximumHP", "MaximumHP",
            "maxHealth", "MaxHealth", "maximumHealth", "MaximumHealth",
            "healthMax", "HealthMax",
            "maxLife", "MaxLife", "maximumLife", "MaximumLife",
            "lifeMax", "LifeMax",
            "maxBlood", "MaxBlood", "maximumBlood", "MaximumBlood",
            "bloodMax", "BloodMax"
        }, 4)
    end

    if max_hp == nil and type(avepoint_find_named_number_fuzzy) == "function" then
        max_hp, max_hp_source = avepoint_find_named_number_fuzzy(info, {
            "upper", "limit", "ceiling"
        }, 4)
    end

    if hp == nil or max_hp == nil or max_hp <= 0 then
        return hp, max_hp, nil, hp_source or max_hp_source
    end

    return hp, max_hp, hp / max_hp, string.format("%s/%s", tostring(hp_source or ""), tostring(max_hp_source or ""))
end

local function read_loading_state(ctx)
    local nav_mod = nav_api(ctx)
    if type(nav_mod) ~= "table" or type(nav_mod.is_loading) ~= "function" then
        return false
    end

    local value, err = nav_mod.is_loading()
    if value == nil then
        log_throttled(ctx, "loading_api_error", "warn", LOG_THROTTLE_MS,
            "[Leveling] is_loading failed: " .. tostring(err))
        return false
    end

    return value == true
end

local function read_main_interface_state(ctx)
    local nav_mod = nav_api(ctx)
    if type(nav_mod) ~= "table" or type(nav_mod.is_main_interface) ~= "function" then
        return nil, "nav.is_main_interface is unavailable."
    end

    local value, err = nav_mod.is_main_interface()
    if value == nil then
        return nil, err or "is_main_interface failed."
    end

    return value == true, nil
end

local function extract_position_from_item(ctx, item)
    if type(item) ~= "table" then
        return nil, nil, nil
    end

    local nav_mod = nav_api(ctx)
    if type(nav_mod) == "table" and type(nav_mod.extract_position) == "function" then
        local x, y, z = nav_mod.extract_position(item)
        if x ~= nil and y ~= nil then
            return x, y, z
        end
    end

    local function pick(tbl, keys)
        if type(tbl) ~= "table" then
            return nil
        end
        for _, key in ipairs(keys) do
            local value = as_number(tbl[key])
            if value ~= nil then
                return value
            end
        end
        return nil
    end

    local x = pick(item, { "x", "X", "posX", "PosX", "worldX", "WorldX" })
    local y = pick(item, { "y", "Y", "posY", "PosY", "worldY", "WorldY" })
    local z = pick(item, { "z", "Z", "posZ", "PosZ", "worldZ", "WorldZ" })
    if x ~= nil and y ~= nil then
        return x, y, z
    end

    for _, key in ipairs({ "pos", "position", "coord", "coords", "point", "location", "Location" }) do
        local nested = item[key]
        if type(nested) == "table" then
            x = pick(nested, { "x", "X", "posX", "PosX", "worldX", "WorldX" })
            y = pick(nested, { "y", "Y", "posY", "PosY", "worldY", "WorldY" })
            z = pick(nested, { "z", "Z", "posZ", "PosZ", "worldZ", "WorldZ" })
            if x ~= nil and y ~= nil then
                return x, y, z
            end
        end
    end

    return nil, nil, nil
end

local function npc_label(item)
    if type(item) ~= "table" then
        return ""
    end

    for _, key in ipairs({
        "name", "Name", "text", "Text", "fullname", "Fullname",
        "displayName", "DisplayName", "title", "Title"
    }) do
        local value = trim(item[key])
        if value ~= "" then
            return value
        end
    end

    return ""
end

function M.monster_special_kind(item, label)
    if type(item) ~= "table" then
        return nil
    end

    local text = trim(label or npc_label(item))
    local force_kite_match = select(1, is_force_kite_monster_name(text))
    if force_kite_match then
        return "forced_kite"
    end
    local lower_text = text:lower()
    if lower_text ~= "" then
        if lower_text:find("boss", 1, true)
            or lower_text:find("leader", 1, true)
            or lower_text:find("elite", 1, true)
            or text:find("棣栭", 1, true)
            or text:find("棰嗕富", 1, true)
            or text:find("绮捐嫳", 1, true)
            or text:find("\u{7A00}\u{6709}", 1, true)
        then
            return "named"
        end
    end

    for _, key in ipairs({
        "isBoss", "IsBoss", "boss", "Boss",
        "isElite", "IsElite", "elite", "Elite",
        "isRare", "IsRare", "rare", "Rare",
        "isNamed", "IsNamed", "named", "Named",
        "rank", "Rank", "rarity", "Rarity",
        "quality", "Quality", "monsterType", "MonsterType"
    }) do
        local value = item[key]
        if value == true or value == 1 then
            return "flag:" .. tostring(key)
        end
        local value_text = trim(value)
        local lower_value = value_text:lower()
        if lower_value ~= "" then
            if lower_value:find("boss", 1, true)
                or lower_value:find("leader", 1, true)
                or lower_value:find("elite", 1, true)
                or lower_value:find("rare", 1, true)
                or lower_value:find("named", 1, true)
                or value_text:find("棣栭", 1, true)
                or value_text:find("棰嗕富", 1, true)
                or value_text:find("绮捐嫳", 1, true)
                or value_text:find("\u{7A00}\u{6709}", 1, true)
            then
                return tostring(key) .. ":" .. value_text
            end
        end
    end

    return nil
end

local function ui_item_text(item)
    if type(item) ~= "table" then
        return ""
    end

    return table.concat({
        tostring(item.name or ""),
        tostring(item.text or ""),
        tostring(item.Fullname or item.fullname or "")
    }, " "):lower()
end

local function confirm_dialogue_ui_visible(ctx, current_time)
    current_time = tonumber(current_time) or now_ms(ctx)
    if state.dialogue_ui_confirmed == true then
        return true, state.dialogue_ui_match
    end
    if current_time < (tonumber(state.next_dialogue_probe_at) or 0) then
        return false, state.dialogue_ui_match
    end

    state.next_dialogue_probe_at = current_time + DIALOGUE_UI_PROBE_INTERVAL_MS

    local nav_mod = nav_api(ctx)
    if type(nav_mod) ~= "table" or type(nav_mod.enum_ui) ~= "function" then
        state.dialogue_ui_match = "nav.enum_ui is unavailable."
        return false, state.dialogue_ui_match
    end

    local ui, ui_err = nav_mod.enum_ui()
    if type(ui) ~= "table" then
        state.dialogue_ui_match = tostring(ui_err or "enum_ui failed.")
        return false, state.dialogue_ui_match
    end

    local dialogue_patterns = DIALOGUE_UI_PATTERNS
    if tostring(state.pending_interaction_origin or "") == "interaction_prompt" then
        dialogue_patterns = {
            "dialog",
            "dialogue",
            "talk",
            "conversation",
            "story",
            "subtitle",
            "skipbutton",
            "skip",
            "cinematic",
            "movie"
        }
    end

    local function scan(items, kind, patterns)
        for _, item in ipairs(items or {}) do
            local text = ui_item_text(item)
            if text ~= "" then
                local excluded = false
                for _, pattern in ipairs(DIALOGUE_UI_EXCLUDE_PATTERNS) do
                    if text:find(pattern, 1, true) then
                        excluded = true
                        break
                    end
                end
                if excluded ~= true then
                    for _, pattern in ipairs(patterns or {}) do
                        if text:find(pattern, 1, true) then
                            return string.format("%s:%s", tostring(kind or "ui"), text)
                        end
                    end
                end
            end
        end
        return nil
    end

    local safe_matched = scan(ui.buttons, "button", DIALOGUE_ESCAPE_SAFE_PATTERNS)
        or scan(ui.texts, "text", DIALOGUE_ESCAPE_SAFE_PATTERNS)
        or scan(ui.images, "image", DIALOGUE_ESCAPE_SAFE_PATTERNS)
    if safe_matched then
        state.dialogue_ui_confirmed = true
        state.dialogue_ui_match = safe_matched
        logger(ctx).info("[Leveling] dialogue UI confirmed | match=" .. tostring(safe_matched))
        return true, safe_matched
    end

    local matched = scan(ui.buttons, "button", dialogue_patterns)
        or scan(ui.texts, "text", dialogue_patterns)
        or scan(ui.images, "image", dialogue_patterns)
    if matched then
        state.dialogue_ui_confirmed = false
        state.dialogue_ui_match = matched
        log_throttled(
            ctx,
            "dialogue_ui_not_escape_safe",
            "info",
            LOG_THROTTLE_MS,
            "[Leveling] dialogue UI seen but ESC is only allowed for skip/cinematic UI | match="
                .. tostring(matched)
        )
        return false, "dialogue UI is not escape-safe: " .. tostring(matched)
    end

    state.dialogue_ui_match = "dialogue UI pattern not found."
    return false, state.dialogue_ui_match
end

local function build_path_signature(path)
    if type(path) ~= "table" or #path == 0 then
        return ""
    end

    local first_point = path[1]
    local last_point = path[#path]
    return string.format(
        "%d|%.1f|%.1f|%.1f|%.1f",
        #path,
        tonumber(first_point and first_point.x) or 0,
        tonumber(first_point and first_point.y) or 0,
        tonumber(last_point and last_point.x) or 0,
        tonumber(last_point and last_point.y) or 0
    )
end

local function is_sharp_turn(prev_point, point, next_point)
    if type(prev_point) ~= "table" or type(point) ~= "table" or type(next_point) ~= "table" then
        return false
    end

    local ax = (tonumber(point.x) or 0) - (tonumber(prev_point.x) or 0)
    local ay = (tonumber(point.y) or 0) - (tonumber(prev_point.y) or 0)
    local bx = (tonumber(next_point.x) or 0) - (tonumber(point.x) or 0)
    local by = (tonumber(next_point.y) or 0) - (tonumber(point.y) or 0)
    local len_a = math.sqrt(ax * ax + ay * ay)
    local len_b = math.sqrt(bx * bx + by * by)
    if len_a < 1 or len_b < 1 then
        return false
    end

    local cos_value = (ax * bx + ay * by) / (len_a * len_b)
    return cos_value <= TASK_PATH_COMPRESS_TURN_COS_THRESHOLD
end

local function compress_task_path(path)
    if type(path) ~= "table" or #path == 0 then
        return nil, 0, "invalid"
    end

    local raw_count = #path
    if raw_count <= 2 then
        return path, raw_count, "raw_short"
    end

    if raw_count <= 6 then
        return path, raw_count, "raw_short"
    end

    local function compress_with_thresholds(min_distance, turn_min_distance, turn_cos_threshold)
        local function is_sharp_turn_with_threshold(prev_point, point, next_point)
            if type(prev_point) ~= "table" or type(point) ~= "table" or type(next_point) ~= "table" then
                return false
            end

            local ax = (tonumber(point.x) or 0) - (tonumber(prev_point.x) or 0)
            local ay = (tonumber(point.y) or 0) - (tonumber(prev_point.y) or 0)
            local bx = (tonumber(next_point.x) or 0) - (tonumber(point.x) or 0)
            local by = (tonumber(next_point.y) or 0) - (tonumber(point.y) or 0)
            local len_a = math.sqrt(ax * ax + ay * ay)
            local len_b = math.sqrt(bx * bx + by * by)
            if len_a < 1 or len_b < 1 then
                return false
            end

            local cos_value = (ax * bx + ay * by) / (len_a * len_b)
            return cos_value <= turn_cos_threshold
        end

        local compressed = { path[1] }
        local last_kept = path[1]

        for index = 2, raw_count - 1 do
            local point = path[index]
            local next_point = path[index + 1]
            local segment_distance = distance_2d(last_kept.x, last_kept.y, point.x, point.y)
            local keep_for_distance = segment_distance >= min_distance
            local keep_for_turn = segment_distance >= turn_min_distance
                and is_sharp_turn_with_threshold(last_kept, point, next_point)

            if keep_for_distance or keep_for_turn then
                compressed[#compressed + 1] = point
                last_kept = point
            end
        end

        local last_point = path[raw_count]
        local last_added = compressed[#compressed]
        if type(last_added) ~= "table"
            or distance_2d(last_added.x, last_added.y, last_point.x, last_point.y) >= 1
        then
            compressed[#compressed + 1] = last_point
        end

        return compressed
    end

    local compressed = compress_with_thresholds(
        TASK_PATH_COMPRESS_MIN_DISTANCE,
        TASK_PATH_COMPRESS_TURN_MIN_DISTANCE,
        TASK_PATH_COMPRESS_TURN_COS_THRESHOLD
    )
    local compress_mode = "default"
    local compressed_count = type(compressed) == "table" and #compressed or 0
    local over_compressed = raw_count >= 12
        and compressed_count <= math.max(4, math.floor(raw_count * 0.24))

    if over_compressed then
        local relaxed = compress_with_thresholds(
            math.max(420, math.floor(TASK_PATH_COMPRESS_MIN_DISTANCE * 0.55)),
            math.max(180, math.floor(TASK_PATH_COMPRESS_TURN_MIN_DISTANCE * 0.65)),
            math.min(0.94, TASK_PATH_COMPRESS_TURN_COS_THRESHOLD + 0.09)
        )
        if type(relaxed) == "table" and #relaxed > compressed_count then
            compressed = relaxed
            compressed_count = #relaxed
            compress_mode = "adaptive_relaxed"
        end

        if raw_count <= 10 and compressed_count <= math.max(3, math.floor(raw_count * 0.2)) then
            return path, raw_count, "raw_fallback"
        end
    end

    return compressed, raw_count, compress_mode
end

local function clone_task_path(path)
    if type(path) ~= "table" or #path == 0 then
        return nil, 0, "invalid"
    end

    local copy = {}
    for index, point in ipairs(path) do
        if is_valid_world_point(point) then
            copy[#copy + 1] = {
                x = tonumber(point.x),
                y = tonumber(point.y),
                z = tonumber(point.z),
                index = tonumber(point.index) or index
            }
        end
    end

    if #copy == 0 then
        return nil, 0, "invalid"
    end

    if M.TASK_PATH_USE_RAW_PATH == true then
        return copy, #copy, "raw_worker"
    end

    return compress_task_path(copy)
end

local function path_direction_name(direction)
    return direction == -1 and "reverse" or "forward"
end

local function find_nearest_path_index(player_x, player_y, path)
    if type(path) ~= "table" or #path == 0 then
        return nil, nil
    end

    local nearest_index = 1
    local nearest_distance = nil
    for index, point in ipairs(path) do
        local dist = distance_2d(player_x or point.x, player_y or point.y, point.x, point.y)
        if nearest_distance == nil or dist < nearest_distance then
            nearest_distance = dist
            nearest_index = index
        end
    end

    return nearest_index, nearest_distance
end

local function choose_path_direction(player_x, player_y, path)
    if type(path) ~= "table" or #path == 0 then
        return 1
    end

    local first_point = path[1]
    local last_point = path[#path]
    local first_distance = distance_2d(player_x, player_y, first_point.x, first_point.y)
    local last_distance = distance_2d(player_x, player_y, last_point.x, last_point.y)
    return first_distance <= last_distance and 1 or -1
end

local function advance_path_index(path, start_index, direction, player_x, player_y)
    if type(path) ~= "table" or #path == 0 then
        return nil
    end

    local selected_index = math.max(1, math.min(#path, tonumber(start_index) or 1))
    local max_advance = math.max(1, math.floor(tonumber(PATH_LOOKAHEAD_POINTS) or 1))
    for _ = 1, max_advance do
        local next_index = selected_index + direction
        if next_index < 1 or next_index > #path then
            break
        end

        selected_index = next_index
        local point = path[selected_index]
        local dist = distance_2d(player_x or point.x, player_y or point.y, point.x, point.y)
        if dist >= PATH_MIN_ADVANCE_DISTANCE then
            break
        end
    end

    return math.max(1, math.min(#path, selected_index))
end

local function step_path_index(path, current_index, direction)
    if type(path) ~= "table" or #path == 0 then
        return nil
    end

    local next_index = math.max(1, math.min(#path, tonumber(current_index) or 1))
    next_index = next_index + (tonumber(direction) or 1)
    if next_index < 1 or next_index > #path then
        return nil
    end
    return next_index
end

local function ensure_task_path_route(player_x, player_y, current_time)
    local path = state.task_path
    if type(path) ~= "table" or #path == 0 then
        state.task_path_route = nil
        return nil
    end

    local path_signature = build_path_signature(path)
    local route = state.task_path_route
    if type(route) ~= "table" or route.signature ~= path_signature then
        local nearest_index, nearest_distance = find_nearest_path_index(player_x, player_y, path)
        if nearest_index == nil then
            state.task_path_route = nil
            return nil
        end

        local direction = choose_path_direction(player_x, player_y, path)
        local selected_index = advance_path_index(path, nearest_index, direction, player_x, player_y)
        route = {
            signature = path_signature,
            direction = direction,
            index = selected_index,
            nearest_index = nearest_index,
            nearest_distance = nearest_distance,
            point_started_at = tonumber(current_time) or 0,
            point_best_distance = math.huge,
            next_repath_at = (tonumber(current_time) or 0) + TASK_PATH_REPATH_INTERVAL_MS
        }
        state.task_path_route = route
        state.last_path_signature = path_signature
        state.path_direction_sign = direction
        state.last_selected_path_index = selected_index
    end

    return route
end

local function maybe_reanchor_task_path_route(route, path, player_x, player_y, current_time)
    if type(route) ~= "table" or type(path) ~= "table" then
        return false
    end

    local nearest_index, nearest_distance = find_nearest_path_index(player_x, player_y, path)
    if nearest_index ~= nil then
        route.nearest_index = nearest_index
        route.nearest_distance = nearest_distance
    end

    local point = path[route.index]
    if type(point) ~= "table" then
        return false
    end

    if current_time < (tonumber(route.next_repath_at) or 0) then
        return false
    end

    route.next_repath_at = current_time + TASK_PATH_REPATH_INTERVAL_MS

    if nearest_index == nil or nearest_distance == nil then
        return false
    end

    local current_distance = distance_2d(player_x, player_y, point.x, point.y)
    local index_delta = math.abs((tonumber(nearest_index) or 0) - (tonumber(route.index) or 0))
    local should_reanchor = index_delta >= TASK_PATH_REANCHOR_INDEX_DELTA
        and current_distance >= TASK_PATH_REANCHOR_DISTANCE
        and nearest_distance + TASK_PATH_REANCHOR_ADVANTAGE_DISTANCE < current_distance

    if not should_reanchor then
        return false
    end

    route.index = advance_path_index(path, nearest_index, route.direction, player_x, player_y)
    route.point_started_at = current_time
    route.point_best_distance = math.huge
    state.next_move_at = 0
    state.last_selected_path_index = route.index
    return true
end

local function build_target_from_task_path_route(route, player_x, player_y)
    local path = state.task_path
    if type(route) ~= "table" or type(path) ~= "table" then
        return nil
    end

    local point = path[route.index]
    if type(point) ~= "table" then
        return nil
    end

    local current_distance = distance_2d(player_x or point.x, player_y or point.y, point.x, point.y)
    return {
        x = point.x,
        y = point.y,
        z = point.z,
        source = "task_path",
        path_index = tonumber(point.index) or tonumber(route.index) or 0,
        route_index = tonumber(route.index) or 0,
        path_points = #path,
        nearest_index = tonumber(route.nearest_index) or tonumber(route.index) or 0,
        nearest_distance = tonumber(route.nearest_distance) or tonumber(current_distance) or 0,
        current_distance = tonumber(current_distance) or 0,
        path_direction = path_direction_name(route.direction),
        move_interval_ms = M.TASK_FOLLOW_MOVE_INTERVAL_MS
    }
end

local function sync_task_path_target(ctx, player_x, player_y, current_time)
    local route = ensure_task_path_route(player_x, player_y, current_time)
    if type(route) ~= "table" then
        return nil, false, nil
    end

    local path = state.task_path
    local reanchored = maybe_reanchor_task_path_route(route, path, player_x, player_y, current_time)
    if reanchored == true then
        logger(ctx).info(string.format(
            "[Leveling] task path reanchored | route_index=%d nearest_index=%d nearest_distance=%.2f",
            tonumber(route.index) or 0,
            tonumber(route.nearest_index) or 0,
            tonumber(route.nearest_distance) or 0
        ))
    end

    local target = build_target_from_task_path_route(route, player_x, player_y)
    if type(target) ~= "table" then
        return nil, false, nil
    end

    local route_debug_signature = tostring(route.signature or "") .. "|"
        .. tostring(route.index or "") .. "|"
        .. tostring(route.nearest_index or "")
    if tostring(state.last_task_path_route_debug_signature or "") ~= route_debug_signature then
        state.last_task_path_route_debug_signature = route_debug_signature
        local first_point = path[1]
        local last_point = path[#path]
        local nearest_point = path[math.max(1, math.min(#path, tonumber(route.nearest_index) or 1))]
        local selected_point = path[math.max(1, math.min(#path, tonumber(route.index) or 1))]
        logger(ctx).info(string.format(
            "[Leveling] task path route selected | signature=%s player=%.2f, %.2f direction=%s route_index=%d nearest_index=%d nearest_distance=%.2f selected=%.2f, %.2f, %.2f nearest=%.2f, %.2f, %.2f first=%.2f, %.2f, %.2f last=%.2f, %.2f, %.2f points=%d",
            tostring(route.signature or ""),
            tonumber(player_x) or 0,
            tonumber(player_y) or 0,
            path_direction_name(route.direction),
            tonumber(route.index) or 0,
            tonumber(route.nearest_index) or 0,
            tonumber(route.nearest_distance) or 0,
            tonumber(selected_point and selected_point.x) or 0,
            tonumber(selected_point and selected_point.y) or 0,
            tonumber(selected_point and selected_point.z) or 0,
            tonumber(nearest_point and nearest_point.x) or 0,
            tonumber(nearest_point and nearest_point.y) or 0,
            tonumber(nearest_point and nearest_point.z) or 0,
            tonumber(first_point and first_point.x) or 0,
            tonumber(first_point and first_point.y) or 0,
            tonumber(first_point and first_point.z) or 0,
            tonumber(last_point and last_point.x) or 0,
            tonumber(last_point and last_point.y) or 0,
            tonumber(last_point and last_point.z) or 0,
            #path
        ))
    end

    local changed = false
    local current_distance = tonumber(target.current_distance) or distance_2d(player_x, player_y, target.x, target.y)
    local best_distance = tonumber(route.point_best_distance) or math.huge
    if current_distance < best_distance then
        route.point_best_distance = current_distance
        if best_distance == math.huge
            or current_distance <= best_distance - TASK_PATH_PROGRESS_RESET_DISTANCE
        then
            route.point_started_at = current_time
        end
    end

    if current_distance <= TASK_PATH_POINT_ARRIVE_TOLERANCE then
        local next_index = step_path_index(path, route.index, route.direction)
        if next_index ~= nil then
            route.index = next_index
            route.point_started_at = current_time
            route.point_best_distance = math.huge
            route.next_repath_at = current_time + TASK_PATH_REPATH_INTERVAL_MS
            state.next_move_at = 0
            state.last_selected_path_index = route.index
            target = build_target_from_task_path_route(route, player_x, player_y)
            changed = true
            current_distance = tonumber(target and target.current_distance) or current_distance
        end
    elseif current_time - (tonumber(route.point_started_at) or current_time) >= TASK_PATH_STUCK_SKIP_MS then
        local next_index = step_path_index(path, route.index, route.direction)
        if next_index ~= nil then
            local old_index = route.index
            route.index = next_index
            route.point_started_at = current_time
            route.point_best_distance = math.huge
            route.next_repath_at = current_time + TASK_PATH_REPATH_INTERVAL_MS
            state.next_move_at = 0
            state.last_selected_path_index = route.index
            target = build_target_from_task_path_route(route, player_x, player_y)
            changed = true
            logger(nil).warn(string.format(
                "[Leveling] task path point looked stuck, skip route_index=%d -> %d",
                tonumber(old_index) or 0,
                tonumber(route.index) or 0
            ))
        end
    end

    return target, changed, current_distance
end

local function build_target_signature(target)
    if type(target) ~= "table" then
        return ""
    end

    return string.format(
        "%s|%d|%.1f|%.1f|%.1f",
        tostring(target.source or ""),
        tonumber(target.path_index) or 0,
        tonumber(target.x) or 0,
        tonumber(target.y) or 0,
        tonumber(target.z) or 0
    )
end

local issue_move

function M.reset_task_path_sidestep_for_signature(signature)
    state.task_path_sidestep_target_signature = tostring(signature or "")
    state.task_path_sidestep_attempt_count = 0
    state.task_path_sidestep_next_at = 0
    state.task_path_sidestep_last_side = 0
end

function M.build_task_path_sidestep_target(player_x, player_y, player_z, target)
    if type(target) ~= "table" then
        return nil, "sidestep target unavailable."
    end

    local target_source = tostring(target.source or "")
    if target_source ~= "task_path" and target_source ~= "treasure_path" then
        return nil, "sidestep only supports path targets."
    end

    local route = state.task_path_route
    local path = state.task_path
    if type(route) ~= "table" or type(path) ~= "table" or #path <= 0 then
        return nil, "task path route unavailable."
    end

    local route_index = math.max(1, math.min(#path, tonumber(route.index) or 1))
    local direction = tonumber(route.direction) or 1
    if direction ~= -1 then
        direction = 1
    end

    local selected_point = path[route_index]
    local forward_index = step_path_index(path, route_index, direction)
    local backward_index = step_path_index(path, route_index, -direction)
    local forward_point = type(forward_index) == "number" and path[forward_index] or nil
    local backward_point = type(backward_index) == "number" and path[backward_index] or nil

    local ax, ay, bx, by = nil, nil, nil, nil
    if type(selected_point) == "table" and type(forward_point) == "table" then
        ax, ay = tonumber(selected_point.x), tonumber(selected_point.y)
        bx, by = tonumber(forward_point.x), tonumber(forward_point.y)
    elseif type(backward_point) == "table" and type(selected_point) == "table" then
        ax, ay = tonumber(backward_point.x), tonumber(backward_point.y)
        bx, by = tonumber(selected_point.x), tonumber(selected_point.y)
    else
        ax, ay = tonumber(player_x), tonumber(player_y)
        bx, by = tonumber(target.x), tonumber(target.y)
    end

    if type(ax) ~= "number" or type(ay) ~= "number" or type(bx) ~= "number" or type(by) ~= "number" then
        return nil, "sidestep anchors unavailable."
    end

    local dir_x = bx - ax
    local dir_y = by - ay
    local dir_len = distance_2d(ax, ay, bx, by)
    if type(dir_len) ~= "number" or dir_len < (tonumber(M.TASK_PATH_SIDESTEP_MIN_SEGMENT_DISTANCE) or 80) then
        dir_x = (tonumber(target.x) or 0) - (tonumber(player_x) or 0)
        dir_y = (tonumber(target.y) or 0) - (tonumber(player_y) or 0)
        dir_len = math.sqrt(dir_x * dir_x + dir_y * dir_y)
    end
    if type(dir_len) ~= "number" or dir_len < 1 then
        return nil, "sidestep direction unavailable."
    end

    dir_x = dir_x / dir_len
    dir_y = dir_y / dir_len

    local side_sign = (tonumber(state.task_path_sidestep_last_side) or 0) >= 0 and -1 or 1
    local lateral_x = -dir_y * side_sign
    local lateral_y = dir_x * side_sign
    local sidestep_x = (tonumber(player_x) or 0)
        + lateral_x * (tonumber(M.TASK_PATH_SIDESTEP_DISTANCE) or 220)
        + dir_x * (tonumber(M.TASK_PATH_SIDESTEP_FORWARD_DISTANCE) or 72)
    local sidestep_y = (tonumber(player_y) or 0)
        + lateral_y * (tonumber(M.TASK_PATH_SIDESTEP_DISTANCE) or 220)
        + dir_y * (tonumber(M.TASK_PATH_SIDESTEP_FORWARD_DISTANCE) or 72)

    return {
        x = sidestep_x,
        y = sidestep_y,
        z = tonumber(target.z) or tonumber(player_z) or 0,
        source = target_source .. "_sidestep",
        path_index = tonumber(target.path_index) or 0,
        move_interval_ms = math.min(MOVE_INTERVAL_MS, 360),
        force_move = true,
        sidestep_side = side_sign,
        sidestep_anchor_ax = ax,
        sidestep_anchor_ay = ay,
        sidestep_anchor_bx = bx,
        sidestep_anchor_by = by
    }, nil
end

function M.maybe_issue_task_path_sidestep(ctx, current_time, player_x, player_y, player_z, target)
    if type(target) ~= "table" then
        return false, "sidestep target unavailable."
    end

    local target_source = tostring(target.source or "")
    if target_source ~= "task_path" and target_source ~= "treasure_path" then
        return false, "sidestep only supports path targets."
    end

    local signature = build_target_signature(target)
    if signature ~= tostring(state.task_path_sidestep_target_signature or "") then
        M.reset_task_path_sidestep_for_signature(signature)
    end

    if current_time < (tonumber(state.task_path_sidestep_next_at) or 0) then
        return false, "sidestep cooldown."
    end
    if (tonumber(state.task_path_sidestep_attempt_count) or 0) >= 1 then
        return false, "sidestep already attempted for target."
    end

    local sidestep_target, build_err = M.build_task_path_sidestep_target(player_x, player_y, player_z, target)
    if type(sidestep_target) ~= "table" then
        return false, build_err or "sidestep target build failed."
    end

    local move_ok, move_err = issue_move(ctx, current_time, sidestep_target)
    if not move_ok then
        return false, move_err or "sidestep move failed."
    end

    state.task_path_sidestep_attempt_count = (tonumber(state.task_path_sidestep_attempt_count) or 0) + 1
    state.task_path_sidestep_last_side = tonumber(sidestep_target.sidestep_side) or 0
    state.task_path_sidestep_next_at = current_time + (tonumber(M.TASK_PATH_SIDESTEP_COOLDOWN_MS) or 2200)
    state.last_progress_at = current_time

    logger(ctx).info(string.format(
        "[Leveling] task path sidestep issued | source=%s target=%.2f, %.2f side=%d anchor_a=%.2f, %.2f anchor_b=%.2f, %.2f cooldown_ms=%d",
        tostring(target_source),
        tonumber(sidestep_target.x) or 0,
        tonumber(sidestep_target.y) or 0,
        tonumber(sidestep_target.sidestep_side) or 0,
        tonumber(sidestep_target.sidestep_anchor_ax) or 0,
        tonumber(sidestep_target.sidestep_anchor_ay) or 0,
        tonumber(sidestep_target.sidestep_anchor_bx) or 0,
        tonumber(sidestep_target.sidestep_anchor_by) or 0,
        tonumber(M.TASK_PATH_SIDESTEP_COOLDOWN_MS) or 2200
    ))
    return true
end

local function assign_task_target(ctx, current_time, target)
    if type(target) ~= "table" then
        return false
    end

    state.task_target = target
    state.task_target_updated_at = current_time

    local signature = build_target_signature(target)
    if signature ~= state.last_task_signature then
        state.last_task_signature = signature
        state.next_move_at = 0
        M.reset_task_path_sidestep_for_signature(signature)
        logger(ctx).info(string.format(
            "[Leveling] task target updated | source=%s path_index=%d nearest_index=%d nearest_distance=%.2f order=%s path_points=%d target=%.2f, %.2f, %.2f",
            tostring(target.source or ""),
            tonumber(target.path_index) or 0,
            tonumber(target.nearest_index) or 0,
            tonumber(target.nearest_distance) or 0,
            tostring(target.path_direction or ""),
            tonumber(target.path_points) or 0,
            tonumber(target.x) or 0,
            tonumber(target.y) or 0,
            tonumber(target.z) or 0
        ))
    end

    if state.global_task_portal_wait_reacquire == true then
        state.global_task_portal_wait_reacquire = false
        local post_reacquire_guard_ms = 6000
        state.global_task_portal_guard_until = math.max(
            tonumber(state.global_task_portal_guard_until) or 0,
            current_time + post_reacquire_guard_ms
        )
        state.global_task_portal_guard_reason = "post_transition_task_reacquired"
        logger(ctx).info(string.format(
            "[Leveling] global task portal resume deferred after task reacquire | source=%s reason=%s guard_ms=%d",
            tostring(target.source or ""),
            tostring(state.global_task_portal_reacquire_reason or ""),
            post_reacquire_guard_ms
        ))
        state.global_task_portal_reacquire_reason = nil
    end

    return true
end

function M.clear_loading_transition_reacquire_state()
    state.loading_transition_reacquire_pending = false
    state.loading_transition_reacquire_reason = nil
    state.loading_transition_reacquire_origin_x = nil
    state.loading_transition_reacquire_origin_y = nil
    state.loading_transition_reacquire_origin_z = nil
    state.loading_transition_reacquire_origin_map_name = nil
    state.loading_transition_reacquire_armed_at = 0
end

function M.arm_loading_transition_reacquire(ctx, current_time, reason)
    if state.loading_transition_reacquire_pending == true then
        return
    end

    state.loading_transition_reacquire_pending = true
    state.loading_transition_reacquire_reason = tostring(reason or "loading_state")
    state.loading_transition_reacquire_origin_x = tonumber(state.last_known_player_x)
    state.loading_transition_reacquire_origin_y = tonumber(state.last_known_player_y)
    state.loading_transition_reacquire_origin_z = tonumber(state.last_known_player_z)
    state.loading_transition_reacquire_origin_map_name = normalize_map_name(state.current_map_name)
    state.loading_transition_reacquire_armed_at = tonumber(current_time) or 0
    logger(ctx).info(string.format(
        "[Leveling] loading transition recovery armed | reason=%s origin=%.2f, %.2f, %.2f map=%s",
        tostring(state.loading_transition_reacquire_reason or ""),
        tonumber(state.loading_transition_reacquire_origin_x) or 0,
        tonumber(state.loading_transition_reacquire_origin_y) or 0,
        tonumber(state.loading_transition_reacquire_origin_z) or 0,
        tostring(state.loading_transition_reacquire_origin_map_name or "")
    ))
end

function M.maybe_handle_loading_transition_reacquire(ctx, current_time, player_x, player_y, player_z)
    if state.loading_transition_reacquire_pending ~= true then
        return false
    end

    local loading_reacquire_cfg = type(M.LOADING_TRANSITION_REACQUIRE_CFG) == "table"
        and M.LOADING_TRANSITION_REACQUIRE_CFG
        or {}

    if state.require_task_button_refresh == true then
        logger(ctx).info(string.format(
            "[Leveling] loading transition recovery released to existing task refresh | reason=%s refresh_reason=%s",
            tostring(state.loading_transition_reacquire_reason or ""),
            tostring(state.require_task_button_refresh_reason or "")
        ))
        M.clear_loading_transition_reacquire_state()
        return false
    end

    local pending_force_reacquire = (tonumber(state.force_task_path_reacquire_until) or 0) > current_time
    local waiting_task_path_after_click = tonumber(state.last_task_button_click_at) ~= nil
        and (tonumber(state.last_task_button_click_at) or 0) > 0
        and current_time < math.max(
            (tonumber(state.last_task_button_click_at) or 0) + TASK_BUTTON_SETTLE_MS,
            tonumber(state.task_path_wait_until) or 0
        )
    if pending_force_reacquire
        or waiting_task_path_after_click
    then
        logger(ctx).info(string.format(
            "[Leveling] loading transition recovery released to main task pipeline | reason=%s force_reacquire=%s waiting_task_path=%s stage=%s",
            tostring(state.loading_transition_reacquire_reason or ""),
            pending_force_reacquire and "true" or "false",
            waiting_task_path_after_click and "true" or "false",
            tostring(state.stage or "")
        ))
        M.clear_loading_transition_reacquire_state()
        return false
    end

    local path = state.task_path
    local nearest_index = nil
    local nearest_distance = nil
    if type(path) == "table" and #path > 0 then
        nearest_index, nearest_distance = find_nearest_path_index(player_x, player_y, path)
    end

    local target = state.task_target
    local target_distance = type(target) == "table"
        and distance_2d(player_x, player_y, target.x, target.y)
        or nil
    local origin_distance = nil
    if type(state.loading_transition_reacquire_origin_x) == "number"
        and type(state.loading_transition_reacquire_origin_y) == "number"
    then
        origin_distance = distance_2d(
            player_x,
            player_y,
            state.loading_transition_reacquire_origin_x,
            state.loading_transition_reacquire_origin_y
        )
    end

    local origin_map_name = normalize_map_name(state.loading_transition_reacquire_origin_map_name)
    local current_map_name = normalize_map_name(state.current_map_name)
    local map_changed = origin_map_name ~= nil
        and current_map_name ~= nil
        and origin_map_name ~= current_map_name
    local path_detached = type(nearest_distance) == "number"
        and nearest_distance >= (tonumber(loading_reacquire_cfg.path_distance) or (TASK_PATH_REANCHOR_DISTANCE * 2))
    local target_detached = type(target_distance) == "number"
        and target_distance >= (tonumber(loading_reacquire_cfg.target_distance) or 2200)
    local origin_shifted = type(origin_distance) == "number"
        and origin_distance >= (tonumber(loading_reacquire_cfg.origin_distance) or 1200)
        and (type(path) == "table" and #path > 0 or type(target) == "table")

    if not (map_changed or path_detached or target_detached or origin_shifted) then
        logger(ctx).info(string.format(
            "[Leveling] loading transition recovery resumed in place | reason=%s origin_distance=%s nearest_path_distance=%s target_distance=%s map_before=%s map_now=%s",
            tostring(state.loading_transition_reacquire_reason or ""),
            type(origin_distance) == "number" and string.format("%.2f", origin_distance) or "nil",
            type(nearest_distance) == "number" and string.format("%.2f", nearest_distance) or "nil",
            type(target_distance) == "number" and string.format("%.2f", target_distance) or "nil",
            tostring(origin_map_name or ""),
            tostring(current_map_name or "")
        ))
        M.clear_loading_transition_reacquire_state()
        return false
    end

    logger(ctx).info(string.format(
        "[Leveling] loading transition recovery forcing main task reacquire | reason=%s origin_distance=%s nearest_path_distance=%s nearest_index=%s target_distance=%s map_before=%s map_now=%s pos=%.2f, %.2f, %.2f",
        tostring(state.loading_transition_reacquire_reason or ""),
        type(origin_distance) == "number" and string.format("%.2f", origin_distance) or "nil",
        type(nearest_distance) == "number" and string.format("%.2f", nearest_distance) or "nil",
        tostring(nearest_index or ""),
        type(target_distance) == "number" and string.format("%.2f", target_distance) or "nil",
        tostring(origin_map_name or ""),
        tostring(current_map_name or ""),
        tonumber(player_x) or 0,
        tonumber(player_y) or 0,
        tonumber(player_z) or 0
    ))
    M.clear_loading_transition_reacquire_state()
    schedule_task_refresh_after_transition(ctx, current_time, "map_transition_loading_recovery", tonumber(loading_reacquire_cfg.settle_ms) or 900, {
        force_task_call = true,
        task_pos_reject_extra_ms = 3500
    })
    return true
end

local function build_task_destination_point(player_x, player_y)
    if is_valid_world_point(state.task_pos) then
        return {
            x = tonumber(state.task_pos.x),
            y = tonumber(state.task_pos.y),
            z = tonumber(state.task_pos.z),
            source = "task_pos"
        }
    end

    local path = state.task_path
    if type(path) ~= "table" or #path == 0 then
        return nil
    end

    local first_point = path[1]
    local last_point = path[#path]
    if type(first_point) ~= "table" or type(last_point) ~= "table" then
        return nil
    end

    local route = state.task_path_route
    local direction = tonumber(route and route.direction)
    local destination = nil
    if direction ~= nil then
        destination = direction < 0 and first_point or last_point
    else
        local first_distance = distance_2d(player_x, player_y, first_point.x, first_point.y)
        local last_distance = distance_2d(player_x, player_y, last_point.x, last_point.y)
        destination = first_distance >= last_distance and first_point or last_point
    end

    if not is_valid_world_point(destination) then
        return nil
    end

    return {
        x = tonumber(destination.x),
        y = tonumber(destination.y),
        z = tonumber(destination.z),
        source = destination == first_point and "path_first_endpoint" or "path_last_endpoint"
    }
end

local function prepare_inputs(ctx, current_time, opts)
    opts = opts or {}
    current_time = tonumber(current_time) or now_ms(ctx)
    if current_time < (tonumber(state.next_input_prepare_at) or 0) then
        return true
    end

    local nav_mod = nav_api(ctx)
    if type(nav_mod) ~= "table" or type(nav_mod.window_hwnd) ~= "function" then
        return false, "nav.window_hwnd is unavailable."
    end

    local hwnd, hwnd_err = nav_mod.window_hwnd()
    if not hwnd then
        return false, hwnd_err or "game window not found."
    end

    local wnd_api = type(ctx) == "table" and ctx.wnd or wnd
    if type(wnd_api) == "table" and type(wnd_api.set_foreground) == "function" then
        safe_call(wnd_api.set_foreground, hwnd)
        sleep_ms(ctx, INPUT_PREPARE_SETTLE_MS)
    end

    local preferred_mode = type(ctx) == "table" and ctx.runtime_mode or "driver"
    preferred_mode = preferred_mode == "api" and "api" or "driver"

    local function set_input_mode(input_api)
        if type(input_api) ~= "table" or type(input_api.set_mode) ~= "function" then
            return
        end

        local fallback_mode = preferred_mode == "api" and "driver" or "api"
        local ok, result = safe_call(input_api.set_mode, preferred_mode)
        if not ok or result == false then
            safe_call(input_api.set_mode, fallback_mode)
        end
    end

    local keybd_api = type(ctx) == "table" and ctx.keybd or keybd
    local mouse_api = type(ctx) == "table" and ctx.mouse or mouse
    local need_mouse = opts.need_mouse ~= false

    set_input_mode(keybd_api)
    if need_mouse then
        set_input_mode(mouse_api)
    end

    if type(keybd_api) == "table" and type(keybd_api.set_window) == "function" then
        safe_call(keybd_api.set_window, hwnd)
    end
    if need_mouse and type(mouse_api) == "table" and type(mouse_api.set_window) == "function" then
        safe_call(mouse_api.set_window, hwnd)
    end

    state.next_input_prepare_at = current_time + INPUT_PREPARE_INTERVAL_MS
    return true
end

local function input_apis(ctx)
    local keybd_api = type(ctx) == "table" and ctx.keybd or keybd
    local mouse_api = type(ctx) == "table" and ctx.mouse or mouse
    return keybd_api, mouse_api
end

local function resolve_input_hwnd(ctx)
    local nav_mod = nav_api(ctx)
    if type(nav_mod) ~= "table" or type(nav_mod.window_hwnd) ~= "function" then
        return nil, "nav.window_hwnd is unavailable."
    end

    local hwnd, hwnd_err = nav_mod.window_hwnd()
    if not hwnd then
        return nil, hwnd_err or "game window not found."
    end

    return hwnd
end

local function try_background_key_click(ctx, vk, label)
    local hwnd, hwnd_err = resolve_input_hwnd(ctx)
    if not hwnd then
        return false, hwnd_err
    end

    local keybd_api = select(1, input_apis(ctx))
    if type(keybd_api) ~= "table" or type(keybd_api.post_click) ~= "function" then
        return false, "keybd.post_click is unavailable."
    end

    local ok, result = safe_call(keybd_api.post_click, hwnd, vk)
    if not ok or result == false then
        return false, string.format("%s keybd.post_click(0x%02X) failed.", tostring(label or "key"), tonumber(vk) or 0)
    end

    return true
end

local function try_background_key_state(ctx, vk, is_down, label)
    local hwnd, hwnd_err = resolve_input_hwnd(ctx)
    if not hwnd then
        return false, hwnd_err
    end

    local keybd_api = select(1, input_apis(ctx))
    if type(keybd_api) ~= "table" or type(keybd_api.post_key) ~= "function" then
        return false, "keybd.post_key is unavailable."
    end

    local ok, result = safe_call(keybd_api.post_key, hwnd, vk, is_down == true)
    if not ok or result == false then
        return false, string.format(
            "%s keybd.post_key(0x%02X, %s) failed.",
            tostring(label or "key"),
            tonumber(vk) or 0,
            tostring(is_down == true)
        )
    end

    return true
end

local function press_keyboard_hotkey(ctx, current_time, vk, label)
    local background_ok = try_background_key_click(ctx, vk, label)
    if background_ok then
        return true
    end

    local prepared, prepare_err = prepare_inputs(ctx, current_time, {
        need_mouse = false
    })
    if not prepared then
        return false, prepare_err
    end

    local keybd_api = select(1, input_apis(ctx))
    if type(keybd_api) ~= "table" or type(keybd_api.click) ~= "function" then
        return false, "keybd.click is unavailable."
    end

    local ok, result = safe_call(keybd_api.click, vk)
    if not ok or result == false then
        return false, string.format("%s keybd.click(0x%02X) failed.", tostring(label or "key"), tonumber(vk) or 0)
    end

    return true
end

M.try_press_potion_hotkey = function(ctx, vk, label)
    local background_ok, background_err = try_background_key_click(ctx, vk, label)
    if background_ok then
        return true, nil, "background"
    end

    local driver_api = type(ctx) == "table" and ctx.driver or driver
    if type(driver_api) == "table" and type(driver_api.keybd_click) == "function" then
        local ok, result = safe_call(driver_api.keybd_click, vk)
        if ok and result ~= false then
            return true, nil, "driver_click"
        end
    end

    local hwnd, hwnd_err = resolve_input_hwnd(ctx)
    if not hwnd then
        return false, background_err or hwnd_err or "game window not found."
    end

    local keybd_api = select(1, input_apis(ctx))
    if type(keybd_api) ~= "table" then
        return false, background_err or "keybd api unavailable."
    end

    local preferred_mode = type(ctx) == "table" and ctx.runtime_mode or "driver"
    preferred_mode = preferred_mode == "api" and "api" or "driver"
    if type(keybd_api.set_mode) == "function" then
        local fallback_mode = preferred_mode == "api" and "driver" or "api"
        local ok, result = safe_call(keybd_api.set_mode, preferred_mode)
        if not ok or result == false then
            safe_call(keybd_api.set_mode, fallback_mode)
        end
    end
    if type(keybd_api.set_window) == "function" then
        safe_call(keybd_api.set_window, hwnd)
    end
    if type(keybd_api.click) == "function" then
        local ok, result = safe_call(keybd_api.click, vk)
        if ok and result ~= false then
            return true, nil, "key_click"
        end
    end

    return false, background_err or string.format("%s nonintrusive key click failed.", tostring(label or "key"))
end

function M.try_press_right_click_nonintrusive(ctx, label)
    local hwnd, hwnd_err = resolve_input_hwnd(ctx)
    if not hwnd then
        return false, hwnd_err, nil
    end

    local nav_mod = nav_api(ctx)
    local mouse_api = select(2, input_apis(ctx))
    if type(mouse_api) == "table"
        and type(mouse_api.post_click) == "function"
        and type(nav_mod) == "table"
        and type(nav_mod.cursor_client_pos) == "function"
    then
        local cursor, cursor_err = nav_mod.cursor_client_pos()
        if type(cursor) == "table"
            and type(cursor.client_x) == "number"
            and type(cursor.client_y) == "number"
        then
            local ok, result = safe_call(
                mouse_api.post_click,
                hwnd,
                math.floor((tonumber(cursor.client_x) or 0) + 0.5),
                math.floor((tonumber(cursor.client_y) or 0) + 0.5),
                "right",
                ACTION_MOUSE_HOLD_MS
            )
            if ok and result ~= false then
                return true, nil, "mouse_post_click"
            end
        elseif cursor_err then
            hwnd_err = cursor_err
        end
    end

    if type(mouse_api) ~= "table" then
        return false, hwnd_err or "mouse api unavailable.", nil
    end

    local preferred_mode = type(ctx) == "table" and ctx.runtime_mode or "driver"
    preferred_mode = preferred_mode == "api" and "api" or "driver"
    if type(mouse_api.set_mode) == "function" then
        local fallback_mode = preferred_mode == "api" and "driver" or "api"
        local ok, result = safe_call(mouse_api.set_mode, preferred_mode)
        if not ok or result == false then
            safe_call(mouse_api.set_mode, fallback_mode)
        end
    end
    if type(mouse_api.set_window) == "function" then
        safe_call(mouse_api.set_window, hwnd)
    end
    if type(mouse_api.click) == "function" then
        local ok, result = safe_call(mouse_api.click, "right", ACTION_MOUSE_HOLD_MS)
        if ok and result ~= false then
            return true, nil, "mouse_click"
        end
    end

    return false, hwnd_err or string.format("%s right click failed.", tostring(label or "mouse")), nil
end

release_async_combat_inputs = function(ctx, current_time, force)
    current_time = tonumber(current_time) or now_ms(ctx)

    local release_key = state.combat_key_down == true
        and (force == true or current_time >= (tonumber(state.combat_key_release_at) or 0))
    local release_mouse = state.combat_mouse_down == true
        and (force == true or current_time >= (tonumber(state.combat_mouse_release_at) or 0))
    if not release_key and not release_mouse then
        return true
    end

    local keybd_api, mouse_api = input_apis(ctx)
    local all_ok = true
    local need_fallback_prepare = release_mouse == true

    if release_key then
        local released = false
        local driver_api = type(ctx) == "table" and ctx.driver or driver
        if type(driver_api) == "table" and type(driver_api.keybd_up) == "function" then
            local ok, result = safe_call(driver_api.keybd_up, VK_W)
            if ok and result ~= false then
                released = true
            end
        end
        local post_ok = false
        if not released then
            post_ok = try_background_key_state(ctx, VK_W, false, "combat release")
        end
        if released or post_ok then
            released = true
        else
            need_fallback_prepare = true
        end
        if not released and need_fallback_prepare then
            local prepared, prepare_err = prepare_inputs(ctx, current_time, {
                need_mouse = release_mouse
            })
            if not prepared then
                log_throttled(ctx, "combat_release_prepare_failed", "warn", LOG_THROTTLE_MS,
                    "[Leveling] release combat inputs prepare failed: " .. tostring(prepare_err))
                return false, prepare_err
            end

            if type(keybd_api) == "table" and type(keybd_api.up) == "function" then
                local ok, result = safe_call(keybd_api.up, VK_W)
                if ok and result ~= false then
                    released = true
                end
            end
        end
        if not released then
            all_ok = false
        end
        state.combat_key_down = false
        state.combat_key_release_at = 0
    end

    if release_mouse then
        local prepared, prepare_err = prepare_inputs(ctx, current_time, {
            need_mouse = true
        })
        if not prepared then
            log_throttled(ctx, "combat_release_prepare_failed", "warn", LOG_THROTTLE_MS,
                "[Leveling] release combat inputs prepare failed: " .. tostring(prepare_err))
            return false, prepare_err
        end

        if type(mouse_api) == "table" and type(mouse_api.up) == "function" then
            local ok, result = safe_call(mouse_api.up, "right")
            if not ok or result == false then
                all_ok = false
            end
        end
        state.combat_mouse_down = false
        state.combat_mouse_release_at = 0
    end

    if not all_ok then
        log_throttled(ctx, "combat_release_failed", "warn", LOG_THROTTLE_MS,
            "[Leveling] release combat inputs failed.")
    end
    return all_ok
end

local function issue_move_direct(ctx, current_time, target)
    if state.task_combat_kite_route_worker_active == true
        and tostring(type(target) == "table" and target.source or "") ~= "task_combat_kite"
    then
        M.pause_task_combat_kite_route_worker(ctx)
    end

    local force_move = type(target) == "table" and target.force_move == true
    if not force_move and current_time < (tonumber(state.next_move_at) or 0) then
        return true
    end

    local move_interval_ms = MOVE_INTERVAL_MS
    if type(target) == "table" and target.source == "task_path" then
        move_interval_ms = math.max(120, tonumber(target.move_interval_ms) or TASK_PATH_REPATH_INTERVAL_MS)
    elseif type(target) == "table" and target.source == "treasure_path" then
        move_interval_ms = math.max(120, tonumber(target.move_interval_ms) or M.TASK_FOLLOW_MOVE_INTERVAL_MS)
    elseif type(target) == "table" and (target.source == "task_pos" or target.source == "task_pos_precise") then
        move_interval_ms = math.max(120, tonumber(target.move_interval_ms) or MOVE_INTERVAL_MS)
    elseif type(target) == "table" and target.source == "task_combat_kite" then
        move_interval_ms = math.max(
            120,
            tonumber(target.move_interval_ms) or math.min(MOVE_INTERVAL_MS, TASK_COMBAT_KITE_SWITCH_MS)
        )
    elseif tostring(type(target) == "table" and target.source or ""):find("^treasure_") == 1 then
        move_interval_ms = math.max(120, tonumber(target.move_interval_ms) or MOVE_INTERVAL_MS)
    elseif type(target) == "table" and target.source == "route_point_board" then
        move_interval_ms = math.max(120, tonumber(target.move_interval_ms) or 250)
    end

    state.next_move_at = current_time + move_interval_ms
    state.last_move_attempt_at = current_time

    local nav_mod = nav_api(ctx)
    if type(nav_mod) ~= "table" or type(nav_mod.move_call) ~= "function" then
        log_throttled(ctx, "move_api_missing", "warn", LOG_THROTTLE_MS,
            "[Leveling] nav.move_call is unavailable.")
        return false
    end

    local move_ok, move_err = nav_mod.move_call(target.x, target.y, {
        move_call_mouse_sync = {
            enabled = false
        }
    })
    if not move_ok then
        state.last_move_failure_at = current_time
        state.move_failure_streak = (tonumber(state.move_failure_streak) or 0) + 1
        log_throttled(ctx, "move_call_failed", "warn", LOG_THROTTLE_MS,
            "[Leveling] MoveTo failed: " .. tostring(move_err))
        return false, move_err
    end

    state.last_move_call_at = current_time
    state.last_move_failure_at = 0
    state.move_failure_streak = 0
    state.move_guard_until = math.max(
        tonumber(state.move_guard_until) or 0,
        current_time + MOVE_COMBAT_GUARD_MS
    )
    log_throttled(ctx, "move_call_issued", "info", 1500, string.format(
        "[Leveling] MoveTo issued | target=%.2f, %.2f source=%s path_index=%d interval_ms=%d via=direct",
        tonumber(target and target.x) or 0,
        tonumber(target and target.y) or 0,
        tostring(target and target.source or ""),
        tonumber(target and target.path_index) or 0,
        tonumber(move_interval_ms) or 0
    ))
    return true
end

function M.publish_nav_worker_task_path_route(ctx, current_time, target, move_interval_ms)
    local target_source = tostring(type(target) == "table" and target.source or "")
    if M.TASK_PATH_WORKER_ROUTE_MODE ~= true
        or type(target) ~= "table"
        or (target_source ~= "task_path" and target_source ~= "treasure_path")
    then
        return false, "path route worker mode is disabled for source=" .. tostring(target_source)
    end

    local path = state.task_path
    if type(path) ~= "table" or #path <= 0 then
        return false, tostring(target_source) .. " path is unavailable."
    end

    local path_count = #path
    local path_signature = build_path_signature(path)
    local route_identity = tostring(target_source) .. "|" .. tostring(path_signature)
    local requested_direction = tostring(target.path_direction or "")
    local direction = (requested_direction == "reverse" or requested_direction == "fixed_reverse") and -1
        or tonumber(type(state.task_path_route) == "table" and state.task_path_route.direction)
        or 1
    if direction ~= -1 then
        direction = 1
    end
    local arrive_distance = math.max(80, tonumber(target.route_arrive_tolerance) or TASK_PATH_POINT_ARRIVE_TOLERANCE)
    local stuck_skip_ms = math.max(3000, tonumber(target.route_stuck_skip_ms) or TASK_PATH_STUCK_SKIP_MS)
    local progress_reset_distance = math.max(
        40,
        tonumber(target.route_progress_reset_distance) or TASK_PATH_PROGRESS_RESET_DISTANCE
    )
    local worker_target_source = target_source == "treasure_path" and "treasure_path_route" or "task_path_route"

    local nearest_index = tonumber(target.nearest_index)
        or tonumber(type(state.task_path_route) == "table" and state.task_path_route.nearest_index)
        or tonumber(target.route_index)
        or tonumber(target.path_index)
        or 1
    nearest_index = math.max(1, math.min(path_count, math.floor(nearest_index + 0.5)))

    local max_points = math.min(path_count, M.TASK_PATH_WORKER_MAX_POINTS)
    local remaining_count = direction == -1 and nearest_index or (path_count - nearest_index + 1)
    local window_start = tonumber(state.nav_worker_path_route_window_start) or 0
    local window_end = tonumber(state.nav_worker_path_route_window_end) or 0
    local window_direction = tonumber(state.nav_worker_path_route_direction) or direction
    local window_path_signature = tostring(state.nav_worker_path_route_path_signature or "")
    local margin = math.max(6, math.floor(max_points * 0.25))
    local full_route_available = remaining_count <= max_points

    local keep_window = window_start >= 1
        and window_end >= window_start
        and nearest_index >= window_start
        and nearest_index <= window_end
        and window_direction == direction
        and window_path_signature == route_identity
    if keep_window then
        if full_route_available then
            keep_window = direction == 1 and window_end >= path_count or window_start <= 1
        elseif direction == 1 then
            keep_window = window_end >= path_count or (window_end - nearest_index) >= margin
        else
            keep_window = window_start <= 1 or (nearest_index - window_start) >= margin
        end
    end

    local worker_status = tostring(nav_worker_get(ctx, "worker_status") or "")
    local worker_route_version = tonumber(nav_worker_get(ctx, "route_version")) or 0
    local route_count = math.max(0, window_end - window_start + 1)
    if keep_window
        and worker_route_version > 0
        and not (
            worker_status == "path_done"
            and (tonumber(target.current_distance) or 0) > arrive_distance
        )
    then
        local window_first = path[window_start]
        local window_last = path[window_end]
        log_throttled(ctx, "nav_worker_path_route_keep", "info", 1500, string.format(
            "[Leveling] nav worker path route keep | source=%s window=%d-%d/%d direction=%s target_route=%d target_path=%d nearest=%d current_distance=%.2f arrive_distance=%.2f target=%.2f, %.2f first=%.2f, %.2f last=%.2f, %.2f worker_status=%s worker_version=%d",
            tostring(target_source),
            window_start,
            window_end,
            path_count,
            direction == -1 and "reverse" or "forward",
            tonumber(target.route_index) or 0,
            tonumber(target.path_index) or 0,
            nearest_index,
            tonumber(target.current_distance) or 0,
            tonumber(arrive_distance) or 0,
            tonumber(target.x) or 0,
            tonumber(target.y) or 0,
            tonumber(window_first and window_first.x) or 0,
            tonumber(window_first and window_first.y) or 0,
            tonumber(window_last and window_last.x) or 0,
            tonumber(window_last and window_last.y) or 0,
            tostring(worker_status or ""),
            tonumber(worker_route_version) or 0
        ))
        nav_worker_set(ctx, "route_count", route_count)
        nav_worker_set(ctx, "route_arrive_distance", arrive_distance)
        nav_worker_set(ctx, "route_direction", direction)
        nav_worker_set(ctx, "route_stuck_skip_ms", stuck_skip_ms)
        nav_worker_set(ctx, "route_progress_reset_distance", progress_reset_distance)
        nav_worker_set(ctx, "target_source", worker_target_source)
        nav_worker_set(ctx, "target_path_index", tonumber(target.path_index) or 0)
        nav_worker_set(ctx, "move_interval_ms", move_interval_ms)
        nav_worker_set(ctx, "mode", "path_route")
        nav_worker_set(ctx, "paused", false)
        nav_worker_set(ctx, "stop", false)
        state.nav_worker_paused = false
        state.next_move_at = current_time + move_interval_ms
        return true
    end

    if not keep_window then
        if direction == -1 then
            window_end = nearest_index
            window_start = full_route_available and 1 or math.max(1, window_end - max_points + 1)
        else
            window_start = nearest_index
            window_end = full_route_available and path_count or math.min(path_count, window_start + max_points - 1)
        end
    end

    route_count = math.max(0, window_end - window_start + 1)
    if route_count <= 0 then
        return false, "task path route window is empty."
    end

    local parts = {
        target_source,
        path_signature,
        tostring(window_start),
        tostring(window_end),
        tostring(direction),
        tostring(math.floor((tonumber(move_interval_ms) or 0) + 0.5)),
        tostring(math.floor(arrive_distance + 0.5)),
        tostring(math.floor(stuck_skip_ms + 0.5)),
        tostring(math.floor(progress_reset_distance + 0.5)),
        full_route_available and "full" or "chunk"
    }
    for source_index = window_start, window_end do
        local point = path[source_index]
        parts[#parts + 1] = string.format(
            "%d:%.1f:%.1f:%.1f",
            tonumber(point and point.index) or source_index,
            tonumber(point and point.x) or 0,
            tonumber(point and point.y) or 0,
            tonumber(point and point.z) or 0
        )
    end
    local signature = table.concat(parts, "|")
    local route_changed = signature ~= tostring(state.nav_worker_path_route_signature or "")
        or worker_route_version <= 0
        or (worker_status == "path_done"
            and (tonumber(target.current_distance) or 0) > arrive_distance)
    if route_changed then
        state.nav_worker_path_route_version = (tonumber(state.nav_worker_path_route_version) or 0) + 1
        state.nav_worker_path_route_signature = signature
        state.nav_worker_path_route_window_start = window_start
        state.nav_worker_path_route_window_end = window_end
        state.nav_worker_path_route_direction = direction
        state.nav_worker_path_route_path_signature = route_identity

        local output_index = 1
        for source_index = window_start, window_end do
            local point = path[source_index]
            nav_worker_set(ctx, "route_point_" .. output_index .. "_x", tonumber(point and point.x) or 0)
            nav_worker_set(ctx, "route_point_" .. output_index .. "_y", tonumber(point and point.y) or 0)
            nav_worker_set(ctx, "route_point_" .. output_index .. "_z", tonumber(point and point.z) or 0)
            nav_worker_set(ctx, "route_point_" .. output_index .. "_index", tonumber(point and point.index) or source_index)
            output_index = output_index + 1
        end
        local window_first = path[window_start]
        local window_last = path[window_end]
        logger(ctx).info(string.format(
            "[Leveling] nav worker path route armed | source=%s range=%d-%d/%d points=%d mode=%s direction=%s interval_ms=%d arrive_distance=%.2f stuck_skip_ms=%d version=%d target_route=%d target_path=%d nearest=%d current_distance=%.2f target=%.2f, %.2f first=%.2f, %.2f last=%.2f, %.2f signature=%s",
            tostring(target_source),
            window_start,
            window_end,
            path_count,
            route_count,
            full_route_available and "full_remaining" or "chunked",
            direction == -1 and "reverse" or "forward",
            tonumber(move_interval_ms) or 0,
            tonumber(arrive_distance) or 0,
            tonumber(stuck_skip_ms) or 0,
            tonumber(state.nav_worker_path_route_version) or 0,
            tonumber(target.route_index) or 0,
            tonumber(target.path_index) or 0,
            nearest_index,
            tonumber(target.current_distance) or 0,
            tonumber(target.x) or 0,
            tonumber(target.y) or 0,
            tonumber(window_first and window_first.x) or 0,
            tonumber(window_first and window_first.y) or 0,
            tonumber(window_last and window_last.x) or 0,
            tonumber(window_last and window_last.y) or 0,
            tostring(path_signature)
        ))
    end

    nav_worker_set(ctx, "route_count", route_count)
    nav_worker_set(ctx, "route_arrive_distance", arrive_distance)
    nav_worker_set(ctx, "route_direction", direction)
    nav_worker_set(ctx, "route_stuck_skip_ms", stuck_skip_ms)
    nav_worker_set(ctx, "route_progress_reset_distance", progress_reset_distance)
    nav_worker_set(ctx, "target_source", worker_target_source)
    nav_worker_set(ctx, "target_path_index", tonumber(target.path_index) or 0)
    nav_worker_set(ctx, "move_interval_ms", move_interval_ms)
    nav_worker_set(ctx, "mode", "path_route")
    nav_worker_set(ctx, "route_version", tonumber(state.nav_worker_path_route_version) or 1)
    nav_worker_set(ctx, "paused", false)
    nav_worker_set(ctx, "stop", false)
    state.nav_worker_paused = false
    state.next_move_at = current_time + move_interval_ms
    return true
end

issue_move = function(ctx, current_time, target)
    if type(target) ~= "table" then
        return false, "move target is unavailable."
    end

    if LEVELING_USE_NAV_WORKER ~= true then
        return issue_move_direct(ctx, current_time, target)
    end

    local worker_ok, worker_err = ensure_nav_worker_running(ctx, current_time)
    if not worker_ok then
        log_throttled(ctx, "nav_worker_fallback", "warn", LOG_THROTTLE_MS,
            "[Leveling] nav worker unavailable, fallback to direct MoveTo: " .. tostring(worker_err))
        return issue_move_direct(ctx, current_time, target)
    end

    local target_source = tostring(type(target) == "table" and target.source or "")
    local move_interval_ms = MOVE_INTERVAL_MS
    if target_source == "task_path" then
        move_interval_ms = math.max(120, tonumber(target.move_interval_ms) or TASK_PATH_REPATH_INTERVAL_MS)
    elseif target_source == "treasure_path" then
        move_interval_ms = math.max(120, tonumber(target.move_interval_ms) or M.TASK_FOLLOW_MOVE_INTERVAL_MS)
    elseif target_source == "task_pos" or target_source == "task_pos_precise" then
        move_interval_ms = math.max(120, tonumber(target.move_interval_ms) or MOVE_INTERVAL_MS)
    elseif target_source == "task_combat_kite" then
        move_interval_ms = math.max(
            120,
            tonumber(target.move_interval_ms) or math.min(MOVE_INTERVAL_MS, TASK_COMBAT_KITE_SWITCH_MS)
        )
    elseif target_source:find("^treasure_") == 1 then
        move_interval_ms = math.max(120, tonumber(target.move_interval_ms) or MOVE_INTERVAL_MS)
    elseif target_source == "route_point_board" then
        move_interval_ms = math.max(120, tonumber(target.move_interval_ms) or 250)
    end

    if target_source == "task_path" or target_source == "treasure_path" then
        local route_ok, route_err = M.publish_nav_worker_task_path_route(ctx, current_time, target, move_interval_ms)
        if route_ok then
            return true
        end
        log_throttled(ctx, "nav_worker_path_route_fallback_" .. target_source, "warn", LOG_THROTTLE_MS,
            "[Leveling] nav worker path route unavailable, fallback to target MoveTo | source="
                .. tostring(target_source)
                .. " err="
                .. tostring(route_err))
    end

    local signature = nav_worker_target_signature(target)
    local target_path_index = tonumber(target.path_index) or 0
    local published_signature = tostring(state.nav_worker_target_signature or "")
    if type(target) == "table"
        and tostring(target.source or "") == "task_path"
        and signature ~= published_signature
    then
        local last_published_at = tonumber(state.nav_worker_target_published_at) or 0
        local last_published_index = tonumber(state.nav_worker_target_path_index) or 0
        local index_delta = math.abs(target_path_index - last_published_index)
        local current_distance = tonumber(target.current_distance) or math.huge
        local should_hold_publish = last_published_at > 0
            and current_time - last_published_at < TASK_PATH_TARGET_STICK_MS
            and index_delta < TASK_PATH_TARGET_FORCE_INDEX_DELTA
            and current_distance > TASK_PATH_POINT_ARRIVE_TOLERANCE
            and (tonumber(state.stall_retry_count) or 0) <= 0
        if should_hold_publish then
            nav_worker_set(ctx, "paused", false)
            nav_worker_set(ctx, "stop", false)
            state.nav_worker_paused = false
            state.next_move_at = current_time + move_interval_ms
            return true
        end
    end

    local target_changed = signature ~= tostring(state.nav_worker_target_signature or "")
    if target_changed then
        state.nav_worker_target_version = (tonumber(state.nav_worker_target_version) or 0) + 1
        state.nav_worker_target_signature = signature
    end

    nav_worker_set(ctx, "target_x", tonumber(target.x) or 0)
    nav_worker_set(ctx, "target_y", tonumber(target.y) or 0)
    nav_worker_set(ctx, "target_source", tostring(target.source or ""))
    nav_worker_set(ctx, "target_path_index", tonumber(target.path_index) or 0)
    nav_worker_set(ctx, "move_interval_ms", move_interval_ms)
    nav_worker_set(ctx, "mode", "target")
    nav_worker_set(ctx, "target_version", tonumber(state.nav_worker_target_version) or 0)
    nav_worker_set(ctx, "paused", false)
    nav_worker_set(ctx, "stop", false)
    state.nav_worker_paused = false
    if target_changed or (tonumber(state.nav_worker_target_published_at) or 0) <= 0 then
        state.nav_worker_target_published_at = current_time
        state.nav_worker_target_path_index = target_path_index
    end
    if target_changed then
        log_throttled(ctx, "nav_worker_target_published", "info", 1200, string.format(
            "[Leveling] nav worker target published | target=%.2f, %.2f source=%s path_index=%d interval_ms=%d",
            tonumber(target.x) or 0,
            tonumber(target.y) or 0,
            tostring(target.source or ""),
            target_path_index,
            tonumber(move_interval_ms) or 0
        ))
    end
    state.next_move_at = current_time + move_interval_ms
    return true
end

local function should_issue_combat_pulse(current_time, target_distance, is_stalled)
    if current_time < (tonumber(state.pause_combat_until) or 0) then
        return false, "combat pause."
    end
    if current_time < (tonumber(state.move_guard_until) or 0) then
        return false, "move guard."
    end
    if current_time < (tonumber(state.next_action_at) or 0) then
        return false, "combat cooldown."
    end

    if is_stalled == true then
        return true, "stalled"
    end

    return false, "navigation priority."
end

local function should_issue_nearby_monster_pulse(current_time)
    if current_time < (tonumber(state.pause_combat_until) or 0) then
        return false, "combat pause."
    end
    if current_time < (tonumber(state.next_action_at) or 0) then
        return false, "combat cooldown."
    end

    return true, "nearby_monster"
end

function M.should_suppress_follow_nearby_monster_pulse(task_cfg, objective_cfg, target, goal_distance, objective_ready_distance)
    if type(target) ~= "table" or tostring(target.source or "") ~= "task_path" then
        return false, nil
    end
    if type(goal_distance) ~= "number" then
        return false, nil
    end

    local objective_mode = type(objective_cfg) == "table" and tostring(objective_cfg.mode or "") or ""
    if objective_mode ~= "boss_kite" then
        return false, nil
    end

    local threshold = tonumber(type(task_cfg) == "table" and task_cfg.approach_suppress_nearby_monster_pulse_goal_distance)
        or tonumber(type(objective_cfg) == "table" and objective_cfg.approach_suppress_nearby_monster_pulse_goal_distance)
    if type(threshold) ~= "number" or threshold <= 0 then
        return false, nil
    end

    local ready_distance = tonumber(objective_ready_distance) or TARGET_REACHED_DISTANCE
    if goal_distance <= ready_distance or goal_distance > threshold then
        return false, nil
    end

    return true
end

local function should_issue_follow_move_pulse(current_time, goal_distance, is_stalled, target)
    if is_stalled == true then
        return false, "stalled priority."
    end
    if type(target) ~= "table" or tostring(target.source or "") ~= "task_path" then
        return false, "target is not task path."
    end
    if type(goal_distance) ~= "number" or goal_distance <= FOLLOW_MOVE_PULSE_MIN_DISTANCE then
        return false, "goal too near."
    end
    if current_time < (tonumber(state.next_follow_move_pulse_at) or 0) then
        return false, "follow move cooldown."
    end

    local allowed, reason = should_issue_combat_pulse(current_time, goal_distance, false)
    if not allowed then
        return false, reason
    end

    return true, "follow_move"
end

local function issue_combat_pulse(ctx, current_time, reason, ignore_move_guard)
    release_async_combat_inputs(ctx, current_time, false)

    if current_time < (tonumber(state.pause_combat_until) or 0) then
        local wait_ms = (tonumber(state.pause_combat_until) or 0) - current_time
        log_throttled(ctx, "combat_pulse_skipped_pause", "info", 1500, string.format(
            "[Leveling] combat pulse skipped | reason=%s gate=pause wait_ms=%d",
            tostring(reason or ""),
            math.max(0, tonumber(wait_ms) or 0)
        ))
        return false, "combat pause."
    end
    if ignore_move_guard ~= true and current_time < (tonumber(state.move_guard_until) or 0) then
        local wait_ms = (tonumber(state.move_guard_until) or 0) - current_time
        log_throttled(ctx, "combat_pulse_skipped_move_guard", "info", 1500, string.format(
            "[Leveling] combat pulse skipped | reason=%s gate=move_guard wait_ms=%d",
            tostring(reason or ""),
            math.max(0, tonumber(wait_ms) or 0)
        ))
        return false, "move guard."
    end
    if current_time < (tonumber(state.next_action_at) or 0) then
        local wait_ms = (tonumber(state.next_action_at) or 0) - current_time
        log_throttled(ctx, "combat_pulse_skipped_cooldown", "info", 1500, string.format(
            "[Leveling] combat pulse skipped | reason=%s gate=cooldown wait_ms=%d",
            tostring(reason or ""),
            math.max(0, tonumber(wait_ms) or 0)
        ))
        return false, "combat cooldown."
    end

    local cooldown_ms = ACTION_INTERVAL_MS
    state.next_action_at = current_time + cooldown_ms

    local keybd_api = select(1, input_apis(ctx))

    local key_ok = true
    local pulse_mode = "driver_click"
    local post_err = nil

    local driver_api = type(ctx) == "table" and ctx.driver or driver
    if type(driver_api) == "table" and type(driver_api.keybd_click) == "function" then
        local ok, result = safe_call(driver_api.keybd_click, VK_W)
        key_ok = ok and result ~= false
        if key_ok then
            pulse_mode = "driver_click"
        end
    elseif type(keybd_api) == "table" and type(keybd_api.get_mode) == "function" then
        local current_key_mode = nil
        local mode_ok, mode_result = safe_call(keybd_api.get_mode)
        if mode_ok and type(mode_result) == "string" and mode_result ~= "" then
            current_key_mode = mode_result
        end
        if current_key_mode ~= "driver" and type(keybd_api.set_mode) == "function" then
            local set_ok, set_result = safe_call(keybd_api.set_mode, "driver")
            if set_ok and set_result ~= false then
                current_key_mode = "driver"
            end
        end
        if type(keybd_api.click) == "function" then
            local ok, result = safe_call(keybd_api.click, VK_W)
            key_ok = ok and result ~= false
            if key_ok then
                pulse_mode = current_key_mode == "driver" and "key_click_driver" or "key_click"
            end
        else
            key_ok = false
        end
    elseif type(driver_api) == "table" and type(driver_api.keybd_down) == "function" then
        local ok, result = safe_call(driver_api.keybd_down, VK_W)
        key_ok = ok and result ~= false
        if key_ok then
            pulse_mode = "driver_down"
            state.combat_key_down = true
            state.combat_key_release_at = current_time + ACTION_KEY_HOLD_MS
        end
    else
        key_ok = false
    end

    if not key_ok then
        local click_ok, click_err = try_background_key_click(ctx, VK_W, "combat pulse")
        post_err = click_err
        pulse_mode = "post_click"
        if click_ok then
            key_ok = true
        else
            log_throttled(ctx, "combat_pulse_direct_fallback", "info", LOG_THROTTLE_MS, string.format(
                "[Leveling] combat pulse direct key send failed, background click fallback also failed | reason=%s err=%s",
                tostring(reason or ""),
                tostring(click_err or "")
            ))
        end
    end

    local mouse_ok = true
    local mouse_mode = "mouse_post_click"
    local mouse_err = nil

    mouse_ok, mouse_err, mouse_mode = M.try_press_right_click_nonintrusive(ctx, "combat pulse")
    if not mouse_ok then
        log_throttled(ctx, "combat_pulse_mouse_failed", "info", LOG_THROTTLE_MS, string.format(
            "[Leveling] combat pulse right click failed | reason=%s err=%s",
            tostring(reason or ""),
            tostring(mouse_err or "")
        ))
    end

    if not key_ok or not mouse_ok then
        log_throttled(ctx, "combat_pulse_failed", "warn", LOG_THROTTLE_MS, string.format(
            "[Leveling] combat pulse failed | reason=%s key_ok=%s mouse_ok=%s mode=%s mouse_mode=%s post_err=%s mouse_err=%s",
            tostring(reason or ""),
            tostring(key_ok),
            tostring(mouse_ok),
            tostring(pulse_mode or ""),
            tostring(mouse_mode or ""),
            tostring(post_err or "")
            ,
            tostring(mouse_err or "")
        ))
        return false
    end

    if tostring(reason or "") == "follow_move" then
        state.next_follow_move_pulse_at = current_time + FOLLOW_MOVE_PULSE_INTERVAL_MS
    end

    log_throttled(ctx, "combat_pulse", "info", LOG_THROTTLE_MS, string.format(
        "[Leveling] combat pulse issued | reason=%s mode=%s mouse_mode=%s hold_ms=%d cooldown_ms=%d",
        tostring(reason or ""),
        tostring(pulse_mode or ""),
        tostring(mouse_mode or ""),
        ACTION_KEY_HOLD_MS,
        cooldown_ms
    ))
    return true
end

function M.clear_interaction_combat_guard(reason)
    if reason ~= nil
        and tostring(reason or "") ~= ""
        and state.interaction_combat_guard_key ~= nil
        and tostring(state.interaction_combat_guard_key or "") ~= tostring(reason or "")
    then
        return
    end
    state.interaction_combat_guard_key = nil
    state.interaction_combat_guard_started_at = 0
end

function M.maybe_issue_ambient_combat_pulse(ctx, current_time, player_x, player_y, reason, opts)
    opts = type(opts) == "table" and opts or {}
    current_time = tonumber(current_time) or now_ms(ctx)
    if tonumber(player_x) == nil or tonumber(player_y) == nil then
        return false, "player_pos_unavailable"
    end
    if M.is_task_combat_or_post_loot_active and M.is_task_combat_or_post_loot_active() then
        return false, "task_combat_active"
    end
    if opts.in_main_interface == false and opts.allow_when_main_interface_false ~= true then
        return false, "main_interface_false"
    end
    if type(state.task_entry_action_locked_cfg) == "table" and opts.allow_during_entry_action ~= true then
        return false, "task_entry_action_active"
    end
    if current_time < (tonumber(state.pause_combat_until) or 0) then
        return false, "combat_pause"
    end
    if current_time < (tonumber(state.next_ambient_combat_scan_at) or 0) then
        return false, "ambient_scan_cooldown"
    end
    state.next_ambient_combat_scan_at = current_time + (tonumber(M.AMBIENT_COMBAT_WAIT_SCAN_INTERVAL_MS) or 250)

    local nearby_monsters, monster_err = M.find_task_monsters(ctx, current_time, player_x, player_y)
    if not (nearby_monsters and tonumber(nearby_monsters.count) and nearby_monsters.count > 0) then
        if monster_err then
            log_throttled(ctx, "ambient_combat_scan_miss_" .. tostring(reason or ""), "info", MONSTER_SCAN_LOG_INTERVAL_MS,
                "[Leveling] ambient combat scan found no nearby target | reason=" .. tostring(reason or "")
                    .. " err=" .. tostring(monster_err))
        end
        return false, monster_err or "no_nearby_monster"
    end

    local nearest_monster = nearby_monsters.nearest or {}
    local should_pulse, pulse_reason = should_issue_nearby_monster_pulse(current_time)
    if not should_pulse then
        log_throttled(ctx, "ambient_combat_pulse_deferred_" .. tostring(reason or ""), "info", MONSTER_SCAN_LOG_INTERVAL_MS, string.format(
            "[Leveling] ambient combat pulse deferred | reason=%s nearest_distance=%.2f count=%d gate=%s",
            tostring(reason or ""),
            tonumber(nearest_monster.distance) or 0,
            tonumber(nearby_monsters.count) or 0,
            tostring(pulse_reason or "")
        ))
        return false, pulse_reason or "pulse_deferred"
    end

    local pulse_ok, pulse_err = issue_combat_pulse(ctx, current_time, "ambient_" .. tostring(reason or "wait"), true)
    if pulse_ok then
        log_throttled(ctx, "ambient_combat_pulse_issued_" .. tostring(reason or ""), "info", MONSTER_SCAN_LOG_INTERVAL_MS, string.format(
            "[Leveling] ambient combat pulse issued | reason=%s nearest_distance=%.2f count=%d",
            tostring(reason or ""),
            tonumber(nearest_monster.distance) or 0,
            tonumber(nearby_monsters.count) or 0
        ))
        return true, nil
    end

    log_throttled(ctx, "ambient_combat_pulse_blocked_" .. tostring(reason or ""), "info", MONSTER_SCAN_LOG_INTERVAL_MS, string.format(
        "[Leveling] ambient combat pulse blocked | reason=%s nearest_distance=%.2f count=%d err=%s",
        tostring(reason or ""),
        tonumber(nearest_monster.distance) or 0,
        tonumber(nearby_monsters.count) or 0,
        tostring(pulse_err or "")
    ))
    return false, pulse_err or "pulse_blocked"
end

function M.maybe_guard_interaction_with_combat(ctx, current_time, player_x, player_y, reason, opts)
    opts = type(opts) == "table" and opts or {}
    current_time = tonumber(current_time) or now_ms(ctx)
    local guard_key = tostring(reason or "interaction")
    if tostring(state.interaction_combat_guard_skip_key or "") == guard_key
        and current_time < (tonumber(state.interaction_combat_guard_skip_until) or 0)
    then
        return false
    end
    if tonumber(player_x) == nil or tonumber(player_y) == nil then
        M.clear_interaction_combat_guard(reason)
        return false
    end
    if current_time < (tonumber(state.pause_combat_until) or 0) then
        return false
    end

    local nearby_monsters, monster_err = M.find_task_monsters(ctx, current_time, player_x, player_y)
    if not (nearby_monsters and tonumber(nearby_monsters.count) and nearby_monsters.count > 0) then
        M.clear_interaction_combat_guard(reason)
        return false
    end

    local nearest_monster = nearby_monsters.nearest or {}
    local nearest_distance = tonumber(nearest_monster.distance)
    local guard_distance = tonumber(opts.distance) or tonumber(M.INTERACTION_COMBAT_GUARD_DISTANCE) or 520
    if nearest_distance == nil or nearest_distance > guard_distance then
        M.clear_interaction_combat_guard(reason)
        return false
    end

    if tostring(state.interaction_combat_guard_key or "") ~= guard_key then
        state.interaction_combat_guard_key = guard_key
        state.interaction_combat_guard_started_at = current_time
        logger(ctx).info(string.format(
            "[Leveling] interaction combat guard armed | reason=%s nearest_distance=%.2f count=%d max_ms=%d",
            guard_key,
            nearest_distance,
            tonumber(nearby_monsters.count) or 0,
            tonumber(opts.max_ms) or tonumber(M.INTERACTION_COMBAT_GUARD_MAX_MS) or 1800
        ))
    end

    local started_at = tonumber(state.interaction_combat_guard_started_at) or current_time
    local max_ms = math.max(0, tonumber(opts.max_ms) or tonumber(M.INTERACTION_COMBAT_GUARD_MAX_MS) or 1800)
    local elapsed_ms = math.max(0, current_time - started_at)
    if elapsed_ms >= max_ms then
        logger(ctx).info(string.format(
            "[Leveling] interaction combat guard released by timeout | reason=%s elapsed_ms=%d nearest_distance=%.2f count=%d",
            guard_key,
            elapsed_ms,
            nearest_distance,
            tonumber(nearby_monsters.count) or 0
        ))
        M.clear_interaction_combat_guard(reason)
        state.interaction_combat_guard_skip_key = guard_key
        state.interaction_combat_guard_skip_until = current_time + math.max(1000, tonumber(opts.skip_after_timeout_ms) or 3500)
        return false
    end

    state.stage = "interaction_combat_guard"
    hold_navigation(ctx, current_time, "interaction_combat_guard_" .. guard_key)
    M.maybe_issue_ambient_combat_pulse(ctx, current_time, player_x, player_y, "interaction_guard_" .. guard_key, {
        allow_when_main_interface_false = opts.allow_when_main_interface_false == true,
        allow_during_entry_action = opts.allow_during_entry_action == true
    })
    log_throttled(ctx, "interaction_combat_guard_wait_" .. guard_key, "info", MONSTER_SCAN_LOG_INTERVAL_MS, string.format(
        "[Leveling] interaction delayed by nearby monster | reason=%s elapsed_ms=%d/%d nearest_distance=%.2f count=%d",
        guard_key,
        elapsed_ms,
        max_ms,
        nearest_distance,
        tonumber(nearby_monsters.count) or 0
    ))
    return true
end

function M.maybe_issue_route_point_action_route_combat(ctx, current_time, player_x, player_y, point_distance, active_key)
    local action_key = tostring(active_key or "")
    local nearby_monsters, monster_err = M.find_task_monsters(ctx, current_time, player_x, player_y)
    if nearby_monsters and tonumber(nearby_monsters.count) and nearby_monsters.count > 0 then
        local nearest_monster = nearby_monsters.nearest or {}
        log_throttled(
            ctx,
            "route_point_action_route_nearby_monster_" .. action_key,
            "info",
            MONSTER_SCAN_LOG_INTERVAL_MS,
            string.format(
                "[Leveling] recorded route nearby monsters detected | key=%s count=%d total=%d nearest=%s player_distance=%.2f",
                action_key,
                tonumber(nearby_monsters.count) or 0,
                tonumber(nearby_monsters.total_count) or tonumber(nearby_monsters.count) or 0,
                tostring(nearest_monster.label or ""),
                tonumber(nearest_monster.distance) or 0
            )
        )

        local should_pulse, pulse_reason = should_issue_nearby_monster_pulse(current_time)
        if should_pulse then
            local pulse_ok, pulse_err = issue_combat_pulse(ctx, current_time, "nearby_monster", true)
            if pulse_ok then
                logger(ctx).info(string.format(
                    "[Leveling] recorded route nearby monster pulse issued | key=%s",
                    action_key
                ))
                return true
            end
            log_throttled(
                ctx,
                "route_point_action_route_nearby_monster_blocked_" .. action_key,
                "info",
                MONSTER_SCAN_LOG_INTERVAL_MS,
                string.format(
                    "[Leveling] recorded route nearby monster pulse blocked | key=%s nearest_distance=%.2f count=%d reason=%s",
                    action_key,
                    tonumber(nearest_monster.distance) or 0,
                    tonumber(nearby_monsters.count) or 0,
                    tostring(pulse_err or "")
                )
            )
        else
            log_throttled(
                ctx,
                "route_point_action_route_nearby_monster_deferred_" .. action_key,
                "info",
                MONSTER_SCAN_LOG_INTERVAL_MS,
                string.format(
                    "[Leveling] recorded route nearby monster pulse deferred | key=%s nearest_distance=%.2f count=%d reason=%s",
                    action_key,
                    tonumber(nearest_monster.distance) or 0,
                    tonumber(nearby_monsters.count) or 0,
                    tostring(pulse_reason or "")
                )
            )
        end
    elseif monster_err then
        log_throttled(
            ctx,
            "route_point_action_route_monster_scan_miss_" .. action_key,
            "info",
            MONSTER_SCAN_LOG_INTERVAL_MS,
            "[Leveling] recorded route monster scan found no nearby target: " .. tostring(monster_err)
        )
    end

    local should_pulse = false
    local pulse_reason = nil
    if type(point_distance) == "number"
        and point_distance > FOLLOW_MOVE_PULSE_MIN_DISTANCE
        and current_time >= (tonumber(state.next_follow_move_pulse_at) or 0)
    then
        local follow_allowed, follow_reason = should_issue_combat_pulse(current_time, point_distance, false)
        if follow_allowed then
            should_pulse = true
            pulse_reason = "follow_move"
        else
            pulse_reason = follow_reason
        end
    end

    if not should_pulse then
        should_pulse, pulse_reason = should_issue_combat_pulse(current_time, point_distance, false)
    end

    if should_pulse then
        local pulse_ok, pulse_err = issue_combat_pulse(ctx, current_time, pulse_reason)
        if pulse_ok then
            logger(ctx).info(string.format(
                "[Leveling] recorded route combat pulse issued | key=%s reason=%s distance=%.2f",
                action_key,
                tostring(pulse_reason or ""),
                tonumber(point_distance) or 0
            ))
            return true
        end
        log_throttled(
            ctx,
            "route_point_action_route_pulse_blocked_" .. action_key,
            "info",
            MONSTER_SCAN_LOG_INTERVAL_MS,
            string.format(
                "[Leveling] recorded route combat pulse blocked | key=%s reason=%s distance=%.2f err=%s",
                action_key,
                tostring(pulse_reason or ""),
                tonumber(point_distance) or 0,
                tostring(pulse_err or "")
            )
        )
        return false
    end

    log_throttled(
        ctx,
        "route_point_action_route_pulse_deferred_" .. action_key,
        "info",
        MONSTER_SCAN_LOG_INTERVAL_MS,
        string.format(
            "[Leveling] recorded route combat pulse deferred | key=%s distance=%.2f reason=%s",
            action_key,
            tonumber(point_distance) or 0,
            tostring(pulse_reason or "")
        )
    )
    return false
end

local function maybe_consume_potion(ctx, current_time, hp, max_hp, hp_ratio, opts)
    opts = opts or {}

    if opts.force_refresh == true or hp == nil or max_hp == nil or hp_ratio == nil then
        _, hp, max_hp, hp_ratio = refresh_player_status(ctx, current_time, opts.force_refresh == true)
    end

    local hotkey_vk = tonumber(opts.vk) or VK_Q
    local hotkey_name = tostring(opts.hotkey_name or (hotkey_vk == 0x45 and "E" or "Q"))
    local threshold_ratio = tonumber(opts.threshold_ratio)
        or (hotkey_vk == 0x45 and 0.45 or POTION_THRESHOLD_RATIO)
    local last_used_field = tostring(opts.last_used_field or (hotkey_vk == 0x45 and "last_potion_e_at" or "last_potion_q_at"))

    local potion_cooldown_ms = POTION_COOLDOWN_MS
    if type(hp_ratio) == "number" and hp_ratio <= 0.40 then
        potion_cooldown_ms = 900
    end
    if current_time - (tonumber(state[last_used_field]) or 0) < potion_cooldown_ms then
        return false
    end

    if type(hp_ratio) ~= "number" or hp_ratio > threshold_ratio then
        return false
    end

    local ok, err, mode = nil, nil, nil
    if opts.nonintrusive == true then
        ok, err, mode = M.try_press_potion_hotkey(ctx, hotkey_vk, "leveling potion " .. hotkey_name)
    else
        ok, err = press_keyboard_hotkey(ctx, current_time, hotkey_vk, "leveling potion " .. hotkey_name)
        mode = ok and "default" or nil
    end
    if not ok then
        log_throttled(ctx, "potion_failed_" .. hotkey_name, "warn", LOG_THROTTLE_MS,
            string.format("[Leveling] low hp potion %s failed: %s", hotkey_name, tostring(err)))
        return false, err
    end

    state.last_potion_at = current_time
    state[last_used_field] = current_time
    logger(ctx).info(string.format(
        "[Leveling] potion used | key=%s hp=%s max_hp=%s ratio=%.2f threshold=%.2f mode=%s source=%s cooldown_ms=%d",
        hotkey_name,
        hp ~= nil and string.format("%.2f", tonumber(hp) or 0) or "nil",
        max_hp ~= nil and string.format("%.2f", tonumber(max_hp) or 0) or "nil",
        tonumber(hp_ratio) or 0,
        tonumber(threshold_ratio) or 0,
        tostring(mode or ""),
        opts.watch == true and "watch" or "default",
        tonumber(potion_cooldown_ms) or 0
    ))
    return true
end

M.maybe_handle_potion_watch = function(ctx, current_time, hp, max_hp, hp_ratio)
    current_time = tonumber(current_time) or now_ms(ctx)
    if current_time < (tonumber(state.next_potion_watch_at) or 0) then
        return false
    end

    state.next_potion_watch_at = current_time + 120

    local last_info_at = tonumber(state.last_player_info_at) or 0
    local info_age_ms = last_info_at > 0 and math.max(0, current_time - last_info_at) or math.huge
    local force_refresh = hp == nil
        or max_hp == nil
        or hp_ratio == nil
        or info_age_ms >= 160
        or (type(hp_ratio) == "number" and hp_ratio <= 0.72)

    local common_opts = {
        nonintrusive = true,
        force_refresh = force_refresh,
        watch = true
    }

    local used_q = maybe_consume_potion(ctx, current_time, hp, max_hp, hp_ratio, {
        nonintrusive = common_opts.nonintrusive,
        force_refresh = common_opts.force_refresh,
        watch = common_opts.watch,
        vk = VK_Q,
        hotkey_name = "Q",
        threshold_ratio = POTION_THRESHOLD_RATIO,
        last_used_field = "last_potion_q_at"
    })
    if used_q then
        return true
    end

    return maybe_consume_potion(ctx, current_time, hp, max_hp, hp_ratio, {
        nonintrusive = common_opts.nonintrusive,
        force_refresh = common_opts.force_refresh,
        watch = common_opts.watch,
        vk = 0x45,
        hotkey_name = "E",
        threshold_ratio = 0.45,
        last_used_field = "last_potion_e_at"
    })
end

